import { TAU, mulberry32 } from '../core/math';
import { drawHunter, drawMimika } from '../render/actors';
import { PALETTE } from '../render/palette';
import { SPRITE_PAD, getBlockSprite } from '../render/sprites';
import type { MaterialId } from '../config/materials';
import { h } from './dom';

/** dimensioni logiche dell'illustrazione */
const W = 480;
const H = 190;
const GROUND = 166;

interface Confetto { x: number; y: number; vy: number; s: number; rot: number; vr: number; color: string }

/**
 * Illustrazione animata della schermata di vittoria, disegnata con gli stessi personaggi del gioco.
 * Difesa (menta): Mimika esulta sulla fortezza intatta, il Cacciatore si abbatte.
 * Attacco (corallo): il Cacciatore esulta tra le macerie, Mimika è presa (occhio a spirale).
 * Si ferma da sola quando la schermata viene rimossa dal DOM.
 */
export function victoryArt(role: 'atk' | 'def'): HTMLCanvasElement {
  const canvas = h('canvas', { class: `victory-art ${role}`, 'aria-hidden': 'true' });
  const color = role === 'def' ? PALETTE.defender : PALETTE.attacker;
  const rng = mulberry32(role === 'def' ? 5 : 9);
  const confetti: Confetto[] = Array.from({ length: 34 }, (_, i) => ({
    x: rng() * W, y: rng() * H, vy: 18 + rng() * 30, s: 3 + rng() * 4, rot: rng() * TAU, vr: (rng() - 0.5) * 6,
    color: i % 3 === 0 ? PALETTE.gold : i % 3 === 1 ? color : '#fff3d6',
  }));
  let started = false;
  let last = 0;
  const frame = (now: number) => {
    if (started && !canvas.isConnected) return;
    started = true;
    const dt = Math.min(0.05, (now - (last || now)) / 1000);
    last = now;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const cw = canvas.clientWidth || W;
    const ch = canvas.clientHeight || H;
    if (canvas.width !== Math.round(cw * dpr) || canvas.height !== Math.round(ch * dpr)) {
      canvas.width = Math.round(cw * dpr);
      canvas.height = Math.round(ch * dpr);
    }
    const g = canvas.getContext('2d')!;
    // scala sull'altezza; lo spazio in più ai lati (pannelli larghi) lo riempiono cielo e colline
    const k = ch / H;
    const ext = Math.max(0, (cw / k - W) / 2);
    g.setTransform(dpr * k, 0, 0, dpr * k, dpr * ext * k, 0);
    g.clearRect(-ext - 10, -10, W + ext * 2 + 20, H + 20);
    paint(g, now / 1000, dt, role, color, confetti, ext);
    requestAnimationFrame(frame);
  };
  requestAnimationFrame(frame);
  return canvas;
}

function paint(g: CanvasRenderingContext2D, t: number, dt: number, role: 'atk' | 'def', color: string, confetti: Confetto[], ext: number): void {
  const x0 = -ext - 10, x1 = W + ext + 10;
  // raggi che ruotano lentamente (carta a ventaglio)
  g.save();
  g.translate(W / 2, GROUND - 40);
  g.rotate(t * 0.15);
  g.fillStyle = color;
  for (let i = 0; i < 14; i++) {
    g.globalAlpha = i % 2 ? 0.1 : 0.18;
    g.beginPath();
    g.moveTo(0, 0);
    g.arc(0, 0, 320, (i / 14) * TAU, ((i + 0.5) / 14) * TAU);
    g.closePath();
    g.fill();
  }
  g.restore();
  // colline di carta
  g.globalAlpha = 1;
  for (const [y, c, amp] of [[GROUND - 26, PALETTE.mid, 14], [GROUND - 8, PALETTE.near, 8]] as const) {
    g.fillStyle = c;
    g.beginPath();
    g.moveTo(x0, H + 10);
    for (let x = x0; x <= x1; x += 10) g.lineTo(x, y - Math.sin(x * 0.02 + y) * amp);
    g.lineTo(x1, H + 10);
    g.closePath();
    g.fill();
  }
  g.fillStyle = PALETTE.grass;
  g.fillRect(x0, GROUND, x1 - x0, H - GROUND);
  g.fillStyle = PALETTE.grassTop;
  g.fillRect(x0, GROUND - 1, x1 - x0, 4);

  if (role === 'def') {
    // fortezza intatta, Mimika in cima che esulta, Cacciatore abbattuto in disparte
    block(g, 'wood', 150, GROUND - 40, 40, 40, 0, 0);
    block(g, 'stone', 190, GROUND - 40, 100, 40, 0, 0);
    block(g, 'metal', 290, GROUND - 40, 40, 40, 0, 0);
    block(g, 'glass', 330, GROUND - 20, 20, 20, 0, 0);
    drawMimika(g, 240, GROUND - 72, t, { style: 'live', scale: 1.9, cheer: 1 });
    drawHunter(g, t, { at: { x: 420, y: GROUND }, scale: 0.62, slump: 1 });
  } else {
    // macerie, Cacciatore che esulta, Mimika presa
    block(g, 'stone', 300, GROUND - 22, 80, 40, 0.25, 2);
    block(g, 'wood', 360, GROUND - 16, 40, 40, -0.5, 2);
    block(g, 'glass', 405, GROUND - 12, 40, 20, 0.9, 1);
    block(g, 'metal', 268, GROUND - 14, 40, 20, -0.15, 2);
    drawMimika(g, 352, GROUND - 58, t, { style: 'live', scale: 1.5, dizzy: true, scared: 0.4 });
    drawHunter(g, t, { at: { x: 170, y: GROUND }, scale: 1.05, cheer: 1 });
  }

  // coriandoli
  for (const c of confetti) {
    c.y += c.vy * dt;
    c.rot += c.vr * dt;
    if (c.y > H + 8) c.y = -8;
    g.save();
    g.translate(x0 + (c.x / W) * (x1 - x0) + Math.sin(t * 2 + c.rot) * 6, c.y);
    g.rotate(c.rot);
    g.fillStyle = c.color;
    g.fillRect(-c.s / 2, -c.s / 4, c.s, c.s / 2);
    g.restore();
  }
}

function block(g: CanvasRenderingContext2D, mat: MaterialId, x: number, y: number, w: number, hgt: number, angle: number, crack: number): void {
  const s = getBlockSprite(mat, w, hgt, crack, Math.round(x * 13 + y));
  g.save();
  g.translate(x + w / 2, y + hgt / 2);
  g.rotate(angle);
  g.drawImage(s, -w / 2 - SPRITE_PAD, -hgt / 2 - SPRITE_PAD, w + SPRITE_PAD * 2, hgt + SPRITE_PAD * 2);
  g.restore();
}
