import { MATERIALS, MATERIAL_ORDER, type MaterialId } from '../config/materials';
import { MODES, type ModeId } from '../config/modes';
import { WORLD, inZone, type Cell } from '../config/world';

/**
 * Blueprint = il progetto della fortezza, puro dato serializzabile.
 * È ciò che viaggia nei link di sfida e (Step 2) sul DataChannel P2P.
 * Coordinate in celle: col da sinistra della zona, row dal suolo verso l'alto.
 */
export interface PlacedBlock {
  mat: MaterialId;
  col: number;
  row: number;
  w: number;
  h: number;
}

export interface Blueprint {
  mode: ModeId;
  author: string;
  blocks: PlacedBlock[];
  core: Cell;
  decoys: Cell[];
}

export function emptyBlueprint(mode: ModeId, author: string): Blueprint {
  return { mode, author, blocks: [], core: { col: Math.floor(WORLD.ZONE_COLS / 2), row: 0 }, decoys: [] };
}

export const blockCost = (b: PlacedBlock) => MATERIALS[b.mat].cost * b.w * b.h;
export const blueprintCost = (bp: Blueprint) => bp.blocks.reduce((s, b) => s + blockCost(b), 0);

const covers = (b: PlacedBlock, col: number, row: number) =>
  col >= b.col && col < b.col + b.w && row >= b.row && row < b.row + b.h;

export const blockIndexAt = (bp: Blueprint, col: number, row: number) =>
  bp.blocks.findIndex((b) => covers(b, col, row));

export const decoyIndexAt = (bp: Blueprint, col: number, row: number) =>
  bp.decoys.findIndex((d) => d.col === col && d.row === row);

export function isCellFree(bp: Blueprint, col: number, row: number): boolean {
  if (bp.core.col === col && bp.core.row === row) return false;
  return blockIndexAt(bp, col, row) < 0 && decoyIndexAt(bp, col, row) < 0;
}

export function canPlaceBlock(bp: Blueprint, b: PlacedBlock): boolean {
  if (!inZone(b.col, b.row, b.w, b.h)) return false;
  for (let c = b.col; c < b.col + b.w; c++)
    for (let r = b.row; r < b.row + b.h; r++) if (!isCellFree(bp, c, r)) return false;
  return true;
}

// ---------------------------------------------------------------------------
// Formato compatto "wire" (per link e rete). Versionato: v=1.
// b = [indiceMateriale, col, row, w, h]
// ---------------------------------------------------------------------------
export interface WireBlueprint {
  v: 1;
  m: ModeId;
  a: string;
  b: number[][];
  c: [number, number];
  d: number[][];
}

export function toWire(bp: Blueprint): WireBlueprint {
  return {
    v: 1,
    m: bp.mode,
    a: bp.author,
    b: bp.blocks.map((b) => [MATERIAL_ORDER.indexOf(b.mat), b.col, b.row, b.w, b.h]),
    c: [bp.core.col, bp.core.row],
    d: bp.decoys.map((d) => [d.col, d.row]),
  };
}

const isInt = (n: unknown): n is number => typeof n === 'number' && Number.isInteger(n);

/** Decodifica difensiva: un link manomesso non deve mai rompere il gioco. */
export function fromWire(raw: unknown): Blueprint | null {
  const w = raw as Partial<WireBlueprint> | null;
  if (!w || w.v !== 1 || !w.m || !(w.m in MODES)) return null;
  const mode = MODES[w.m];
  if (!Array.isArray(w.c) || !isInt(w.c[0]) || !isInt(w.c[1]) || !inZone(w.c[0], w.c[1])) return null;
  const bp = emptyBlueprint(w.m, String(w.a ?? 'Anonimo').slice(0, 16));
  bp.core = { col: w.c[0], row: w.c[1] };
  for (const d of Array.isArray(w.d) ? w.d : []) {
    if (bp.decoys.length >= mode.decoys) break;
    if (Array.isArray(d) && isInt(d[0]) && isInt(d[1]) && inZone(d[0], d[1]) && isCellFree(bp, d[0], d[1]))
      bp.decoys.push({ col: d[0], row: d[1] });
  }
  let spent = 0;
  for (const item of Array.isArray(w.b) ? w.b : []) {
    if (!Array.isArray(item) || !item.every(isInt)) continue;
    const [mi, col, row, bw, bh] = item;
    const mat = MATERIAL_ORDER[mi];
    if (!mat || bw < 1 || bh < 1 || bw > 3 || bh > 3) continue;
    const block: PlacedBlock = { mat, col, row, w: bw, h: bh };
    if (spent + blockCost(block) > mode.budget || !canPlaceBlock(bp, block)) continue;
    spent += blockCost(block);
    bp.blocks.push(block);
  }
  return bp;
}

/** Fortezza dimostrativa per lo sfondo del menu. */
export function demoBlueprint(): Blueprint {
  const bp = emptyBlueprint('tactical', 'Mimika');
  const B = (mat: MaterialId, col: number, row: number, w: number, h: number) => bp.blocks.push({ mat, col, row, w, h });
  B('stone', 3, 0, 2, 1); B('stone', 5, 0, 2, 1); B('stone', 9, 0, 2, 1); B('stone', 11, 0, 2, 1);
  B('wood', 3, 1, 1, 3); B('stone', 4, 1, 1, 1); B('glass', 4, 2, 1, 1); B('stone', 4, 3, 1, 1);
  B('wood', 12, 1, 1, 3); B('stone', 11, 1, 1, 1); B('glass', 11, 2, 1, 1); B('stone', 11, 3, 1, 1);
  B('metal', 3, 4, 3, 1); B('metal', 10, 4, 3, 1); B('wood', 6, 4, 2, 1); B('wood', 8, 4, 2, 1);
  B('moss', 7, 0, 2, 1); B('glass', 7, 3, 2, 1);
  B('stone', 6, 5, 1, 1); B('stone', 9, 5, 1, 1); B('moss', 7, 5, 2, 1);
  B('wood', 3, 5, 1, 2); B('wood', 12, 5, 1, 2); B('glass', 7, 6, 2, 1);
  bp.core = { col: 8, row: 1 };
  bp.decoys = [{ col: 5, row: 1 }];
  return bp;
}
