import { packText, unpackText } from './codec';

/**
 * PeerLink: connessione WebRTC DataChannel con signaling MANUALE (nessun server).
 * Implementa il flusso del documento p2p-webrtc-signaling-whatsapp.pdf (cap. 3 e 5):
 *
 *   A: createOffer()  -> codice/link #o=...  --(WhatsApp/QR/copia)-->  B
 *   B: acceptOffer()  -> codice/link #a=...  --(WhatsApp/QR/copia)-->  A
 *   A: acceptAnswer() -> DataChannel aperto su entrambi i lati
 *
 * Usato dalla lobby del duello live (game/LiveDuel.ts); dettagli in docs/04-P2P-NETWORKING.md.
 */
export type PeerState = 'idle' | 'gathering' | 'waiting-answer' | 'connecting' | 'connected' | 'unstable' | 'closed' | 'failed';

export const DEFAULT_ICE: RTCIceServer[] = [
  { urls: 'stun:stun.l.google.com:19302' },
  { urls: 'stun:stun.cloudflare.com:3478' },
  ...turnFromEnv(),
];

/**
 * Server TURN facoltativo (ponte quando il collegamento diretto non riesce, es. due telefoni su dati mobili):
 * VITE_TURN_URLS="turn:host:80,turns:host:443?transport=tcp", VITE_TURN_USERNAME, VITE_TURN_CREDENTIAL.
 * Vedi docs/04-P2P-NETWORKING.md.
 */
function turnFromEnv(): RTCIceServer[] {
  const urls = (import.meta.env.VITE_TURN_URLS ?? '').split(',').map((u) => u.trim()).filter(Boolean);
  return urls.length ? [{ urls, username: import.meta.env.VITE_TURN_USERNAME, credential: import.meta.env.VITE_TURN_CREDENTIAL }] : [];
}

export interface PeerLinkOptions {
  iceServers?: RTCIceServer[];
  /** rete di sicurezza: alcune reti non completano mai la raccolta ICE (cap. 5.3) */
  gatherTimeoutMs?: number;
}

export class PeerLink {
  readonly pc: RTCPeerConnection;
  private channel: RTCDataChannel | null = null;
  private readonly gatherTimeoutMs: number;

  onState?: (state: PeerState, detail?: string) => void;
  onMessage?: (msg: unknown) => void;
  onOpen?: () => void;
  onClose?: () => void;

  constructor(opts: PeerLinkOptions = {}) {
    this.gatherTimeoutMs = opts.gatherTimeoutMs ?? 5000;
    this.pc = new RTCPeerConnection({ iceServers: opts.iceServers ?? DEFAULT_ICE });
    this.pc.onconnectionstatechange = () => {
      const s = this.pc.connectionState;
      if (s === 'connected') this.onState?.('connected');
      else if (s === 'failed') this.onState?.('failed', 'Connessione diretta impossibile (NAT/firewall).');
      // 'disconnected' può essere momentaneo (cambio rete, tab in background): lo decide il keep-alive
      else if (s === 'disconnected') this.onState?.('unstable');
      else if (s === 'closed') this.onState?.('closed');
    };
  }

  /** Lato A (chi invita). Il DataChannel lo crea solo chi fa l'offerta. */
  async createOffer(): Promise<string> {
    this.setupChannel(this.pc.createDataChannel('mimika', { ordered: true }));
    this.onState?.('gathering');
    await this.pc.setLocalDescription(await this.pc.createOffer());
    await this.waitIce();
    this.onState?.('waiting-answer');
    return packText(this.pc.localDescription!.sdp);
  }

  /** Lato B (chi riceve l'invito): restituisce il codice di risposta da rimandare ad A. */
  async acceptOffer(offerCode: string): Promise<string> {
    this.pc.ondatachannel = (e) => this.setupChannel(e.channel);
    await this.pc.setRemoteDescription({ type: 'offer', sdp: await unpackText(offerCode) });
    this.onState?.('gathering');
    await this.pc.setLocalDescription(await this.pc.createAnswer());
    await this.waitIce();
    this.onState?.('connecting');
    return packText(this.pc.localDescription!.sdp);
  }

  /** Lato A: applica la risposta ricevuta. Da fare entro 1-2 minuti (le mappature NAT scadono). */
  async acceptAnswer(answerCode: string): Promise<void> {
    await this.pc.setRemoteDescription({ type: 'answer', sdp: await unpackText(answerCode) });
    this.onState?.('connecting');
  }

  get isOpen(): boolean {
    return this.channel?.readyState === 'open';
  }

  send(msg: unknown): boolean {
    if (!this.isOpen) return false;
    this.channel!.send(JSON.stringify(msg));
    return true;
  }

  close(): void {
    if (this.channel) this.channel.onclose = null;
    this.channel?.close();
    this.pc.close();
  }

  private setupChannel(ch: RTCDataChannel): void {
    this.channel = ch;
    ch.onopen = () => this.onOpen?.();
    ch.onclose = () => this.onClose?.();
    ch.onmessage = (e) => {
      if (typeof e.data !== 'string') return;
      try {
        this.onMessage?.(JSON.parse(e.data));
      } catch {
        /* messaggio malformato: ignorato */
      }
    };
  }

  private waitIce(): Promise<void> {
    return new Promise((resolve) => {
      if (this.pc.iceGatheringState === 'complete') return resolve();
      const check = () => {
        if (this.pc.iceGatheringState === 'complete') resolve();
      };
      this.pc.addEventListener('icegatheringstatechange', check);
      setTimeout(resolve, this.gatherTimeoutMs);
    });
  }
}

/**
 * Inoltro automatico della risposta alla scheda originale (cap. 5.6): quando A tocca il link #a=...
 * si apre una nuova scheda; questa lo passa via BroadcastChannel alla scheda che detiene la PeerConnection,
 * che conferma con un "ack". Se non funziona (webview isolata, altro browser), resta sempre l'incolla manuale.
 */
const SIGNAL_CHANNEL = 'mimika-signaling';

type SignalMsg = { type: 'answer'; code: string } | { type: 'ack' };

/** true se una scheda in attesa ha confermato di aver ricevuto la risposta. */
export function forwardAnswerToOriginalTab(answerCode: string, timeoutMs = 1200): Promise<boolean> {
  if (typeof BroadcastChannel === 'undefined') return Promise.resolve(false);
  const bc = new BroadcastChannel(SIGNAL_CHANNEL);
  return new Promise((resolve) => {
    const done = (ok: boolean) => {
      clearTimeout(timer);
      bc.close();
      resolve(ok);
    };
    const timer = setTimeout(() => done(false), timeoutMs);
    bc.onmessage = (e) => (e.data as SignalMsg)?.type === 'ack' && done(true);
    bc.postMessage({ type: 'answer', code: answerCode } satisfies SignalMsg);
  });
}

/** cb restituisce true se ha accettato la risposta (allora la scheda mittente riceve l'ack). */
export function listenForwardedAnswers(cb: (answerCode: string) => boolean): () => void {
  if (typeof BroadcastChannel === 'undefined') return () => {};
  const bc = new BroadcastChannel(SIGNAL_CHANNEL);
  bc.onmessage = (e) => {
    const msg = e.data as SignalMsg;
    if (msg?.type === 'answer' && typeof msg.code === 'string' && cb(msg.code)) bc.postMessage({ type: 'ack' } satisfies SignalMsg);
  };
  return () => bc.close();
}
