import Matter from 'matter-js';
import { MODES } from '../config/modes';
import { TUNING, WEAPONS, WEAPON_ORDER, type WeaponId } from '../config/weapons';
import { WORLD } from '../config/world';
import { formatTime, lerp, rand } from '../core/math';
import type { Game } from '../game/Game';
import type { Blueprint } from '../game/blueprint';
import { World, type Entity, type Vec } from '../game/World';
import type { EventMessage, NetEvent, SnapMessage } from '../net/protocol';
import { drawHunter, drawLauncher, drawStormMarker } from '../render/actors';
import { drawWorld } from '../render/scenery';
import { h, icon } from '../ui/dom';
import { ICONS } from '../ui/icons';
import type { CamFocus } from '../render/Renderer';
import { battleFocus, drawEffects, hunterMood, mimikaMood, newFxState, playEffect, updateEffects } from './effects';
import type { Scene } from './Scene';

const { Body } = Matter;

/** ritardo di riproduzione: tiene sempre almeno uno snapshot "nel futuro" da cui interpolare */
const PLAY_DELAY = 140;
/** oltre questo scarto l'orologio salta invece di rincorrere */
const RESYNC_MS = 600;
const WIND_MS = 2800;

interface Sample {
  t: number;
  x: number;
  y: number;
  a: number;
  hp: number;
}

export interface SpectatorOptions {
  attacker: string;
  defender: string;
  /** latenza corrente in ms (null = non ancora misurata) */
  rtt: () => number | null;
  onQuit: () => void;
}

/**
 * Il difensore guarda l'assedio in diretta. Nessuna fisica locale: il World serve solo da contenitore
 * dei corpi da disegnare; posizioni, crolli ed effetti arrivano dall'attaccante (snapshot + eventi)
 * e vengono riprodotti con un piccolo ritardo, interpolando tra uno snapshot e l'altro.
 */
export class SpectatorScene implements Scene {
  readonly mood = 'siege';
  private readonly world: World;
  private readonly byNid = new Map<number, Entity>();
  private readonly tracks = new Map<number, Sample[]>();
  private readonly incoming = new Map<number, WeaponId>();
  private readonly removals: { t: number; nid: number }[] = [];
  private readonly events: EventMessage[] = [];
  private readonly statuses: Pick<SnapMessage, 'tick' | 's' | 'a' | 'f'>[] = [];
  private readonly fx = newFxState('def');
  /** tempo di riproduzione, nella scala dei tick dell'attaccante (-1 = in attesa del primo snapshot) */
  private clock = -1;
  private latestTick = -1;
  private latestAt = 0;
  private pouch: Vec | null = null;
  private loaded: WeaponId | null = null;
  private stormX: number | null = null;
  private windMs = 0;
  private pingTimer = 0;
  private hud!: { timer: HTMLElement; hint: HTMLElement; stats: HTMLElement; ping: HTMLElement };

  constructor(private game: Game, private bp: Blueprint, private opts: SpectatorOptions) {
    // stesso Blueprint (passato da fromWire) dell'attaccante => stessi nid nello stesso ordine
    this.world = new World(bp);
    for (const e of this.world.entities.values()) this.byNid.set(e.nid, e);
  }

  // ------------------------------------------------------------------ ciclo di vita

  enter(): void {
    this.game.ui.hud(this.buildHud());
    this.setHint(`${this.opts.attacker} sta studiando la tua fortezza…`);
  }

  exit(): void {
    this.game.ui.hud(null);
  }

  /** Messaggi di gioco dall'attaccante (inoltrati da LiveDuel). */
  feed(msg: SnapMessage | EventMessage): void {
    if (!Number.isFinite(msg.tick)) return;
    if (msg.tick >= this.latestTick) {
      this.latestTick = msg.tick;
      this.latestAt = performance.now();
    }
    if (msg.t === 'event') {
      if (msg.ev && typeof msg.ev.k === 'string') this.events.push(msg);
      return;
    }
    const t = msg.tick;
    const b = Array.isArray(msg.b) ? msg.b : [];
    for (let i = 0; i + 4 < b.length; i += 5) this.sample(b[i], { t, x: b[i + 1], y: b[i + 2], a: b[i + 3], hp: b[i + 4] });
    const p = Array.isArray(msg.p) ? msg.p : [];
    for (let i = 0; i + 4 < p.length; i += 5) {
      const nid = p[i];
      const w = WEAPON_ORDER[p[i + 1]];
      if (!w) continue;
      if (!this.byNid.has(nid) && !this.incoming.has(nid)) this.incoming.set(nid, w);
      this.sample(nid, { t, x: p[i + 2], y: p[i + 3], a: p[i + 4], hp: 1 });
    }
    for (const nid of Array.isArray(msg.x) ? msg.x : []) this.removals.push({ t, nid });
    this.statuses.push({ tick: t, s: msg.s, a: msg.a, f: msg.f });
  }

  update(dt: number): void {
    updateEffects(this.game, this.fx, dt, this.world);
    if (this.windMs > 0) {
      this.windMs -= dt;
      for (let k = 0; k < 2; k++) this.game.particles.streak(rand(-200, 900), rand(250, 930));
    }
    if ((this.pingTimer -= dt) <= 0) {
      this.pingTimer = 1000;
      const rtt = this.opts.rtt();
      this.hud.ping.textContent = rtt === null ? '…' : `${rtt} ms`;
    }
    for (const e of this.world.entities.values()) {
      if (e.flash > 0) e.flash = Math.max(0, e.flash - dt / 250);
      if (e.infest) e.infest = Math.max(0, e.infest - dt);
    }
    if (this.latestTick < 0) return;

    const target = this.latestTick + (performance.now() - this.latestAt) - PLAY_DELAY;
    if (this.clock < 0 || Math.abs(target - this.clock) > RESYNC_MS) this.clock = Math.max(this.clock, target);
    else this.clock = Math.max(this.clock, this.clock + dt + (target - this.clock - dt) * 0.08);
    const now = this.clock;

    while (this.events.length && this.events[0].tick <= now) this.onEvent(this.events.shift()!.ev);
    while (this.removals.length && this.removals[0].t <= now) this.drop(this.removals.shift()!.nid);
    this.applyTracks(now);
    while (this.statuses.length > 1 && this.statuses[1].tick <= now) this.statuses.shift();
    if (this.statuses.length && this.statuses[0].tick <= now) this.applyStatus(this.statuses.shift()!);
  }

  // ------------------------------------------------------------------ riproduzione

  private sample(nid: unknown, s: Sample): void {
    if (typeof nid !== 'number' || ![s.x, s.y, s.a, s.hp].every(Number.isFinite)) return;
    let track = this.tracks.get(nid);
    if (!track) this.tracks.set(nid, (track = []));
    track.push(s);
  }

  private applyTracks(now: number): void {
    for (const [nid, track] of this.tracks) {
      let i = -1;
      while (i + 1 < track.length && track[i + 1].t <= now) i++;
      if (i < 0) continue;
      let e = this.byNid.get(nid);
      if (!e) {
        const w = this.incoming.get(nid);
        if (!w) continue;
        this.incoming.delete(nid);
        e = this.world.launch(w, 0, 0);
        this.byNid.set(nid, e);
      }
      const a = track[i];
      const b = track[i + 1];
      const k = b ? (now - a.t) / Math.max(1, b.t - a.t) : 0;
      const x = b ? lerp(a.x, b.x, k) : a.x;
      const y = b ? lerp(a.y, b.y, k) : a.y;
      const body = e.body;
      // la velocità serve solo al disegno (orientamento della bomba in volo)
      if (e.kind === 'projectile') Body.setVelocity(body, { x: x - body.position.x, y: y - body.position.y });
      Body.setPosition(body, { x, y });
      Body.setAngle(body, b ? lerp(a.a, b.a, k) : a.a);
      // le termiti rosicchiano poco per volta: lampo solo per i colpi veri
      if (a.hp < e.hp - 2) e.flash = 1;
      e.hp = a.hp;
      if (i > 0) track.splice(0, i);
    }
  }

  private drop(nid: number): void {
    const e = this.byNid.get(nid);
    if (e) this.world.remove(e);
    this.byNid.delete(nid);
    this.tracks.delete(nid);
    this.incoming.delete(nid);
  }

  private applyStatus(st: Pick<SnapMessage, 's' | 'a' | 'f'>): void {
    const [timeLeft, shots, broken] = Array.isArray(st.s) ? st.s : [];
    if (Number.isFinite(timeLeft)) {
      this.game.sfx.music.tension = this.fx.winner ? 0 : timeLeft <= 10 ? 1 : timeLeft <= 30 ? 0.45 : 0;
      this.hud.timer.textContent = formatTime(timeLeft);
      this.hud.timer.classList.toggle('warn', timeLeft <= 10);
    }
    if (Number.isFinite(shots) && Number.isFinite(broken)) this.hud.stats.textContent = `Colpi ${shots} · Crolli ${broken}`;
    const a = Array.isArray(st.a) ? st.a : [];
    this.pouch = a.length >= 3 && Number.isFinite(a[0]) && Number.isFinite(a[1]) ? { x: a[0], y: a[1] } : null;
    this.loaded = this.pouch ? WEAPON_ORDER[a[2]] ?? null : null;
    this.stormX = Number.isFinite(st.f) && st.f >= 0 ? st.f : null;
  }

  private onEvent(ev: NetEvent): void {
    playEffect(this.game, ev, this.fx);
    const atk = this.opts.attacker;
    switch (ev.k) {
      case 'shot':
        if (WEAPONS[ev.w]) this.setHint(`${atk} lancia: ${WEAPONS[ev.w].name}!`);
        break;
      case 'bolt':
        for (const e of this.world.entities.values()) e.wet = false;
        this.setHint('Un fulmine si abbatte sulla fortezza!');
        break;
      case 'reflect':
        this.setHint(`La tua seta rimanda il fulmine: ${atk} è abbagliato!`);
        break;
      case 'termite': {
        const e = Number.isInteger(ev.n) ? this.byNid.get(ev.n) : undefined;
        if (e) e.infest = TUNING.termiteMs;
        this.setHint(e ? 'Le termiti rosicchiano la tua fortezza!' : 'Le termiti non trovano niente da rosicchiare.');
        break;
      }
      case 'flood':
        this.setHint('Una piena investe la base della fortezza!');
        break;
      case 'wet':
        for (const n of Array.isArray(ev.n) ? ev.n.slice(0, 200) : []) {
          const e = this.byNid.get(n);
          if (e) e.wet = true;
        }
        break;
      case 'wind':
        this.windMs = WIND_MS;
        this.setHint('La bufera investe la tua fortezza!');
        break;
      case 'echo':
        this.setHint(`L'Eco rivela Mimika a ${atk} per 3 secondi!`);
        break;
      case 'decoy':
        this.setHint(`${atk} ha colpito un'esca: l'inganno funziona!`);
        break;
      case 'core-hit':
        this.setHint(`Mimika è stata presa (${ev.cause})!`);
        break;
      case 'end':
        if (ev.winner === 'defender') this.setHint(`Mimika resiste: ${ev.cause}!`);
        break;
    }
  }

  // ------------------------------------------------------------------ disegno

  /** stessa regola dell'attaccante: segue i proiettili (con il ritardo di riproduzione), ferma durante la mira */
  camera(): CamFocus | null {
    return battleFocus(this.world, this.fx, !!this.pouch || this.stormX !== null);
  }

  render(g: CanvasRenderingContext2D, t: number): void {
    drawHunter(g, t, { ...hunterMood(this.fx), pouch: this.pouch, cast: this.stormX !== null });
    drawLauncher(g, t, this.pouch, this.loaded, this.fx.recoil);
    // il difensore sa dove sono Mimika e le esche: le vede sempre
    drawWorld(g, this.world, t, {
      creature: (e) => (e.kind === 'core' ? { style: 'live', alpha: 1, ...mimikaMood(this.fx) } : { style: 'decoy', alpha: 1 }),
      look: this.pouch ?? { x: WORLD.LAUNCH_X, y: WORLD.LAUNCH_Y },
    });
    if (this.stormX !== null) drawStormMarker(g, this.stormX, t);
    drawEffects(g, this.fx, t);
  }

  // ------------------------------------------------------------------ HUD

  private setHint(text: string): void {
    this.hud.hint.textContent = text;
  }

  private buildHud(): HTMLElement {
    const timer = h('div', { class: 'timer' }, formatTime(MODES[this.bp.mode].attackTime));
    const hint = h('div', { class: 'hint' });
    const stats = h('div', { class: 'stats' }, 'Colpi 0 · Crolli 0');
    const ping = h('small', {}, '…');
    this.hud = { timer, hint, stats, ping };
    return h('div', { class: 'hud spectate-hud' },
      h('div', { class: 'hud-top' },
        h('div', { class: 'role-pill def' }, h('b', {}, 'DIFESA'), h('span', {}, `${this.opts.defender} · ${this.opts.attacker} attacca`)),
        timer,
        h('div', { class: 'hud-actions' },
          h('div', { class: 'live-badge', title: 'Latenza' }, h('i', {}), h('span', {}, 'IN DIRETTA'), ping),
          stats,
        ),
      ),
      hint,
      h('button', { class: 'quit-btn', title: 'Esci', onclick: () => this.opts.onQuit() }, icon(ICONS.back)),
    );
  }
}
