import type { MaterialId } from '../config/materials';
import type { WeaponId } from '../config/weapons';
import { Music, type Mood } from './music';

export type { Mood } from './music';

const SFX_GAIN = 0.55;
const MUSIC_GAIN = 0.42;

/** Piccola variazione casuale di altezza: lo stesso suono ripetuto non stanca. */
const vary = (f: number, amt = 0.035) => f * (1 + (Math.random() * 2 - 1) * amt);

/**
 * Audio sintetizzato con WebAudio: zero asset, pochi KB.
 * Catena: effetti -> bus effetti \
 *                                  > master (muto) -> uscita
 *         musica  -> bus musica  /
 * L'AudioContext si sblocca al primo tocco (regola dei browser mobili).
 */
export class Sfx {
  private ctx: AudioContext | null = null;
  private master: GainNode | null = null;
  private bus: GainNode | null = null;
  private musicBus: GainNode | null = null;
  private noiseBuf: AudioBuffer | null = null;
  private lastThud = 0;
  private lastScare = 0;
  readonly music = new Music();
  muted = false;
  private background = false;
  /** 0..1, regolabili dalle impostazioni */
  sfxVolume = 1;
  musicVolume = 0.7;

  unlock(): void {
    if (!this.ctx) {
      const AC = window.AudioContext ?? (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
      if (!AC) return;
      const ctx = (this.ctx = new AC());
      this.master = ctx.createGain();
      this.master.gain.value = this.muted ? 0 : 1;
      this.master.connect(ctx.destination);
      this.bus = ctx.createGain();
      this.bus.connect(this.master);
      this.musicBus = ctx.createGain();
      this.musicBus.connect(this.master);
      this.applyVolumes();
      const len = ctx.sampleRate;
      this.noiseBuf = ctx.createBuffer(1, len, ctx.sampleRate);
      const d = this.noiseBuf.getChannelData(0);
      for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
      this.music.attach(ctx, this.musicBus, this.noiseBuf);
      this.music.paused = this.muted;
      // scheda in background: niente musica né CPU sprecata
      document.addEventListener('visibilitychange', () => this.setBackground(document.hidden));
    }
    if (this.ctx.state === 'suspended' && !document.hidden && !this.background) void this.ctx.resume();
  }

  /** In background (scheda nascosta o app sospesa): audio fermo; al ritorno riprende da dove era. */
  setBackground(bg: boolean): void {
    this.background = bg;
    if (!this.ctx) return;
    if (bg) void this.ctx.suspend();
    else if (!this.muted) void this.ctx.resume();
  }

  setMuted(m: boolean): void {
    this.muted = m;
    this.music.paused = m;
    if (this.master && this.ctx) this.master.gain.setTargetAtTime(m ? 0 : 1, this.ctx.currentTime, 0.04);
  }

  setVolumes(music: number, sfx: number): void {
    this.musicVolume = music;
    this.sfxVolume = sfx;
    this.applyVolumes();
  }

  private applyVolumes(): void {
    if (!this.ctx) return;
    this.bus!.gain.setTargetAtTime(SFX_GAIN * this.sfxVolume, this.ctx.currentTime, 0.03);
    this.musicBus!.gain.setTargetAtTime(MUSIC_GAIN * this.musicVolume * this.musicVolume, this.ctx.currentTime, 0.03);
  }

  /** Tema musicale: calma (menu, costruzione), assedio (attacco, diretta), silenzio. Crossfade automatico. */
  setMood(m: Mood): void {
    this.music.setMood(m);
  }

  private ready(): AudioContext | null {
    return this.ctx && this.bus && !this.muted && this.sfxVolume > 0 ? this.ctx : null;
  }

  private tone(freq: number, dur: number, type: OscillatorType = 'sine', vol = 0.3, slideTo?: number, delay = 0): void {
    const ctx = this.ready();
    if (!ctx) return;
    const t0 = ctx.currentTime + delay;
    const o = ctx.createOscillator();
    const g = ctx.createGain();
    o.type = type;
    o.frequency.setValueAtTime(freq, t0);
    if (slideTo) o.frequency.exponentialRampToValueAtTime(slideTo, t0 + dur);
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(vol, t0 + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    o.connect(g).connect(this.bus!);
    o.start(t0);
    o.stop(t0 + dur + 0.05);
  }

  private noise(dur: number, vol: number, freq: number, type: BiquadFilterType = 'lowpass', sweepTo?: number, delay = 0, q = 1): void {
    const ctx = this.ready();
    if (!ctx || !this.noiseBuf) return;
    const t0 = ctx.currentTime + delay;
    const src = ctx.createBufferSource();
    src.buffer = this.noiseBuf;
    src.loop = true;
    const f = ctx.createBiquadFilter();
    f.type = type;
    f.Q.value = q;
    f.frequency.setValueAtTime(freq, t0);
    if (sweepTo) f.frequency.exponentialRampToValueAtTime(sweepTo, t0 + dur);
    const g = ctx.createGain();
    g.gain.setValueAtTime(vol, t0);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    src.connect(f).connect(g).connect(this.bus!);
    src.start(t0, Math.random() * 0.5);
    src.stop(t0 + dur + 0.05);
  }

  click(): void { this.tone(vary(720, 0.02), 0.06, 'triangle', 0.12); }
  place(): void { this.tone(vary(300), 0.09, 'triangle', 0.18, 180); this.noise(0.06, 0.12, vary(1200, 0.1)); }
  erase(): void { this.tone(vary(420), 0.1, 'sine', 0.12, 220); }
  deny(): void { this.tone(160, 0.14, 'square', 0.06); }
  /** elastico che si tende (inizio mira) */
  stretch(): void { this.tone(vary(140), 0.28, 'sawtooth', 0.035, 260); this.noise(0.2, 0.04, 500, 'bandpass', 1500, 0, 4); }

  launch(w?: WeaponId): void {
    if (w === 'drill') {
      this.tone(vary(260), 0.5, 'sawtooth', 0.08, 900);
      this.noise(0.45, 0.12, 1800, 'bandpass', 4200, 0, 3);
    } else if (w === 'termite') {
      this.tone(vary(240), 0.16, 'triangle', 0.16, 420); // vaso di terracotta che parte
      for (let i = 0; i < 4; i++) this.noise(0.03, 0.05, vary(3200, 0.2), 'bandpass', undefined, 0.05 + i * 0.04, 8); // zampette
    } else if (w === 'bomb') {
      this.tone(vary(160), 0.24, 'triangle', 0.2, 480);
      this.noise(0.6, 0.06, 5000, 'highpass'); // miccia che sfrigola
    } else {
      this.tone(vary(180), 0.22, 'triangle', 0.22, 560);
    }
    this.noise(0.25, 0.1, 900, 'bandpass', 3000);
  }

  /** Urto contro un blocco: timbro diverso per materiale. */
  thud(strength: number, mat?: MaterialId): void {
    const ctx = this.ready();
    if (!ctx || ctx.currentTime - this.lastThud < 0.045) return;
    this.lastThud = ctx.currentTime;
    const s = strength;
    switch (mat) {
      case 'wood':
        this.tone(vary(210, 0.08), 0.14, 'triangle', 0.32 * s, 120);
        this.noise(0.09, 0.22 * s, vary(900, 0.1), 'bandpass', undefined, 0, 2);
        break;
      case 'metal':
        for (const [f, v] of [[520, 0.12], [1310, 0.07], [2140, 0.04]] as const) this.tone(vary(f, 0.03), 0.55, 'sine', v * s + 0.01);
        this.noise(0.05, 0.2 * s, 3000, 'highpass');
        break;
      case 'glass':
        this.tone(vary(2600, 0.08), 0.18, 'sine', 0.09 * s + 0.01);
        this.tone(vary(3900, 0.08), 0.12, 'sine', 0.05 * s + 0.01, undefined, 0.02);
        break;
      case 'moss':
        this.noise(0.12, 0.25 * s, 260, 'lowpass');
        this.tone(vary(140), 0.12, 'sine', 0.25 * s, 90);
        break;
      case 'silk': // fruscio di stoffa e un piccolo scintillio
        this.noise(0.14, 0.2 * s, vary(2400, 0.1), 'bandpass', 900, 0, 1.2);
        this.tone(vary(1760, 0.04), 0.22, 'sine', 0.05 * s + 0.01, 2100);
        break;
      default: // pietra (e tutto il resto)
        this.noise(0.16, 0.35 * s, vary(380, 0.1));
        this.tone(vary(95, 0.06), 0.16, 'sine', 0.45 * s, 45);
    }
  }

  /** Blocco distrutto. */
  broken(mat: MaterialId): void {
    switch (mat) {
      case 'glass': return this.shatter();
      case 'wood':
        this.noise(0.4, 0.3, vary(1500, 0.1), 'bandpass', 300, 0, 1.5);
        for (let i = 0; i < 3; i++) this.noise(0.04, 0.2, vary(2400, 0.2), 'bandpass', undefined, i * 0.05 + Math.random() * 0.03, 6);
        this.tone(vary(150), 0.25, 'triangle', 0.18, 70);
        return;
      case 'metal':
        for (const [f, v] of [[340, 0.14], [870, 0.09], [1490, 0.06], [2230, 0.04]] as const) this.tone(vary(f, 0.04), 0.9, 'sine', v);
        this.noise(0.5, 0.2, 1600, 'bandpass', 400);
        return;
      case 'moss':
        this.noise(0.35, 0.3, 700, 'lowpass', 120);
        this.tone(vary(220), 0.2, 'sine', 0.16, 110);
        return;
      case 'silk': // strappo di seta + arpeggio iridescente che svanisce
        this.noise(0.32, 0.28, vary(4200, 0.1), 'bandpass', 1200, 0, 2.5);
        [1568, 1976, 2349].forEach((f, i) => this.tone(vary(f, 0.02), 0.3, 'sine', 0.05, f * 0.7, 0.05 + i * 0.05));
        return;
      default:
        return this.crumble();
    }
  }

  shatter(): void { this.noise(0.4, 0.28, 3500, 'highpass'); for (let i = 0; i < 4; i++) this.tone(2200 + Math.random() * 2600, 0.12, 'sine', 0.05, undefined, i * 0.03); }
  crumble(): void { this.noise(0.45, 0.3, vary(700, 0.1), 'lowpass', 150); this.tone(vary(70), 0.3, 'sine', 0.2, 40); }
  boom(): void { this.noise(1.1, 0.7, vary(1100, 0.08), 'lowpass', 80); this.tone(vary(70, 0.06), 0.7, 'sine', 0.7, 28); }
  zap(): void { this.noise(0.5, 0.35, vary(2600, 0.08), 'bandpass', 600); this.tone(vary(1400, 0.08), 0.35, 'sawtooth', 0.08, 120); }
  wind(): void { this.noise(2.8, 0.3, 300, 'bandpass', 1400); }
  /** la seta rimanda il fulmine: accordo cristallino che sale */
  mirror(): void { [1046, 1568, 2093, 3136].forEach((f, i) => this.tone(f, 0.5, 'sine', 0.1, f * 1.5, i * 0.04)); this.noise(0.3, 0.12, 6000, 'highpass'); }
  /** termiti che rosicchiano: scricchiolii secchi e fitti */
  chew(): void { for (let i = 0; i < 6; i++) this.noise(0.025, 0.12, vary(2800, 0.3), 'bandpass', undefined, i * 0.05 + Math.random() * 0.02, 9); }
  /** piena: boato d'acqua che arriva e risacca */
  flood(): void { this.noise(2.6, 0.38, 220, 'lowpass', 900); this.noise(1.6, 0.18, 1800, 'bandpass', 500, 0.5, 0.8); for (let i = 0; i < 5; i++) this.tone(vary(420, 0.3), 0.08, 'sine', 0.05, 900, 0.4 + i * 0.22); }
  ping(): void { this.tone(880, 0.9, 'sine', 0.22); this.tone(1320, 0.7, 'sine', 0.1, undefined, 0.12); }
  pop(): void { this.tone(vary(500), 0.12, 'square', 0.08, 900); }
  squeak(): void { this.tone(vary(900), 0.25, 'triangle', 0.22, 1700); }
  /** Mimika si spaventa (colpo vicino): squittio breve, mai più di uno al secondo */
  eek(): void {
    const ctx = this.ready();
    if (!ctx || ctx.currentTime - this.lastScare < 1) return;
    this.lastScare = ctx.currentTime;
    this.tone(vary(1500, 0.06), 0.09, 'triangle', 0.1, 2300);
    this.tone(vary(1700, 0.06), 0.08, 'triangle', 0.08, 2600, 0.1);
  }
  /** Mimika esulta */
  cheer(): void { [1046, 1318, 1568, 2093].forEach((f, i) => this.tone(vary(f, 0.01), 0.12, 'triangle', 0.09, f * 1.15, 0.5 + i * 0.07)); }
  tick(): void { this.tone(1000, 0.04, 'square', 0.05); }
  win(): void { [523, 659, 784, 1046].forEach((f, i) => this.tone(f, 0.35, 'triangle', 0.18, undefined, i * 0.11)); }
  lose(): void { [392, 330, 262].forEach((f, i) => this.tone(f, 0.45, 'triangle', 0.16, undefined, i * 0.16)); }
}
