import { MATERIAL_ORDER, type MaterialId } from '../config/materials';
import { MODES, type ModeId } from '../config/modes';
import { WORLD } from '../config/world';
import { mulberry32 } from '../core/math';
import { blockCost, blockIndexAt, blueprintCost, canPlaceBlock, emptyBlueprint, isCellFree, type Blueprint, type PlacedBlock } from './blueprint';

/** Stile della fortezza generata: materiale prevalente, oppure misto. */
export type FortStyle = 'mixed' | MaterialId;
export const FORT_STYLES: FortStyle[] = ['mixed', ...MATERIAL_ORDER];

type Role = 'wall' | 'roof' | 'filler';

const MIXED: Record<Role, Partial<Record<MaterialId, number>>> = {
  wall: { stone: 3, wood: 2, metal: 1, moss: 1.2, glass: 0.8, silk: 0.5 },
  roof: { stone: 2, wood: 2, metal: 1, moss: 1, silk: 1, glass: 0.5 },
  filler: { glass: 3, wood: 2, moss: 1, stone: 1, silk: 0.5 },
};

/**
 * Fortezza "tipo" generata da un seme: camera di Mimika (muri + tetto), capanne gemelle per le esche,
 * poi torri e scudi finché ci sono risorse. Ogni blocco poggia su qualcosa. Solo interi e PRNG:
 * lo stesso seme dà la stessa fortezza su ogni dispositivo (sfida del giorno, banco di prova).
 */
export function generateFortress(seed: number, mode: ModeId, style: FortStyle = 'mixed', author = 'Mimika', allowed: readonly MaterialId[] = MATERIAL_ORDER): Blueprint {
  const rng = mulberry32(seed);
  const def = MODES[mode];
  const bp = emptyBlueprint(mode, author);
  const ri = (a: number, b: number) => a + Math.floor(rng() * (b - a + 1));

  const pick = (role: Role): MaterialId => {
    if (style !== 'mixed' && rng() < 0.6) return style;
    const table = MIXED[role];
    const entries = (Object.entries(table) as [MaterialId, number][]).filter(([m]) => allowed.includes(m));
    let r = rng() * entries.reduce((s, [, w]) => s + w, 0);
    for (const [m, w] of entries) if ((r -= w) <= 0) return m;
    return entries[0][0];
  };

  const supported = (b: PlacedBlock) => {
    if (b.row === 0) return true;
    const under = (c: number) => blockIndexAt(bp, c, b.row - 1) >= 0;
    return b.w === 1 ? under(b.col) : under(b.col) && under(b.col + b.w - 1);
  };

  const place = (mat: MaterialId, col: number, row: number, w: number, h: number): boolean => {
    const b: PlacedBlock = { mat, col, row, w, h };
    if (blueprintCost(bp) + blockCost(b) > def.budget || !canPlaceBlock(bp, b) || !supported(b)) return false;
    bp.blocks.push(b);
    return true;
  };

  /** camera: gusci concentrici attorno alla cella (col, row); strato L = muri a col±L e tetto sopra */
  const chamber = (col: number, row: number, layers: number) => {
    for (let L = 1; L <= layers; L++) {
      const top = row + 1 + L;
      const wall = pick('wall');
      for (const c of [col - L, col + L]) {
        const m = c > col && rng() > 0.7 ? pick('wall') : wall;
        place(m, c, 0, 1, Math.min(3, top));
        if (top > 3) place(m, c, 3, 1, top - 3);
      }
      const roof = pick('roof');
      for (let c = col - L; c <= col + L; c += 3) place(roof, c, top, Math.min(3, col + L - c + 1), 1);
    }
  };

  // Mimika: in una camera a uno o più gusci, a volte su un piedistallo (prima si spende per lei)
  const coreCol = ri(3, 12);
  const raised = rng() < 0.25;
  bp.core = { col: coreCol, row: raised ? 1 : 0 };
  if (raised && !place(pick('wall'), coreCol, 0, 1, 1)) bp.core.row = 0;
  chamber(coreCol, bp.core.row, def.budget >= 150 ? ri(2, 3) : ri(1, 2));

  // esche in capanne simili (devono sembrare il vero nascondiglio)
  for (let i = 0; i < def.decoys; i++) {
    if (rng() > 0.85) continue;
    for (let tries = 0; tries < 12; tries++) {
      const col = ri(1, WORLD.ZONE_COLS - 2);
      if (Math.abs(col - coreCol) < 3 || !isCellFree(bp, col, 0)) continue;
      bp.decoys.push({ col, row: 0 });
      chamber(col, 0, 1);
      break;
    }
  }

  // il resto delle risorse: blocchi lasciati cadere sulle colonne (torri, scudi sul lato dell'attacco)
  const height = (c: number) => {
    let r = 0;
    while (r < WORLD.ZONE_ROWS && !isCellFree(bp, c, r)) r++;
    return r;
  };
  for (let tries = 0; tries < 260 && def.budget - blueprintCost(bp) > 0; tries++) {
    const shield = rng() < 0.45;
    const col = shield ? ri(0, Math.max(0, coreCol - 2)) : ri(0, WORLD.ZONE_COLS - 1);
    const vertical = rng() < 0.4;
    const w = vertical ? 1 : ri(1, 3);
    const h = vertical ? ri(1, 2) : 1;
    if (col + w > WORLD.ZONE_COLS) continue;
    let row = 0;
    for (let c = col; c < col + w; c++) row = Math.max(row, height(c));
    if (row + h > WORLD.ZONE_ROWS - 2) continue;
    place(pick(rng() < 0.3 ? 'filler' : 'wall'), col, row, w, h);
  }
  return bp;
}

/** Seme della sfida del giorno: la data locale come numero AAAAMMGG. */
export function dailySeed(d = new Date()): number {
  return d.getFullYear() * 10000 + (d.getMonth() + 1) * 100 + d.getDate();
}
