import { WEAPON_ORDER, type WeaponId } from '../config/weapons';
import type { Vec, World } from '../game/World';
import { SNAP_INTERVAL, type NetEvent, type NetMessage } from './protocol';

/** Stato dell'attacco che il difensore vede nel suo HUD e sulla fionda. */
export interface AttackStatus {
  timeLeft: number;
  shots: number;
  broken: number;
  pouch: Vec | null;
  loaded: WeaponId | null;
  stormX: number | null;
}

const r1 = (v: number) => Math.round(v * 10) / 10;
const r3 = (v: number) => Math.round(v * 1000) / 1000;
/** urti minori di così, o più ravvicinati di così, non viaggiano in rete (solo effetto locale) */
const IMPACT_MIN = 0.3;
const IMPACT_GAP_MS = 60;

/**
 * Lato attaccante (autorevole): trasforma il World in snapshot delta a ~15 Hz ed eventi.
 * Il DataChannel è affidabile e ordinato, quindi basta mandare ciò che è cambiato.
 */
export class LiveBroadcaster {
  private tick = 0;
  private nextSnap = 0;
  private lastImpact = -1e9;
  /** ultimo stato trasmesso di blocchi e creature: nid -> [x, y, angolo, hp] */
  private readonly sent = new Map<number, number[]>();
  private readonly sentProjectiles = new Set<number>();

  constructor(private readonly send: (msg: NetMessage) => void) {}

  event(ev: NetEvent): void {
    if (ev.k === 'impact') {
      if (ev.s < IMPACT_MIN || this.tick - this.lastImpact < IMPACT_GAP_MS) return;
      this.lastImpact = this.tick;
    }
    this.send({ t: 'event', tick: this.tick, ev });
  }

  /** Da chiamare a ogni frame dopo World.step; elapsed = ms dall'inizio dell'attacco. */
  frame(world: World, elapsed: number, st: AttackStatus): void {
    this.tick = Math.round(elapsed);
    if (elapsed < this.nextSnap) return;
    this.nextSnap = Math.max(this.nextSnap + SNAP_INTERVAL, elapsed);

    const b: number[] = [];
    const p: number[] = [];
    const x: number[] = [];
    const alive = new Set<number>();
    for (const e of world.entities.values()) {
      const body = e.body;
      alive.add(e.nid);
      if (e.kind === 'projectile') {
        p.push(e.nid, WEAPON_ORDER.indexOf(e.weapon!), r1(body.position.x), r1(body.position.y), r3(body.angle));
        this.sentProjectiles.add(e.nid);
        continue;
      }
      const cur = [r1(body.position.x), r1(body.position.y), r3(body.angle), Math.round(e.hp)];
      const prev = this.sent.get(e.nid);
      if (prev && prev.every((v, i) => v === cur[i])) continue;
      this.sent.set(e.nid, cur);
      b.push(e.nid, ...cur);
    }
    for (const nid of this.sent.keys()) if (!alive.has(nid)) (this.sent.delete(nid), x.push(nid));
    for (const nid of this.sentProjectiles) if (!alive.has(nid)) (this.sentProjectiles.delete(nid), x.push(nid));

    this.send({
      t: 'snap', tick: this.tick, b, p, x,
      s: [r1(Math.max(0, st.timeLeft)), st.shots, st.broken],
      a: st.pouch ? [r1(st.pouch.x), r1(st.pouch.y), st.loaded ? WEAPON_ORDER.indexOf(st.loaded) : -1] : [],
      f: st.stormX === null ? -1 : Math.round(st.stormX),
    });
  }
}
