import { MODES } from '../config/modes';
import { WEAPONS, WEAPON_ORDER, type WeaponId } from '../config/weapons';
import type { Blueprint } from './blueprint';
import { World, type WorldListener } from './World';

/**
 * Azioni dell'attaccante come puro dato: le usano l'attacco dal vivo (che le registra),
 * il replay dei referti, l'attaccante automatico e il banco di prova del bilanciamento.
 *
 * Shot = [passo, indiceArma, a, b]
 *   fionda/trivella: a, b = velocità × 1000 (interi)
 *   fulmine:         a = x del punto toccato
 *   istantanei:      a = b = 0
 * Il valore viene arrotondato PRIMA di essere applicato, così il replay riparte dagli stessi numeri.
 */
export type Shot = [step: number, weapon: number, a: number, b: number];

export const MAX_SHOTS = 64;

export function makeShot(step: number, w: WeaponId, vx = 0, vy = 0): Shot {
  const aim = WEAPONS[w].aim;
  const wi = WEAPON_ORDER.indexOf(w);
  if (aim === 'sling' || aim === 'line') return [step, wi, Math.round(vx * 1000), Math.round(vy * 1000)];
  if (aim === 'tap') return [step, wi, Math.round(vx), 0];
  return [step, wi, 0, 0];
}

/** Applica un tiro al World. Ritorna l'arma usata (null se il dato non è valido). */
export function applyShot(world: World, s: Shot): WeaponId | null {
  const w = WEAPON_ORDER[s[1]];
  if (!w) return null;
  const aim = WEAPONS[w].aim;
  if (aim === 'sling' || aim === 'line') world.launch(w, s[2] / 1000, s[3] / 1000);
  else if (aim === 'tap') world.lightning(s[2]);
  else if (w === 'wind') world.startWind();
  else if (w === 'flood') world.startFlood();
  return w;
}

/** Validazione difensiva dei tiri ricevuti in un referto. */
export function cleanShots(raw: unknown): Shot[] | null {
  if (!Array.isArray(raw) || raw.length > MAX_SHOTS) return null;
  const out: Shot[] = [];
  let last = 0;
  for (const s of raw) {
    if (!Array.isArray(s) || s.length !== 4 || !s.every((n) => Number.isInteger(n) && Math.abs(n) < 1e7)) return null;
    if (s[0] < last || !WEAPON_ORDER[s[1]]) return null;
    last = s[0];
    out.push([s[0], s[1], s[2], s[3]]);
  }
  return out;
}

/** Esito in forma confrontabile: vincitore, causa e impronta dello stato. */
export interface SiegeOutcome {
  winner: 'attacker' | 'defender';
  cause: string;
  broken: number;
  /** passo a cui si è deciso l'esito */
  step: number;
  hash: string;
}

export const outcomeKey = (winner: SiegeOutcome['winner'], cause: string) => `${winner}|${cause}`;

/**
 * Rigioca senza grafica una battaglia registrata: stessi tiri agli stessi passi.
 * endStep = valore di World.steps quando l'attacco è finito. Se Mimika è stata presa durante un passo
 * (urto, crollo) quel passo non era ancora contato: per l'esito dichiarato "attacker" si concede un passo in più.
 */
export function replaySiege(bp: Blueprint, shots: Shot[], endStep: number, claimed: SiegeOutcome['winner'], listener: WorldListener = {}): SiegeOutcome {
  let out: SiegeOutcome | null = null;
  const world: World = new World(bp, {
    ...listener,
    coreHit: (cause, x, y) => {
      listener.coreHit?.(cause, x, y);
      if (!out) out = { winner: 'attacker', cause, broken: world.broken, step: world.steps, hash: world.digest(outcomeKey('attacker', cause)) };
    },
  });
  let i = 0;
  world.onBeforeStep = (step) => {
    while (!out && i < shots.length && shots[i][0] <= step) applyShot(world, shots[i++]);
  };
  const limit = Math.min(endStep + (claimed === 'attacker' ? 1 : 0), (MODES[bp.mode].attackTime + 30) * 60);
  while (!out && world.steps < limit) world.step(1000 / 60);
  return out ?? { winner: 'defender', cause: '', broken: world.broken, step: world.steps, hash: world.digest(outcomeKey('defender', '')) };
}
