/**
 * Codifica testo <-> stringa URL-safe.
 * Livello 1 del documento P2P (p2p-webrtc-signaling-whatsapp.pdf, cap. 4-5):
 * deflate-raw (CompressionStream nativo) + base64url.
 *
 * Prefisso del codice:  'z' = compresso deflate-raw,  'p' = solo base64url (browser senza CompressionStream).
 */
const hasStreams = typeof CompressionStream !== 'undefined' && typeof DecompressionStream !== 'undefined';

function bytesToB64url(bytes: Uint8Array): string {
  let bin = '';
  for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
  return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function b64urlToBytes(s: string): Uint8Array<ArrayBuffer> {
  const bin = atob(s.replace(/-/g, '+').replace(/_/g, '/'));
  return Uint8Array.from(bin, (c) => c.charCodeAt(0));
}

async function pipe(bytes: Uint8Array<ArrayBuffer>, stream: CompressionStream | DecompressionStream): Promise<Uint8Array> {
  const out = new Blob([bytes]).stream().pipeThrough(stream);
  return new Uint8Array(await new Response(out).arrayBuffer());
}

export async function packText(text: string): Promise<string> {
  const raw = new TextEncoder().encode(text);
  if (hasStreams) return 'z' + bytesToB64url(await pipe(raw, new CompressionStream('deflate-raw')));
  return 'p' + bytesToB64url(raw);
}

/** Lancia un errore se il codice è troncato o non valido (es. link copiato a metà). */
export async function unpackText(code: string): Promise<string> {
  const tag = code[0];
  const bytes = b64urlToBytes(code.slice(1));
  if (tag === 'p') return new TextDecoder().decode(bytes);
  if (tag === 'z') {
    if (!hasStreams) throw new Error('Questo browser non supporta la decompressione: aggiornalo.');
    return new TextDecoder().decode(await pipe(bytes, new DecompressionStream('deflate-raw')));
  }
  throw new Error('Codice non riconosciuto');
}

export const packJson = (value: unknown) => packText(JSON.stringify(value));
export const unpackJson = async <T>(code: string): Promise<T> => JSON.parse(await unpackText(code)) as T;
