export type QualityPref = 'auto' | 'high' | 'low';

/**
 * Impostazioni di resa lette da chi disegna (particelle, ombre, camera).
 * Qualità bassa: risoluzione 1×, niente parallasse né grana, metà particelle, niente ombre dei blocchi.
 */
export const QUALITY = {
  low: false,
  /** frazione di particelle generate (0..1) */
  particles: 1,
  shadows: true,
};

/** finestra di misura (ms) e soglia: sotto ~40 fps per due finestre di fila (~3 s) si scende di qualità */
const WINDOW_MS = 1500;
const SLOW_MS = 25;

/**
 * Misura i frame e abbassa la qualità da sola sui telefoni lenti (in modalità "auto").
 * Scende una volta sola e non risale: niente oscillazioni a metà partita.
 */
export class FrameMeter {
  /** media mobile del tempo di frame (ms) */
  avg = 16.7;
  fps = 60;
  private sum = 0;
  private n = 0;
  private slowWindows = 0;

  constructor(private readonly onSlow: () => void) {}

  sample(ms: number, auto: boolean): void {
    // pause, schede nascoste, caricamenti: non sono frame "veri"
    if (ms <= 0 || ms > 250 || document.hidden) return;
    this.avg += (ms - this.avg) * 0.05;
    this.fps = Math.round(1000 / this.avg);
    this.sum += ms;
    this.n++;
    if (this.sum < WINDOW_MS) return;
    const mean = this.sum / this.n;
    this.sum = this.n = 0;
    this.slowWindows = mean > SLOW_MS ? this.slowWindows + 1 : 0;
    if (auto && !QUALITY.low && this.slowWindows >= 2) {
      this.slowWindows = 0;
      this.onSlow();
    }
  }
}
