import { WORLD } from '../config/world';
import { rand } from '../core/math';
import type { Game } from '../game/Game';
import { demoBlueprint, type Blueprint } from '../game/blueprint';
import { drawHunter, drawLauncher } from '../render/actors';
import { blueprintBlocks, drawBlocks, drawBlueprintCreatures } from '../render/scenery';
import type { CamFocus } from '../render/Renderer';
import type { Scene } from './Scene';

/**
 * Diorama animato dietro menu e pannelli: fortezza, Mimika che si guarda intorno, lucciole.
 * hideCreatures = true quando dietro c'è una sfida da giocare (non si spoilera il nascondiglio).
 */
export class BackdropScene implements Scene {
  private look: { x: number; y: number } = { x: WORLD.LAUNCH_X, y: WORLD.LAUNCH_Y };
  private fireflyTimer = 0;

  constructor(
    private game: Game,
    private bp: Blueprint = demoBlueprint(),
    private hideCreatures = false,
  ) {}

  update(dt: number): void {
    this.fireflyTimer -= dt;
    if (this.fireflyTimer <= 0) {
      this.fireflyTimer = rand(150, 400) / (this.game.renderer.theme.fireflies ?? 1);
      this.game.particles.firefly(rand(200, 1800), rand(600, 930));
    }
    const t = this.game.time;
    this.look = { x: 1400 + Math.cos(t * 0.5) * 900, y: 700 + Math.sin(t * 0.7) * 200 };
  }

  /** deriva lenta del diorama: la parallasse si vede anche dietro ai menu */
  camera(): CamFocus {
    const t = this.game.time;
    return { x: 960 + Math.sin(t * 0.13) * 320, y: 705 + Math.sin(t * 0.09) * 120, zoom: 1.02 };
  }

  render(g: CanvasRenderingContext2D, t: number): void {
    drawHunter(g, t);
    drawLauncher(g, t, null, null);
    drawBlocks(g, blueprintBlocks(this.bp));
    if (!this.hideCreatures) drawBlueprintCreatures(g, this.bp, t, this.look);
  }
}
