import '@fontsource/fredoka/400.css';
import '@fontsource/fredoka/500.css';
import '@fontsource/fredoka/600.css';
import '@fontsource/fredoka/700.css';
import './styles.css';
import { Game } from './game/Game';
import { registerPwa } from './pwa';

registerPwa();

const canvas = document.querySelector<HTMLCanvasElement>('#stage')!;
const ui = document.querySelector<HTMLElement>('#ui')!;

// Il font va caricato prima del primo disegno su canvas (testi fluttuanti).
document.fonts.load('700 32px Fredoka').finally(() => {
  const game = new Game(canvas, ui);
  game.start();
  if (import.meta.env.DEV) (window as unknown as { mimika: Game }).mimika = game; // debug da console
  document.querySelector('#boot')?.classList.add('gone');
});
