import { MODES, type ModeDef } from '../config/modes';
import { WEAPONS, WEAPON_ORDER, type WeaponId } from '../config/weapons';
import { WORLD } from '../config/world';
import { rand } from '../core/math';
import { Bot } from '../game/bot';
import type { Game } from '../game/Game';
import type { Blueprint } from '../game/blueprint';
import { applyShot, type Shot } from '../game/siege';
import { World } from '../game/World';
import type { NetEvent } from '../net/protocol';
import { drawHunter, drawLauncher } from '../render/actors';
import type { CamFocus } from '../render/Renderer';
import { drawWorld } from '../render/scenery';
import { h, icon, tip } from '../ui/dom';
import { ICONS } from '../ui/icons';
import { battleFocus, drawEffects, flatPath, hunterMood, mimikaMood, newFxState, playEffect, updateEffects } from './effects';
import type { Scene } from './Scene';

/**
 * Assedio che si gioca da solo, visto dalla parte di chi difende (Mimika ed esche sempre visibili).
 * Base comune di ReplayScene (tiri registrati nel referto) e SurvivalScene (attaccante automatico a ondate).
 * Le azioni si applicano in World.onBeforeStep: stesso passo, stesso risultato del replay senza grafica.
 */
abstract class AutoSiegeScene implements Scene {
  readonly mood = 'siege';
  protected readonly world: World;
  protected readonly fx = newFxState('def');
  protected readonly mode: ModeDef;
  protected speed = 1;
  protected ended = false;
  protected hud!: { hint: HTMLElement; stats: HTMLElement; info: HTMLElement; speed: HTMLElement };

  constructor(protected readonly game: Game, protected readonly bp: Blueprint) {
    this.mode = MODES[bp.mode];
    const r = Math.round;
    const emit = (ev: NetEvent) => playEffect(this.game, ev, this.fx);
    this.world = new World(bp, {
      impact: (x, y, s, mat) => emit({ k: 'impact', x: r(x), y: r(y), s, mat }),
      broken: (e) => emit({ k: 'broken', x: r(e.body.position.x), y: r(e.body.position.y), mat: e.mat! }),
      coreHit: (cause, x, y) => {
        emit({ k: 'core-hit', x: r(x), y: r(y), cause });
        this.onCoreHit(cause);
      },
      decoyPopped: (e) => emit({ k: 'decoy', x: r(e.body.position.x), y: r(e.body.position.y) }),
      explosion: (x, y, rad) => emit({ k: 'explosion', x: r(x), y: r(y), r: rad }),
      bolt: (path, branches) => emit({ k: 'bolt', path: flatPath(path), br: branches.map(flatPath) }),
      spark: (x, y) => emit({ k: 'spark', x: r(x), y: r(y) }),
      projectileGone: (e) => emit({ k: 'gone', x: r(e.body.position.x), y: r(e.body.position.y) }),
      termite: (x, y, target) => emit({ k: 'termite', x: r(x), y: r(y), n: target?.nid ?? -1 }),
      reflect: (x, y) => emit({ k: 'reflect', x: r(x), y: r(y) }),
    });
    this.world.onBeforeStep = (step) => {
      if (!this.ended) this.beforeStep(step);
    };
  }

  protected abstract beforeStep(step: number): void;
  protected abstract onCoreHit(cause: string): void;
  protected abstract tick(dt: number): void;
  protected abstract pill(): HTMLElement;

  /** Applica un tiro e ne riproduce l'effetto di lancio (come farebbe l'attaccante). */
  protected fire(s: Shot): WeaponId | null {
    const w = applyShot(this.world, s);
    if (!w) return null;
    const aim = WEAPONS[w].aim;
    playEffect(this.game, aim === 'sling' || aim === 'line' ? { k: 'shot', w } : w === 'wind' ? { k: 'wind' } : w === 'flood' ? { k: 'flood' } : w === 'sonar' ? { k: 'echo' } : { k: 'shot', w }, this.fx);
    this.hud.hint.textContent = `${WEAPONS[w].name}! ${WEAPONS[w].desc}`;
    return w;
  }

  enter(): void {
    this.game.ui.hud(this.buildHud());
  }

  exit(): void {
    this.game.ui.hud(null);
  }

  update(dt: number): void {
    this.world.step(dt * this.speed);
    updateEffects(this.game, this.fx, dt, this.world);
    if (this.world.windMs > 0) for (let k = 0; k < 2; k++) this.game.particles.streak(rand(-200, 900), rand(250, 930));
    this.tick(dt);
  }

  render(g: CanvasRenderingContext2D, t: number): void {
    drawHunter(g, t, { ...hunterMood(this.fx), cast: false });
    drawLauncher(g, t, null, null, this.fx.recoil);
    drawWorld(g, this.world, t, {
      creature: (e) => (e.kind === 'core' ? { style: 'live', alpha: 1, ...mimikaMood(this.fx) } : { style: 'decoy', alpha: 1 }),
      look: { x: WORLD.LAUNCH_X, y: WORLD.LAUNCH_Y },
    });
    drawEffects(g, this.fx, t);
  }

  camera(): CamFocus | null {
    return battleFocus(this.world, this.fx, false);
  }

  key(e: KeyboardEvent): void {
    if (e.key === 'f' || e.key === 'F') this.toggleSpeed();
  }

  protected toggleSpeed(): void {
    this.speed = this.speed === 1 ? 2 : 1;
    this.hud.speed.querySelector('span')!.textContent = `×${this.speed}`;
    this.game.sfx.click();
  }

  protected abstract quit(): void;

  private buildHud(): HTMLElement {
    const hint = h('div', { class: 'hint' });
    const stats = h('div', { class: 'stats' });
    const info = h('div', { class: 'timer auto-info' });
    const speed = h('button', { class: 'btn small', 'aria-label': 'Velocità', onclick: () => this.toggleSpeed(),
      'data-tip': tip('Velocità (F)', "Guarda l'assedio a velocità doppia.") }, icon(ICONS.fast), h('span', {}, '×1'));
    this.hud = { hint, stats, info, speed };
    return h('div', { class: 'hud spectate-hud auto-hud' },
      h('div', { class: 'hud-top' }, this.pill(), info, h('div', { class: 'hud-actions' }, speed, stats)),
      hint,
      h('button', { class: 'quit-btn', 'aria-label': 'Esci', 'data-tip': 'Esci', onclick: () => this.quit() }, icon(ICONS.back)),
    );
  }
}

// ---------------------------------------------------------------------------- replay del referto

export interface ReplayOptions {
  shots: Shot[];
  end: number;
  claimed: 'attacker' | 'defender';
  attacker: string;
  defender: string;
  onDone(): void;
}

/** Rigioca la battaglia di un referto: stessi tiri agli stessi passi. */
export class ReplayScene extends AutoSiegeScene {
  private i = 0;
  private outro = 0;

  constructor(game: Game, bp: Blueprint, private readonly o: ReplayOptions) {
    super(game, bp);
  }

  enter(): void {
    super.enter();
    this.hud.hint.textContent = `${this.o.attacker} all'attacco della fortezza di ${this.o.defender}.`;
    this.hud.stats.textContent = `Colpi 0/${this.o.shots.length}`;
  }

  protected pill(): HTMLElement {
    return h('div', { class: 'role-pill neutral' }, h('b', {}, 'REPLAY'), h('span', {}, `${this.o.attacker} vs ${this.o.defender}`));
  }

  protected beforeStep(step: number): void {
    while (this.i < this.o.shots.length && this.o.shots[this.i][0] <= step) {
      this.fire(this.o.shots[this.i++]);
      this.hud.stats.textContent = `Colpi ${this.i}/${this.o.shots.length}`;
    }
    const limit = this.o.end + (this.o.claimed === 'attacker' ? 1 : 0);
    if (step >= limit) this.finish(this.o.claimed === 'attacker' ? 'il replay non trova la cattura' : 'Mimika resiste');
  }

  protected onCoreHit(cause: string): void {
    this.finish(`Mimika presa: ${cause}`);
  }

  private finish(text: string): void {
    if (this.ended) return;
    this.ended = true;
    this.outro = 2600;
    this.hud.hint.textContent = `Fine del replay — ${text}.`;
    const c = this.world.core.body.position;
    const atk = this.world.coreHit;
    playEffect(this.game, { k: 'end', winner: atk ? 'attacker' : 'defender', cause: text, x: Math.round(c.x), y: Math.round(c.y) }, this.fx);
  }

  protected tick(dt: number): void {
    this.hud.info.textContent = `${Math.floor(this.world.steps / 60)} s`;
    if (this.ended && (this.outro -= dt) <= 0) this.quit();
  }

  protected quit(): void {
    this.o.onDone();
  }
}

// ---------------------------------------------------------------------------- sopravvivenza

export interface SurvivalResult {
  /** ondate superate (quella in cui Mimika è stata presa non conta) */
  waves: number;
  cause: string;
  shots: number;
  broken: number;
  seconds: number;
}

export interface SurvivalOptions {
  defender: string;
  seed: number;
  onDone(r: SurvivalResult): void;
  onQuit(): void;
}

const WAVE_PAUSE = 2600;

/** Il Cacciatore automatico attacca a ondate sempre più precise la stessa fortezza (i danni restano). */
export class SurvivalScene extends AutoSiegeScene {
  private bot: Bot;
  private wave = 1;
  private pause = WAVE_PAUSE;
  private waveSteps = 0;
  private lastShot = 0;
  private outro = 0;
  private cause = '';
  private shots = 0;

  constructor(game: Game, bp: Blueprint, private readonly o: SurvivalOptions) {
    super(game, bp);
    this.bot = this.newBot();
  }

  /** skill del Cacciatore: cresce a ogni ondata */
  static skill(wave: number): number {
    return Math.min(0.95, 0.25 + (wave - 1) * 0.14);
  }

  private newBot(): Bot {
    return new Bot(this.mode.arsenal, { seed: this.o.seed + this.wave * 7919, skill: SurvivalScene.skill(this.wave) });
  }

  enter(): void {
    super.enter();
    this.announce();
  }

  protected pill(): HTMLElement {
    return h('div', { class: 'role-pill def' }, h('b', {}, 'SOPRAVVIVENZA'), h('span', {}, `${this.o.defender} contro il Cacciatore`));
  }

  private announce(): void {
    this.hud.info.textContent = `Ondata ${this.wave}`;
    this.hud.hint.textContent = this.wave === 1
      ? 'Il Cacciatore automatico sta arrivando: la tua fortezza deve reggere quante più ondate possibile.'
      : `Ondata ${this.wave}: il Cacciatore ha di nuovo tutto l'arsenale e mira meglio. I danni restano!`;
    const c = this.world.core.body.position;
    this.game.particles.text(c.x, c.y - 60, `Ondata ${this.wave}`, '#ffd27a');
    this.game.sfx.ping();
  }

  protected beforeStep(step: number): void {
    if (this.pause > 0) return;
    this.waveSteps++;
    const s = this.bot.next(this.world, step);
    if (s) {
      this.fire(s);
      this.shots++;
      this.lastShot = this.waveSteps;
    }
    const idle = this.waveSteps - this.lastShot;
    const over = this.waveSteps > this.mode.attackTime * 60;
    if ((this.bot.ammoLeft() === 0 && this.world.projectiles.length === 0 && idle > 90 && (this.world.isSettled() || idle > 420)) || over) this.nextWave();
  }

  private nextWave(): void {
    this.wave++;
    this.waveSteps = this.lastShot = 0;
    this.pause = WAVE_PAUSE;
    this.bot = this.newBot();
    this.announce();
  }

  protected onCoreHit(cause: string): void {
    if (this.ended) return;
    this.ended = true;
    this.cause = cause;
    this.outro = 2800;
    const n = this.wave - 1;
    this.hud.hint.textContent = `Mimika presa all'ondata ${this.wave} (${cause}). Ondate superate: ${n}.`;
    const c = this.world.core.body.position;
    playEffect(this.game, { k: 'end', winner: 'attacker', cause, x: Math.round(c.x), y: Math.round(c.y) }, this.fx);
  }

  protected tick(dt: number): void {
    if (this.pause > 0) this.pause -= dt * this.speed;
    const left = WEAPON_ORDER.filter((w) => this.bot.ammo[w] > 0).map((w) => `${WEAPONS[w].name} ${this.bot.ammo[w]}`).join(' · ');
    this.hud.stats.textContent = this.pause > 0 ? 'In arrivo…' : left || 'Arsenale finito';
    if (this.ended && (this.outro -= dt) <= 0) {
      this.outro = Infinity; // una sola volta
      this.o.onDone({ waves: this.wave - 1, cause: this.cause, shots: this.shots, broken: this.world.broken, seconds: Math.round(this.world.steps / 60) });
    }
  }

  protected quit(): void {
    this.o.onQuit();
  }
}
