import { MATERIALS, type MaterialId } from '../config/materials';
import { mulberry32 } from '../core/math';
import { PALETTE, roundRectPath } from './palette';

/**
 * Sprite dei blocchi generati proceduralmente e messi in cache.
 * Nessun asset esterno: ogni materiale ha una texture "dipinta" + dettagli per cella.
 * Risoluzione 2x rispetto alle unità mondo => nitidi anche su schermi retina.
 */
const RES = 2;
const PAD = 4;
const CELL = 40;

const textures = new Map<MaterialId, HTMLCanvasElement>();
const cache = new Map<string, HTMLCanvasElement>();

function canvas(w: number, h: number): [HTMLCanvasElement, CanvasRenderingContext2D] {
  const c = document.createElement('canvas');
  c.width = Math.ceil(w);
  c.height = Math.ceil(h);
  return [c, c.getContext('2d')!];
}

function texture(mat: MaterialId): HTMLCanvasElement {
  const existing = textures.get(mat);
  if (existing) return existing;
  const S = 128;
  const [c, g] = canvas(S, S);
  const m = MATERIALS[mat];
  const rng = mulberry32(mat.length * 977);
  g.fillStyle = m.color;
  g.fillRect(0, 0, S, S);
  if (mat === 'wood') {
    for (let y = 0; y < S; y += 3) {
      g.strokeStyle = rng() > 0.5 ? 'rgba(90,45,15,0.22)' : 'rgba(255,220,170,0.12)';
      g.lineWidth = 1 + rng();
      g.beginPath();
      for (let x = 0; x <= S; x += 8) g.lineTo(x, y + Math.sin(x * 0.05 + y) * 1.4);
      g.stroke();
    }
    for (let i = 0; i < 3; i++) {
      const kx = rng() * S, ky = rng() * S;
      g.strokeStyle = 'rgba(80,40,15,0.35)';
      g.beginPath();
      g.ellipse(kx, ky, 5, 2.5, 0, 0, Math.PI * 2);
      g.stroke();
    }
  } else if (mat === 'stone') {
    for (let i = 0; i < 90; i++) {
      g.fillStyle = rng() > 0.5 ? 'rgba(255,255,255,0.06)' : 'rgba(20,20,50,0.08)';
      g.beginPath();
      g.arc(rng() * S, rng() * S, 2 + rng() * 9, 0, Math.PI * 2);
      g.fill();
    }
  } else if (mat === 'metal') {
    for (let y = 0; y < S; y += 2) {
      g.fillStyle = `rgba(255,255,255,${rng() * 0.07})`;
      g.fillRect(0, y, S, 1);
    }
  } else if (mat === 'moss') {
    for (let i = 0; i < 140; i++) {
      g.fillStyle = rng() > 0.6 ? 'rgba(20,70,30,0.25)' : 'rgba(210,255,170,0.18)';
      g.beginPath();
      g.arc(rng() * S, rng() * S, 1 + rng() * 3.5, 0, Math.PI * 2);
      g.fill();
    }
  }
  textures.set(mat, c);
  return c;
}

/** Livello crepe: 0 integro, 1 incrinato, 2 a pezzi. */
export function crackLevel(hp: number, maxHp: number): number {
  const r = hp / maxHp;
  return r > 0.66 ? 0 : r > 0.33 ? 1 : 2;
}

export function getBlockSprite(mat: MaterialId, w: number, h: number, crack: number, seed: number): HTMLCanvasElement {
  const key = `${mat}|${w}|${h}|${crack}|${seed % 5}`;
  const hit = cache.get(key);
  if (hit) return hit;
  const [c, g] = canvas((w + PAD * 2) * RES, (h + PAD * 2) * RES);
  g.scale(RES, RES);
  g.translate(PAD, PAD);
  paintBlock(g, mat, w, h, crack, seed % 5);
  cache.set(key, c);
  return c;
}

export const SPRITE_PAD = PAD;

function paintBlock(g: CanvasRenderingContext2D, mat: MaterialId, W: number, H: number, crack: number, seed: number): void {
  const m = MATERIALS[mat];
  const rng = mulberry32(seed * 131 + W * 7 + H);
  const cols = Math.round(W / CELL);
  const rows = Math.round(H / CELL);
  const radius = mat === 'moss' ? 10 : mat === 'glass' ? 4 : mat === 'silk' ? 8 : 6;

  roundRectPath(g, 0, 0, W, H, radius);
  g.save();
  g.clip();

  if (mat === 'glass') {
    const gr = g.createLinearGradient(0, 0, W, H);
    gr.addColorStop(0, 'rgba(225,250,255,0.78)');
    gr.addColorStop(0.5, 'rgba(150,220,240,0.45)');
    gr.addColorStop(1, 'rgba(90,170,210,0.6)');
    g.fillStyle = gr;
    g.fillRect(0, 0, W, H);
    for (let cx = 0; cx < cols; cx++)
      for (let cy = 0; cy < rows; cy++) {
        const ox = cx * CELL, oy = cy * CELL;
        g.strokeStyle = 'rgba(255,255,255,0.75)';
        g.lineWidth = 3;
        g.beginPath();
        g.moveTo(ox + 8, oy + 22);
        g.lineTo(ox + 20, oy + 8);
        g.stroke();
        g.lineWidth = 1.5;
        g.beginPath();
        g.moveTo(ox + 12, oy + 28);
        g.lineTo(ox + 27, oy + 12);
        g.stroke();
        g.strokeStyle = 'rgba(60,140,170,0.35)';
        g.strokeRect(ox + 0.5, oy + 0.5, CELL - 1, CELL - 1);
      }
  } else if (mat === 'silk') {
    paintSilk(g, W, H, cols, rows, rng);
  } else {
    g.fillStyle = g.createPattern(texture(mat), 'repeat')!;
    g.save();
    g.translate(-seed * 23, -seed * 17);
    g.fillRect(seed * 23, seed * 17, W, H);
    g.restore();
  }

  if (mat === 'wood') {
    const horizontal = W >= H;
    const step = 20;
    g.strokeStyle = 'rgba(70,35,12,0.55)';
    g.lineWidth = 1.6;
    const span = horizontal ? H : W;
    for (let s = step; s < span; s += step) {
      g.beginPath();
      if (horizontal) { g.moveTo(0, s); g.lineTo(W, s); } else { g.moveTo(s, 0); g.lineTo(s, H); }
      g.stroke();
    }
    g.fillStyle = '#3a2210';
    for (let s = step / 2; s < span; s += step) {
      const len = horizontal ? W : H;
      for (const t of [6, len - 6]) {
        g.beginPath();
        if (horizontal) g.arc(t, s, 1.8, 0, Math.PI * 2); else g.arc(s, t, 1.8, 0, Math.PI * 2);
        g.fill();
      }
    }
  } else if (mat === 'stone') {
    g.fillStyle = m.dark;
    g.globalAlpha = 0.55;
    g.fillRect(0, 0, W, H);
    g.globalAlpha = 1;
    for (let cx = 0; cx < cols; cx++)
      for (let cy = 0; cy < rows; cy++) {
        const ox = cx * CELL + 2.5, oy = cy * CELL + 2.5, s = CELL - 5;
        roundRectPath(g, ox, oy, s, s, 8);
        const shade = 0.85 + rng() * 0.25;
        g.fillStyle = shadeColor(m.color, shade);
        g.fill();
        g.save();
        g.clip();
        g.fillStyle = g.createPattern(texture('stone'), 'repeat')!;
        g.globalAlpha = 0.6;
        g.fillRect(ox, oy, s, s);
        g.globalAlpha = 1;
        g.fillStyle = 'rgba(255,255,255,0.22)';
        g.fillRect(ox, oy, s, 4);
        g.fillStyle = 'rgba(20,15,50,0.22)';
        g.fillRect(ox, oy + s - 5, s, 5);
        g.restore();
      }
  } else if (mat === 'metal') {
    const gr = g.createLinearGradient(0, 0, 0, H);
    gr.addColorStop(0, 'rgba(255,255,255,0.28)');
    gr.addColorStop(0.45, 'rgba(255,255,255,0)');
    gr.addColorStop(1, 'rgba(0,0,20,0.3)');
    g.fillStyle = gr;
    g.fillRect(0, 0, W, H);
    g.strokeStyle = 'rgba(15,20,30,0.5)';
    g.lineWidth = 1.4;
    for (let cx = 1; cx < cols; cx++) { g.beginPath(); g.moveTo(cx * CELL, 0); g.lineTo(cx * CELL, H); g.stroke(); }
    for (let cy = 1; cy < rows; cy++) { g.beginPath(); g.moveTo(0, cy * CELL); g.lineTo(W, cy * CELL); g.stroke(); }
    for (let cx = 0; cx < cols; cx++)
      for (let cy = 0; cy < rows; cy++)
        for (const [rx, ry] of [[6, 6], [CELL - 6, 6], [6, CELL - 6], [CELL - 6, CELL - 6]]) {
          const x = cx * CELL + rx, y = cy * CELL + ry;
          g.fillStyle = 'rgba(10,15,25,0.55)';
          g.beginPath(); g.arc(x + 0.6, y + 0.8, 2.4, 0, Math.PI * 2); g.fill();
          g.fillStyle = m.light;
          g.beginPath(); g.arc(x, y, 2.1, 0, Math.PI * 2); g.fill();
        }
    g.strokeStyle = 'rgba(255,255,255,0.3)';
    g.lineWidth = 6;
    g.beginPath(); g.moveTo(W * 0.15, H + 4); g.lineTo(W * 0.15 + H, -4); g.stroke();
  } else if (mat === 'moss') {
    for (let i = 0; i < cols * rows * 5; i++) {
      g.fillStyle = rng() > 0.5 ? 'rgba(190,245,140,0.45)' : 'rgba(30,90,45,0.35)';
      g.beginPath();
      g.arc(rng() * W, rng() * H, 3 + rng() * 6, 0, Math.PI * 2);
      g.fill();
    }
    const flowers = Math.floor(rng() * 3 * cols * rows * 0.5) + 1;
    for (let i = 0; i < flowers; i++) {
      const x = 6 + rng() * (W - 12), y = 6 + rng() * (H - 12);
      g.fillStyle = rng() > 0.5 ? '#ff9ec7' : '#ffe17a';
      for (let p = 0; p < 5; p++) {
        const a = (p / 5) * Math.PI * 2;
        g.beginPath(); g.arc(x + Math.cos(a) * 2.4, y + Math.sin(a) * 2.4, 1.8, 0, Math.PI * 2); g.fill();
      }
      g.fillStyle = '#fff6d0';
      g.beginPath(); g.arc(x, y, 1.3, 0, Math.PI * 2); g.fill();
    }
  }

  // smussatura: luce in alto, ombra in basso (stile carta ritagliata)
  g.fillStyle = 'rgba(255,255,255,0.2)';
  g.fillRect(0, 0, W, 3.5);
  g.fillStyle = 'rgba(10,5,30,0.22)';
  g.fillRect(0, H - 4, W, 4);

  if (crack > 0) drawCracks(g, W, H, crack, rng);
  g.restore();

  roundRectPath(g, 0, 0, W, H, radius);
  g.strokeStyle = mat === 'glass' ? 'rgba(40,110,140,0.9)' : mat === 'silk' ? '#3b2b6e' : PALETTE.ink;
  g.lineWidth = 2.2;
  g.stroke();
}

/**
 * Seta specchiante: drappo lilla tessuto fitto, con bande iridescenti nei colori della palette
 * (menta, oro, corallo: le tre "voci" del gioco) e un riflesso a specchio come il cristallo.
 */
function paintSilk(g: CanvasRenderingContext2D, W: number, H: number, cols: number, rows: number, rng: () => number): void {
  const base = g.createLinearGradient(0, 0, W, H);
  base.addColorStop(0, '#ece4ff');
  base.addColorStop(0.35, '#b8a5ee');
  base.addColorStop(0.6, '#d8ccfb');
  base.addColorStop(1, '#8a76cc');
  g.fillStyle = base;
  g.fillRect(0, 0, W, H);
  // bande iridescenti in diagonale
  const bands: [string, number, number][] = [['rgba(94,230,197,0.34)', 0.16, 14], ['rgba(255,210,122,0.4)', 0.42, 10], ['rgba(255,122,107,0.24)', 0.66, 16], ['rgba(203,184,255,0.5)', 0.86, 8]];
  for (const [color, at, width] of bands) {
    const x0 = at * (W + H) - H + (rng() - 0.5) * 10;
    g.fillStyle = color;
    g.beginPath();
    g.moveTo(x0, H);
    g.lineTo(x0 + H, 0);
    g.lineTo(x0 + H + width, 0);
    g.lineTo(x0 + width, H);
    g.closePath();
    g.fill();
  }
  // trama: fili chiari in orizzontale, ombre sottili in verticale
  g.lineWidth = 0.8;
  g.strokeStyle = 'rgba(255,255,255,0.2)';
  for (let y = 2; y < H; y += 4) { g.beginPath(); g.moveTo(0, y); g.lineTo(W, y); g.stroke(); }
  g.strokeStyle = 'rgba(60,40,120,0.14)';
  for (let x = 2; x < W; x += 4) { g.beginPath(); g.moveTo(x, 0); g.lineTo(x, H); g.stroke(); }
  // pieghe morbide del drappo, una per cella
  for (let cx = 0; cx < cols; cx++)
    for (let cy = 0; cy < rows; cy++) {
      const ox = cx * CELL, oy = cy * CELL;
      g.strokeStyle = 'rgba(70,50,140,0.28)';
      g.lineWidth = 2;
      g.beginPath();
      g.moveTo(ox + 6, oy + 30);
      g.bezierCurveTo(ox + 14, oy + 18 + rng() * 6, ox + 24, oy + 34, ox + 34, oy + 14);
      g.stroke();
      g.strokeStyle = 'rgba(255,255,255,0.85)';
      g.lineWidth = 2.4;
      g.beginPath();
      g.moveTo(ox + 7, oy + 15);
      g.lineTo(ox + 15, oy + 7);
      g.stroke();
      g.fillStyle = '#fff3d6';
      g.beginPath();
      g.arc(ox + 30, oy + 10, 1.6, 0, Math.PI * 2);
      g.fill();
    }
}

function drawCracks(g: CanvasRenderingContext2D, W: number, H: number, level: number, rng: () => number): void {
  const n = level === 1 ? 2 : 5;
  for (let i = 0; i < n; i++) {
    let x = rng() * W, y = rng() < 0.5 ? 0 : H;
    const pts: [number, number][] = [[x, y]];
    const dir = y === 0 ? 1 : -1;
    for (let s = 0; s < 4 + level * 2; s++) {
      x += (rng() - 0.5) * 14;
      y += dir * (4 + rng() * 8);
      pts.push([x, y]);
    }
    for (const [color, width, off] of [['rgba(255,255,255,0.35)', 1.2, 0.9], ['rgba(20,8,30,0.85)', 1.6, 0]] as const) {
      g.strokeStyle = color;
      g.lineWidth = width;
      g.beginPath();
      pts.forEach(([px, py], k) => (k ? g.lineTo(px + off, py + off) : g.moveTo(px + off, py + off)));
      g.stroke();
    }
  }
}

function shadeColor(hex: string, f: number): string {
  const n = parseInt(hex.slice(1), 16);
  const r = Math.min(255, ((n >> 16) & 255) * f) | 0;
  const g = Math.min(255, ((n >> 8) & 255) * f) | 0;
  const b = Math.min(255, (n & 255) * f) | 0;
  return `rgb(${r},${g},${b})`;
}
