import { WORLD } from '../config/world';
import { mulberry32 } from '../core/math';
import type { AmbientTheme } from './themes';

export interface Camera {
  vw: number;
  vh: number;
  dpr: number;
  scale: number;
  ox: number;
  oy: number;
}

/**
 * Strato di sfondo pre-renderizzato. x/y/w/h in pixel CSS rispetto allo schermo a camera ferma;
 * f = profondità (0 = fermo come il cielo, 1 = si muove con il mondo).
 */
export interface BgLayer {
  canvas: HTMLCanvasElement;
  f: number;
  x: number;
  y: number;
  w: number;
  h: number;
}

/** Margine (px CSS) attorno agli strati: spazio per il movimento della camera. */
export const LAYER_MARGIN = 150;

/**
 * Dipinge il diorama di sfondo in strati separati (cielo, creste lontane, medie, vicine, suolo).
 * Si rigenera solo al resize o al cambio di tema: per frame costa un drawImage per strato.
 * flat = un solo strato fermo (qualità bassa: niente parallasse, un solo drawImage).
 */
export function paintBackground(cam: Camera, th: AmbientTheme, dpr: number, flat: boolean): BgLayer[] {
  if (flat) {
    const sky = paintSky(cam, th, dpr);
    const g = sky.canvas.getContext('2d')!;
    g.setTransform(dpr * cam.scale, 0, 0, dpr * cam.scale, dpr * cam.ox, dpr * cam.oy);
    paintFar(g, th);
    paintMid(g, th);
    paintNear(g, th);
    drawGround(g, th);
    return [sky];
  }
  return [
    paintSky(cam, th, dpr),
    layer(cam, dpr, 0.18, -400, (g) => paintFar(g, th)),
    layer(cam, dpr, 0.42, 600, (g) => paintMid(g, th)),
    layer(cam, dpr, 0.7, 820, (g) => paintNear(g, th)),
    layer(cam, dpr, 1, WORLD.GROUND_Y - 40, (g) => drawGround(g, th)),
  ];
}

/** Cielo in spazio schermo, ancorato all'orizzonte del mondo. Fermo. */
function paintSky(cam: Camera, th: AmbientTheme, dpr: number): BgLayer {
  const { vw, vh, scale: s, oy } = cam;
  const canvas = document.createElement('canvas');
  canvas.width = Math.round(vw * dpr);
  canvas.height = Math.round(vh * dpr);
  const g = canvas.getContext('2d')!;
  g.setTransform(dpr, 0, 0, dpr, 0, 0);
  const horizon = oy + (WORLD.GROUND_Y - 140) * s;
  const sky = g.createLinearGradient(0, 0, 0, Math.max(horizon, 10));
  sky.addColorStop(0, th.sky[0]);
  sky.addColorStop(0.45, th.sky[1]);
  sky.addColorStop(0.8, th.sky[2]);
  sky.addColorStop(1, th.sky[3]);
  g.fillStyle = sky;
  g.fillRect(0, 0, vw, vh);

  const rng = mulberry32(7);
  for (let i = 0; i < th.stars; i++) {
    const x = rng() * vw;
    const y = rng() * horizon * 0.65;
    const a = (1 - y / (horizon * 0.65)) * (0.3 + rng() * 0.7);
    g.fillStyle = `rgba(255,240,230,${a.toFixed(3)})`;
    g.beginPath();
    g.arc(x, y, rng() * 1.3 + 0.3, 0, Math.PI * 2);
    g.fill();
  }
  return { canvas, f: 0, x: 0, y: 0, w: vw, h: vh };
}

function layer(cam: Camera, dpr: number, f: number, topWorldY: number, paint: (g: CanvasRenderingContext2D) => void): BgLayer {
  const M = LAYER_MARGIN;
  const x = -M;
  const y = Math.max(-M, cam.oy + topWorldY * cam.scale - M);
  const w = cam.vw + 2 * M;
  const h = Math.max(1, cam.vh + M - y);
  const canvas = document.createElement('canvas');
  canvas.width = Math.round(w * dpr);
  canvas.height = Math.round(h * dpr);
  const g = canvas.getContext('2d')!;
  g.setTransform(dpr * cam.scale, 0, 0, dpr * cam.scale, dpr * (cam.ox - x), dpr * (cam.oy - y));
  paint(g);
  return { canvas, f, x, y, w, h };
}

function paintFar(g: CanvasRenderingContext2D, th: AmbientTheme): void {
  if (th.sun.moon) drawMoon(g, th); else drawSun(g, th);
  ridge(g, 11, 700, 190, th.ridges[0], 0.0035, th.rims[0], th.rimWidth);
  haze(g, 640, 900, th.haze[0], 0.35);
}

function paintMid(g: CanvasRenderingContext2D, th: AmbientTheme): void {
  ridge(g, 23, 820, 110, th.ridges[1], 0.006, th.rims[1], th.rimWidth * 0.8);
  pines(g, 31, 820, 110, th.ridges[1], !!th.snow);
  haze(g, 760, 940, th.haze[1], 0.3);
}

function paintNear(g: CanvasRenderingContext2D, th: AmbientTheme): void {
  ridge(g, 47, 895, 55, th.ridges[2], 0.009, th.rims[2], th.rimWidth * 0.7);
}

function drawSun(g: CanvasRenderingContext2D, th: AmbientTheme): void {
  const { x, y, r } = th.sun;
  const glow = g.createRadialGradient(x, y, r * 0.5, x, y, r * 3.4);
  glow.addColorStop(0, `rgba(${th.sun.glow},0.45)`);
  glow.addColorStop(1, `rgba(${th.sun.glow},0)`);
  g.fillStyle = glow;
  g.fillRect(x - r * 4, y - r * 4, r * 8, r * 8);
  const disc = g.createLinearGradient(0, y - r, 0, y + r);
  disc.addColorStop(0, th.sun.core);
  disc.addColorStop(1, th.sun.edge);
  g.fillStyle = disc;
  g.beginPath();
  g.arc(x, y, r, 0, Math.PI * 2);
  g.fill();
  // tagli orizzontali: sole "a fette di carta"
  g.fillStyle = th.sky[2];
  for (let i = 0; i < 5; i++) {
    const yy = y + r * 0.2 + i * r * 0.17;
    g.fillRect(x - r, yy, r * 2, 3 + i * 1.6);
  }
}

/** Luna di carta: disco con crateri ritagliati e alone freddo. */
function drawMoon(g: CanvasRenderingContext2D, th: AmbientTheme): void {
  const { x, y, r } = th.sun;
  const glow = g.createRadialGradient(x, y, r * 0.8, x, y, r * 4);
  glow.addColorStop(0, `rgba(${th.sun.glow},0.32)`);
  glow.addColorStop(1, `rgba(${th.sun.glow},0)`);
  g.fillStyle = glow;
  g.fillRect(x - r * 4, y - r * 4, r * 8, r * 8);
  const disc = g.createLinearGradient(x - r, y - r, x + r, y + r);
  disc.addColorStop(0, th.sun.core);
  disc.addColorStop(1, th.sun.edge);
  g.fillStyle = disc;
  g.beginPath();
  g.arc(x, y, r, 0, Math.PI * 2);
  g.fill();
  g.fillStyle = 'rgba(120,120,180,0.22)';
  for (const [cx, cy, cr] of [[-0.3, -0.2, 0.22], [0.25, 0.3, 0.16], [0.35, -0.35, 0.1], [-0.15, 0.45, 0.09]]) {
    g.beginPath();
    g.arc(x + cx * r, y + cy * r, cr * r, 0, Math.PI * 2);
    g.fill();
  }
}

function ridgeY(x: number, base: number, amp: number, freq: number, p: number[]): number {
  const n = 0.55 * Math.sin(x * freq + p[0]) + 0.3 * Math.sin(x * freq * 2.7 + p[1]) + 0.15 * Math.sin(x * freq * 6.1 + p[2]);
  return base - amp * (0.5 + 0.5 * n);
}

function ridge(g: CanvasRenderingContext2D, seed: number, base: number, amp: number, color: string, freq: number, rim: string, rimWidth: number): void {
  const rng = mulberry32(seed);
  const p = [rng() * 10, rng() * 10, rng() * 10];
  g.beginPath();
  g.moveTo(-2000, 1600);
  for (let x = -2000; x <= 4000; x += 12) g.lineTo(x, ridgeY(x, base, amp, freq, p));
  g.lineTo(4000, 1600);
  g.closePath();
  g.fillStyle = color;
  g.fill();
  g.beginPath();
  for (let x = -2000; x <= 4000; x += 12) g.lineTo(x, ridgeY(x, base, amp, freq, p) + rimWidth * 0.6);
  g.strokeStyle = rim;
  g.lineWidth = rimWidth;
  g.stroke();
}

function pines(g: CanvasRenderingContext2D, seed: number, base: number, amp: number, color: string, snowy: boolean): void {
  const rng = mulberry32(23);
  const p = [rng() * 10, rng() * 10, rng() * 10];
  const r2 = mulberry32(seed);
  for (let x = -600; x < 2600; x += 30 + r2() * 70) {
    const y = ridgeY(x, base, amp, 0.006, p) + 4;
    const h = 30 + r2() * 50;
    for (let k = 0; k < 3; k++) {
      const ty = y - h * (k * 0.28);
      const w = (h * 0.42) * (1 - k * 0.22);
      g.fillStyle = shade(color);
      g.beginPath();
      g.moveTo(x - w, ty);
      g.lineTo(x, ty - h * 0.5);
      g.lineTo(x + w, ty);
      g.closePath();
      g.fill();
      if (snowy) {
        // cappuccio di neve su ogni palco
        g.fillStyle = 'rgba(245,245,255,0.85)';
        g.beginPath();
        g.moveTo(x - w * 0.45, ty - h * 0.28);
        g.lineTo(x, ty - h * 0.5);
        g.lineTo(x + w * 0.45, ty - h * 0.28);
        g.closePath();
        g.fill();
      }
    }
  }
}

function shade(hex: string): string {
  const n = parseInt(hex.slice(1), 16);
  return `rgb(${((n >> 16) & 255) * 0.8 | 0},${((n >> 8) & 255) * 0.8 | 0},${(n & 255) * 0.85 | 0})`;
}

function haze(g: CanvasRenderingContext2D, y0: number, y1: number, rgb: string, a: number): void {
  const gr = g.createLinearGradient(0, y0, 0, y1);
  gr.addColorStop(0, `rgba(${rgb},0)`);
  gr.addColorStop(1, `rgba(${rgb},${a})`);
  g.fillStyle = gr;
  g.fillRect(-2000, y0, 6000, y1 - y0);
}

function drawGround(g: CanvasRenderingContext2D, th: AmbientTheme): void {
  const Y = WORLD.GROUND_Y;
  const soil = g.createLinearGradient(0, Y, 0, Y + 400);
  soil.addColorStop(0, th.soil);
  soil.addColorStop(1, th.soilDeep);
  g.fillStyle = soil;
  g.fillRect(-2000, Y, 6000, 800);

  const rng = mulberry32(99);
  // strati del terreno
  for (let k = 0; k < 4; k++) {
    g.strokeStyle = `rgba(255,180,200,${0.07 - k * 0.012})`;
    g.lineWidth = 2;
    g.beginPath();
    const yy = Y + 40 + k * 38;
    for (let x = -2000; x <= 4000; x += 20) g.lineTo(x, yy + Math.sin(x * 0.01 + k * 2) * 6);
    g.stroke();
  }
  for (let i = 0; i < 220; i++) {
    g.fillStyle = `rgba(20,10,30,${0.25 + rng() * 0.3})`;
    g.beginPath();
    g.ellipse(-400 + rng() * 2800, Y + 20 + rng() * 200, 2 + rng() * 6, 1.5 + rng() * 3, 0, 0, Math.PI * 2);
    g.fill();
  }
  // manto erboso (o innevato)
  g.fillStyle = th.grass;
  g.fillRect(-2000, Y - 2, 6000, 14);
  g.fillStyle = th.grassTop;
  g.fillRect(-2000, Y - 3, 6000, 4);
  if (th.snow) {
    for (let x = -600; x < 2600; x += 20 + rng() * 40) {
      g.fillStyle = rng() > 0.5 ? th.grass : th.grassTop;
      g.beginPath();
      g.ellipse(x, Y + 1, 18 + rng() * 30, 4 + rng() * 6, 0, Math.PI, 0);
      g.fill();
    }
    return;
  }
  for (let x = -600; x < 2600; x += 5 + rng() * 9) {
    const h = 6 + rng() * 14;
    g.fillStyle = rng() > 0.4 ? th.grass : th.grassTop;
    g.beginPath();
    g.moveTo(x - 3, Y + 2);
    g.quadraticCurveTo(x + rng() * 4, Y - h * 0.6, x + (rng() - 0.3) * 6, Y - h);
    g.lineTo(x + 3, Y + 2);
    g.closePath();
    g.fill();
  }
}

/** Vignettatura (sopra a tutto). */
export function paintVignette(target: HTMLCanvasElement, cam: Camera): void {
  target.width = Math.round(cam.vw * cam.dpr);
  target.height = Math.round(cam.vh * cam.dpr);
  const g = target.getContext('2d')!;
  const w = target.width, h = target.height;
  const gr = g.createRadialGradient(w / 2, h * 0.55, Math.min(w, h) * 0.35, w / 2, h * 0.55, Math.max(w, h) * 0.75);
  gr.addColorStop(0, 'rgba(10,5,25,0)');
  gr.addColorStop(1, 'rgba(10,5,25,0.55)');
  g.fillStyle = gr;
  g.fillRect(0, 0, w, h);
}

export function makeGrain(): HTMLCanvasElement {
  const c = document.createElement('canvas');
  c.width = c.height = 128;
  const g = c.getContext('2d')!;
  const img = g.createImageData(128, 128);
  for (let i = 0; i < img.data.length; i += 4) {
    const v = Math.random() * 255;
    img.data[i] = img.data[i + 1] = img.data[i + 2] = v;
    img.data[i + 3] = 255;
  }
  g.putImageData(img, 0, 0);
  return c;
}
