/**
 * PWA: service worker per l'uso offline e invito all'installazione.
 * - Solo nella build di produzione (in sviluppo il SW intralcerebbe l'hot reload).
 * - Non nelle app native Capacitor (i file sono già locali).
 * - I link #c= #r= #o= #a= non sono toccati: il frammento dopo # non arriva mai al service worker.
 */
interface InstallPromptEvent extends Event {
  prompt(): Promise<void>;
  userChoice: Promise<{ outcome: 'accepted' | 'dismissed' }>;
}

let deferred: InstallPromptEvent | null = null;

export function registerPwa(): void {
  window.addEventListener('beforeinstallprompt', (e) => {
    e.preventDefault(); // lo proponiamo noi, dalle impostazioni
    deferred = e as InstallPromptEvent;
  });
  window.addEventListener('appinstalled', () => (deferred = null));
  const native = (window as unknown as { Capacitor?: { isNativePlatform?: () => boolean } }).Capacitor?.isNativePlatform?.();
  if (!import.meta.env.PROD || native || !('serviceWorker' in navigator)) return;
  window.addEventListener('load', () => {
    navigator.serviceWorker.register('./sw.js').catch(() => {
      /* offline non disponibile (es. http non sicuro): il gioco funziona lo stesso */
    });
  });
}

export const canInstall = (): boolean => deferred !== null;

export async function promptInstall(): Promise<boolean> {
  if (!deferred) return false;
  const ev = deferred;
  deferred = null;
  await ev.prompt();
  return (await ev.userChoice).outcome === 'accepted';
}
