/**
 * "Cassetta postale" cifrata per il signaling del duello live, su ntfy.sh (servizio pubblico gratuito,
 * nessun account). Serve a due cose: inviti corti (#o=m + 22 caratteri) e risposta automatica
 * (chi invita non deve aprire nessun link di ritorno).
 *
 * Il link contiene solo un segreto casuale di 16 byte. Da lì si ricavano:
 *   topic  = "mimika-" + SHA-256("topic|segreto")   → il server vede solo questo nome
 *   chiave = SHA-256("key|segreto") come AES-GCM 256 → offerta e risposta viaggiano cifrate
 * ntfy.sh conserva i messaggi al massimo 12 ore e non può leggerli. Se non risponde, il duello
 * ripiega sul signaling manuale (link lunghi #o= / #a=, vedi webrtc.ts).
 */
const RELAY = 'https://ntfy.sh';

export type RelayMsg =
  /** l'ospite ha aperto l'invito: n = suo identificativo di sessione */
  | { t: 'join'; n: string; name: string }
  /** chi invita risponde a quel join con un'offerta fresca */
  | { t: 'offer'; n: string; sdp: string }
  | { t: 'answer'; n: string; sdp: string };

export interface Room {
  secret: string;
  topic: string;
  key: CryptoKey;
}

const enc = new TextEncoder();

function b64url(bytes: Uint8Array): string {
  let bin = '';
  for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
  return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function unb64url(s: string): Uint8Array<ArrayBuffer> {
  const bin = atob(s.replace(/-/g, '+').replace(/_/g, '/'));
  return Uint8Array.from(bin, (c) => c.charCodeAt(0));
}

const sha = async (text: string) => new Uint8Array(await crypto.subtle.digest('SHA-256', enc.encode(text)));

/** true se il browser ha ciò che serve (WebCrypto + EventSource). */
export const relaySupported = () => typeof crypto?.subtle?.digest === 'function' && typeof EventSource !== 'undefined';

export const isRoomCode = (code: string) => /^m[A-Za-z0-9_-]{22}$/.test(code);

/** Identificativo casuale corto (sessione dell'ospite). */
export const randomId = () => b64url(crypto.getRandomValues(new Uint8Array(9)));

export async function openRoom(secret: string): Promise<Room> {
  const topic = 'mimika-' + b64url(await sha(`topic|${secret}`)).slice(0, 24);
  const key = await crypto.subtle.importKey('raw', await sha(`key|${secret}`), 'AES-GCM', false, ['encrypt', 'decrypt']);
  return { secret, topic, key };
}

export async function newRoom(): Promise<Room> {
  return openRoom(b64url(crypto.getRandomValues(new Uint8Array(16))));
}

/** Codice da mettere nel link d'invito (#o=…). */
export const roomCode = (room: Room) => 'm' + room.secret;

/** Imbuca un messaggio cifrato; riprova con attese crescenti (rete appena tornata, telefono che si risveglia). */
export async function post(room: Room, msg: RelayMsg, tries = 6): Promise<boolean> {
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const data = new Uint8Array(await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, room.key, enc.encode(JSON.stringify(msg))));
  const body = `${b64url(iv)}.${b64url(data)}`;
  for (let i = 0; i < tries; i++) {
    try {
      const res = await fetch(`${RELAY}/${room.topic}`, { method: 'POST', body });
      if (res.ok) return true;
      console.info(`[relay] invio rifiutato (${res.status}), riprovo`);
    } catch {
      /* rete assente: si riprova */
    }
    await new Promise((r) => setTimeout(r, 1000 * 2 ** Math.min(i, 3)));
  }
  return false;
}

async function open(room: Room, body: string): Promise<RelayMsg | null> {
  try {
    const [iv, data] = body.split('.');
    const plain = await crypto.subtle.decrypt({ name: 'AES-GCM', iv: unb64url(iv) }, room.key, unb64url(data));
    const msg = JSON.parse(new TextDecoder().decode(plain)) as RelayMsg;
    return msg && typeof msg.t === 'string' && typeof msg.n === 'string' ? msg : null;
  } catch {
    return null; // non cifrato con la nostra chiave: rumore di qualcun altro sullo stesso topic, ignorato
  }
}

/**
 * Ascolta la cassetta (Server-Sent Events, riconnessione automatica anche dopo il background del telefono).
 * Ogni messaggio arriva una sola volta (si ripete da "since=all" a ogni riconnessione: i doppioni sono scartati).
 * onDown: il servizio non risponde da downMs (per ripiegare sul metodo manuale).
 */
export function listen(room: Room, onMsg: (m: RelayMsg) => void, onDown?: () => void, downMs = 9000): () => void {
  const seen = new Set<string>();
  let alive = false;
  let stopped = false;
  let es: EventSource;
  let retry: ReturnType<typeof setTimeout> | undefined;
  const connect = () => {
    es = new EventSource(`${RELAY}/${room.topic}/sse?since=all`);
    es.onopen = () => (alive = true);
    es.onmessage = (e) => {
      alive = true;
      let ev: { id?: string; event?: string; message?: string };
      try {
        ev = JSON.parse(e.data);
      } catch {
        return;
      }
      if (ev.event !== 'message' || !ev.id || !ev.message || seen.has(ev.id)) return;
      seen.add(ev.id);
      void open(room, ev.message).then((m) => m && !stopped && onMsg(m));
    };
    // di solito EventSource si riconnette da solo; se il browser la chiude del tutto (Safari in background), la si riapre
    es.onerror = () => {
      if (es.readyState === EventSource.CLOSED && !stopped) retry = setTimeout(connect, 3000);
    };
  };
  const onVisible = () => {
    if (document.visibilityState === 'visible' && es.readyState === EventSource.CLOSED && !stopped) connect();
  };
  connect();
  document.addEventListener('visibilitychange', onVisible);
  const downTimer = setTimeout(() => !alive && onDown?.(), downMs);
  return () => {
    stopped = true;
    clearTimeout(downTimer);
    clearTimeout(retry);
    document.removeEventListener('visibilitychange', onVisible);
    es.close();
  };
}
