import { WORLD } from '../config/world';
import { TAU, clamp } from '../core/math';
import { makeGrain, paintBackground, paintVignette, type BgLayer, type Camera } from './background';
import { FrameMeter, QUALITY, type QualityPref } from './quality';
import { THEMES, type AmbientTheme, type ThemeId } from './themes';

interface Cloud {
  x: number;
  y: number;
  s: number;
  speed: number;
}

interface Flake {
  x: number;
  y: number;
  r: number;
  vy: number;
  ph: number;
}

/** Punto che la camera deve inquadrare (coordinate mondo); zoom 1 = inquadratura normale. */
export interface CamFocus {
  x: number;
  y: number;
  zoom?: number;
}

/** centro della regione sempre visibile: perno di zoom e parallasse */
const PIVOT = { x: (WORLD.VIEW.x0 + WORLD.VIEW.x1) / 2, y: (WORLD.VIEW.y0 + WORLD.VIEW.y1) / 2 };
const PAN_X = 95;
const PAN_UP = 90;
const PAN_DOWN = 25;

/**
 * Canvas 2D principale. Inquadratura base "contain" sulla regione WORLD.VIEW:
 * lo spazio extra (schermi alti o larghi) diventa cielo/paesaggio, mai bande nere.
 * Sopra c'è una camera leggera (pan + zoom) che segue i proiettili; gli strati dello sfondo
 * si muovono di meno quanto più sono lontani (parallasse).
 * scale/ox/oy = inquadratura base; per convertire usare worldToScreen/screenToWorld (includono la camera).
 */
export class Renderer implements Camera {
  readonly g: CanvasRenderingContext2D;
  vw = 0;
  vh = 0;
  dpr = 1;
  scale = 1;
  ox = 0;
  oy = 0;
  theme: AmbientTheme = THEMES.dusk;
  readonly meter = new FrameMeter(() => this.setLowQuality(true));
  qualityPref: QualityPref = 'auto';
  /** camera: pan in unità mondo e zoom */
  private readonly cam = { x: 0, y: 0, z: 1 };
  /** trasformazione mondo effettiva (camera inclusa), in px CSS */
  private ws = 1;
  private wx = 0;
  private wy = 0;
  private shakeAmp = 0;
  private sx = 0;
  private sy = 0;
  private flashAlpha = 0;
  private flashColor = '255,255,255';
  private layers: BgLayer[] = [];
  private readonly vignette = document.createElement('canvas');
  private readonly grain: CanvasPattern;
  private readonly clouds: Cloud[] = [];
  private readonly flakes: Flake[] = [];

  constructor(readonly canvas: HTMLCanvasElement) {
    this.g = canvas.getContext('2d', { alpha: false })!;
    this.grain = this.g.createPattern(makeGrain(), 'repeat')!;
    for (let i = 0; i < 6; i++) {
      this.clouds.push({ x: Math.random() * 2400 - 200, y: 120 + Math.random() * 320, s: 0.6 + Math.random() * 0.9, speed: 0.004 + Math.random() * 0.008 });
    }
    for (let i = 0; i < 90; i++) {
      this.flakes.push({ x: Math.random() * 2400 - 250, y: Math.random() * 1400 - 450, r: 1.2 + Math.random() * 2.6, vy: 0.5 + Math.random() * 0.9, ph: Math.random() * TAU });
    }
    this.resize();
    window.addEventListener('resize', () => this.resize());
  }

  resize(): void {
    this.dpr = QUALITY.low ? 1 : Math.min(window.devicePixelRatio || 1, 2);
    this.vw = window.innerWidth;
    this.vh = window.innerHeight;
    this.canvas.width = Math.round(this.vw * this.dpr);
    this.canvas.height = Math.round(this.vh * this.dpr);
    const V = WORLD.VIEW;
    const w = V.x1 - V.x0, h = V.y1 - V.y0;
    let scale = Math.min(this.vw / w, this.vh / h);
    // l'interfaccia (barra in alto, attrezzi in basso) non deve coprire il suolo né la zona di costruzione:
    // su schermi bassi (telefono con le barre del browser) la scena si rimpicciolisce quanto basta
    const { top, bottom } = this.insets;
    const zoneTop = WORLD.GROUND_Y - WORLD.ZONE_ROWS * WORLD.CELL - 24;
    if (top || bottom) scale = Math.min(scale, (this.vh - top - bottom - 8) / (WORLD.GROUND_Y - zoneTop));
    this.scale = scale;
    this.ox = (this.vw - w * scale) / 2 - V.x0 * scale;
    const extraY = this.vh - h * scale;
    let oy = extraY * 0.85 - V.y0 * scale;
    if (bottom) oy = Math.min(oy, this.vh - bottom - 6 - WORLD.GROUND_Y * scale);
    if (top) oy = Math.max(oy, top + 2 - zoneTop * scale);
    this.oy = oy;
    this.repaint();
  }

  /** Spazio occupato dall'interfaccia in alto e in basso (px CSS). Lo aggiorna Game quando cambia l'HUD. */
  private insets = { top: 0, bottom: 0 };

  setInsets(top: number, bottom: number): void {
    const t = Math.round(top), b = Math.round(bottom);
    if (t === this.insets.top && b === this.insets.bottom) return;
    this.insets = { top: t, bottom: b };
    this.resize();
  }

  private repaint(): void {
    this.layers = paintBackground(this, this.theme, QUALITY.low ? 1 : Math.min(this.dpr, 1.5), QUALITY.low);
    paintVignette(this.vignette, this);
    this.applyCamera();
  }

  setTheme(id: ThemeId): void {
    if (this.theme.id === id) return;
    this.theme = THEMES[id];
    this.repaint();
  }

  setQualityPref(p: QualityPref): void {
    this.qualityPref = p;
    this.setLowQuality(p === 'low');
  }

  /** Qualità bassa: 1×, sfondo in un solo strato, camera ferma, metà particelle, niente ombre. */
  setLowQuality(low: boolean): void {
    if (QUALITY.low === low) return;
    QUALITY.low = low;
    QUALITY.particles = low ? 0.5 : 1;
    QUALITY.shadows = !low;
    if (low) Object.assign(this.cam, { x: 0, y: 0, z: 1 });
    this.resize();
  }

  shake(amount: number): void {
    this.shakeAmp = Math.max(this.shakeAmp, amount);
  }

  flash(alpha: number, rgb = '255,255,255'): void {
    this.flashAlpha = Math.max(this.flashAlpha, alpha);
    this.flashColor = rgb;
  }

  screenToWorld(sx: number, sy: number): { x: number; y: number } {
    return { x: (sx - this.wx) / this.ws, y: (sy - this.wy) / this.ws };
  }

  /** Punto mondo -> pixel CSS sullo schermo (camera inclusa). Usato anche dai test headless. */
  worldToScreen(x: number, y: number): { x: number; y: number } {
    return { x: x * this.ws + this.wx, y: y * this.ws + this.wy };
  }

  /**
   * Aggiorna la camera verso il punto da seguire (null = inquadratura normale).
   * Movimento morbido e limitato: la scena resta sempre leggibile.
   */
  follow(focus: CamFocus | null, dt: number): void {
    let tx = 0, ty = 0, tz = 1;
    if (focus && !QUALITY.low) {
      tx = clamp((focus.x - PIVOT.x) * 0.22, -PAN_X, PAN_X);
      ty = clamp((focus.y - PIVOT.y) * 0.25, -PAN_UP, PAN_DOWN);
      tz = focus.zoom ?? 1.05;
    }
    const k = 1 - Math.exp(-dt / (focus ? 320 : 520));
    this.cam.x += (tx - this.cam.x) * k;
    this.cam.y += (ty - this.cam.y) * k;
    this.cam.z += (tz - this.cam.z) * k;
    this.applyCamera();
  }

  private applyCamera(): void {
    const t = this.layerXf(1);
    this.ws = t.k;
    this.wx = t.tx;
    this.wy = t.ty;
  }

  /** Trasformazione mondo -> schermo (px CSS) per uno strato a profondità f. */
  private layerXf(f: number): { k: number; tx: number; ty: number; z: number; px: number; py: number; s0x: number; s0y: number } {
    const z = 1 + (this.cam.z - 1) * f;
    const px = this.cam.x * this.scale * f;
    const py = this.cam.y * this.scale * f;
    const s0x = PIVOT.x * this.scale + this.ox;
    const s0y = PIVOT.y * this.scale + this.oy;
    return { k: this.scale * z, tx: (this.ox - s0x - px) * z + s0x, ty: (this.oy - s0y - py) * z + s0y, z, px, py, s0x, s0y };
  }

  private setLayerTransform(f: number): void {
    const t = this.layerXf(f);
    const d = this.dpr;
    this.g.setTransform(d * t.k, 0, 0, d * t.k, d * (t.tx + this.sx), d * (t.ty + this.sy));
  }

  beginFrame(t: number, dt: number): void {
    const g = this.g;
    if (this.shakeAmp > 0.2) {
      this.sx = (Math.random() * 2 - 1) * this.shakeAmp;
      this.sy = (Math.random() * 2 - 1) * this.shakeAmp;
      this.shakeAmp *= Math.pow(0.86, dt / 16.67);
    } else {
      this.sx = this.sy = this.shakeAmp = 0;
    }
    g.setTransform(1, 0, 0, 1, 0, 0);
    g.fillStyle = this.theme.sky[0];
    g.fillRect(0, 0, this.canvas.width, this.canvas.height);
    const d = this.dpr;
    for (const L of this.layers) {
      const c = this.layerXf(L.f);
      const x = (L.x - c.s0x - c.px) * c.z + c.s0x + this.sx;
      const y = (L.y - c.s0y - c.py) * c.z + c.s0y + this.sy;
      g.drawImage(L.canvas, x * d, y * d, L.w * c.z * d, L.h * c.z * d);
    }
    this.setLayerTransform(0.3);
    this.drawClouds(dt);
    if (this.theme.snow) {
      this.setLayerTransform(0.85);
      this.drawSnow(t, dt);
    }
    this.worldTransform();
  }

  worldTransform(): void {
    this.setLayerTransform(1);
  }

  endFrame(t: number, dt: number): void {
    const g = this.g;
    g.setTransform(1, 0, 0, 1, 0, 0);
    if (this.flashAlpha > 0.01) {
      g.fillStyle = `rgba(${this.flashColor},${this.flashAlpha})`;
      g.fillRect(0, 0, this.canvas.width, this.canvas.height);
      this.flashAlpha *= Math.pow(0.85, dt / 16.67);
    }
    if (!QUALITY.low) {
      g.save();
      const j = Math.floor(t * 12) % 4;
      g.translate(j * 31, j * 17);
      g.globalAlpha = 0.05;
      g.globalCompositeOperation = 'overlay';
      g.fillStyle = this.grain;
      g.fillRect(-128, -128, this.canvas.width + 256, this.canvas.height + 256);
      g.restore();
    }
    g.drawImage(this.vignette, 0, 0);
  }

  private drawClouds(dt: number): void {
    const g = this.g;
    g.fillStyle = this.theme.cloud;
    for (const c of this.clouds) {
      c.x += c.speed * dt;
      if (c.x > 2300) c.x = -400;
      for (let i = 0; i < 5; i++) {
        g.beginPath();
        g.ellipse(c.x + i * 38 * c.s, c.y + Math.sin(i * 1.7) * 10 * c.s, 60 * c.s, 22 * c.s, 0, 0, TAU);
        g.fill();
      }
    }
  }

  private drawSnow(t: number, dt: number): void {
    const g = this.g;
    const top = -this.oy / this.scale - 60;
    const n = QUALITY.low ? 40 : this.flakes.length;
    g.fillStyle = 'rgba(255,255,255,0.8)';
    for (let i = 0; i < n; i++) {
      const f = this.flakes[i];
      f.y += f.vy * dt * 0.06;
      f.x += Math.sin(t * 1.3 + f.ph) * 0.02 * dt;
      if (f.y > WORLD.GROUND_Y + 10) {
        f.y = top;
        f.x = Math.random() * 2400 - 250;
      }
      g.beginPath();
      g.arc(f.x, f.y, f.r, 0, TAU);
      g.fill();
    }
  }
}
