import Matter from 'matter-js';
import { MATERIALS } from '../config/materials';
import { TUNING, WEAPON_ORDER, type WeaponId } from '../config/weapons';
import { WORLD } from '../config/world';
import { clamp, gauss, lerp, mulberry32 } from '../core/math';
import { makeShot, type Shot } from './siege';
import type { Entity, Vec, World } from './World';

const { Query } = Matter;

export interface BotOpts {
  /** seme del PRNG: stesse scelte a parità di seme e di fortezza */
  seed: number;
  /** 0 = principiante (mira larga, lento), 1 = esperto */
  skill: number;
}

/**
 * Attaccante automatico: imita un giocatore medio. Vede la fortezza e i riflessi (Mimika e le esche
 * luccicano uguali), quindi tira a un "sospetto" finché l'Eco o un'esca scoppiata non lo correggono.
 * Sceglie l'arma guardando la struttura attorno al bersaglio e mira con un errore che dipende da skill.
 * Usato dal banco di prova del bilanciamento e dalla modalità Sopravvivenza.
 */
export class Bot {
  readonly ammo: Record<WeaponId, number>;
  shots = 0;
  /** ultima arma usata (per attribuire i crolli nel banco di prova) */
  lastWeapon: WeaponId | null = null;
  private readonly rng: () => number;
  private wait: number;
  private knowsCore = false;
  private suspect: Entity | null = null;
  private combo = false;

  constructor(arsenal: Record<WeaponId, number>, private readonly opts: BotOpts) {
    this.ammo = { ...arsenal };
    this.rng = mulberry32(opts.seed);
    // prima di tirare si guarda la fortezza (e si aspetta l'assestamento)
    this.wait = Math.round((1.6 + this.rng() * 1.4) * 60);
  }

  ammoLeft(): number {
    return WEAPON_ORDER.reduce((s, w) => s + this.ammo[w], 0);
  }

  /** Da chiamare a ogni passo (World.onBeforeStep): ritorna il tiro da fare adesso, se c'è. */
  next(world: World, step: number): Shot | null {
    if (this.wait > 0) {
      this.wait--;
      return null;
    }
    if (world.coreHit || world.jamMs > 0 || this.ammoLeft() === 0 || world.projectiles.length > 0) return null;
    const target = this.pickTarget(world);
    if (!target) return null;
    const w = this.chooseWeapon(world, target.body.position);
    if (!w) return null;
    const shot = this.aim(world, w, target.body.position, step);
    this.ammo[w]--;
    this.shots++;
    this.lastWeapon = w;
    if (w === 'sonar') this.knowsCore = true;
    this.combo = w === 'flood' && this.ammo.lightning > 0;
    // tempo di reazione: guardare l'esito, scegliere, tendere la fionda
    this.wait = Math.round(lerp(2.6, 1.3, this.opts.skill) * (0.7 + this.rng() * 0.6) * 60);
    return shot;
  }

  // ------------------------------------------------------------------ percezione

  private pickTarget(world: World): Entity | null {
    const candidates = [world.core, ...world.decoys].filter((e) => !e.dead);
    if (candidates.length === 1 || this.knowsCore) return world.core;
    if (!this.suspect || this.suspect.dead) this.suspect = candidates[Math.floor(this.rng() * candidates.length)];
    return this.suspect;
  }

  /** Il primo corpo che un fulmine incontrerebbe sulla verticale x. */
  private topAt(world: World, x: number): Entity | null {
    const bodies = [...world.entities.values()].filter((e) => e.kind !== 'projectile').map((e) => e.body);
    for (let y = -100; y < WORLD.GROUND_Y; y += 10) {
      const found = Query.point(bodies, { x, y });
      if (found.length) return world.entities.get(found[0].id) ?? null;
    }
    return null;
  }

  private near(world: World, p: Vec, r: number, test: (e: Entity) => boolean): Entity[] {
    return [...world.entities.values()].filter((e) => e.kind === 'block' && test(e) && Math.hypot(e.body.position.x - p.x, e.body.position.y - p.y) < r);
  }

  private chooseWeapon(world: World, t: Vec): WeaponId | null {
    if (this.combo && this.ammo.lightning > 0) return 'lightning';
    const top = this.topAt(world, t.x);
    const metalNear = this.near(world, t, 110, (e) => e.mat === 'metal').length > 0;
    const edible = this.near(world, t, 130, (e) => !!e.mat && MATERIALS[e.mat].termite > 0).length;
    const tall = [...world.entities.values()].some((e) => e.kind === 'block' && e.body.position.y < WORLD.GROUND_Y - 6 * WORLD.CELL);
    const decoys = world.decoys.length;
    const weights: Record<WeaponId, number> = {
      boulder: 3,
      bomb: 3,
      drill: 2,
      lightning: !top ? 0.5 : top.kind !== 'block' ? 6 : top.mat === 'metal' ? 3.5 : top.mat === 'silk' ? 0.25 : 0.8,
      wind: tall ? 1.2 : 0.4,
      sonar: this.knowsCore || decoys === 0 ? 0.15 : 4,
      termite: edible ? 1 + edible * 0.4 : 0.25,
      flood: metalNear && this.ammo.lightning > 0 ? 2.5 : 0.6,
    };
    let sum = 0;
    for (const w of WEAPON_ORDER) if (this.ammo[w] > 0) sum += weights[w];
    if (sum <= 0) return null;
    let r = this.rng() * sum;
    for (const w of WEAPON_ORDER) {
      if (this.ammo[w] <= 0) continue;
      if ((r -= weights[w]) <= 0) return w;
    }
    return WEAPON_ORDER.find((w) => this.ammo[w] > 0) ?? null;
  }

  // ------------------------------------------------------------------ mira

  private aim(world: World, w: WeaponId, t: Vec, step: number): Shot {
    const sigma = lerp(120, 22, clamp(this.opts.skill, 0, 1));
    let goal = { x: t.x + gauss(this.rng) * sigma, y: t.y + gauss(this.rng) * sigma * 0.6 };
    if (w === 'termite') {
      const food = this.near(world, t, 160, (e) => !!e.mat && MATERIALS[e.mat].termite > 0)[0];
      if (food) goal = { x: food.body.position.x + gauss(this.rng) * sigma * 0.5, y: food.body.position.y + gauss(this.rng) * sigma * 0.3 };
    }
    if (w === 'lightning') return makeShot(step, w, clamp(t.x + gauss(this.rng) * sigma * 0.5, 0, WORLD.W));
    if (w === 'drill') {
      const dx = goal.x - WORLD.LAUNCH_X, dy = goal.y - WORLD.LAUNCH_Y, len = Math.hypot(dx, dy) || 1;
      return makeShot(step, w, (dx / len) * TUNING.drillSpeed, (dy / len) * TUNING.drillSpeed);
    }
    if (w === 'boulder' || w === 'bomb' || w === 'termite') {
      const v = solveSling(goal, world.gravityPerStep, this.rng() < 0.7);
      return makeShot(step, w, v.vx, v.vy);
    }
    return makeShot(step, w);
  }
}

/**
 * Velocità di lancio della fionda per passare vicino al punto (stesso modello dell'anteprima di traiettoria).
 * direct = preferisci il tiro teso; altrimenti il pallonetto.
 */
export function solveSling(goal: Vec, g: number, direct: boolean): { vx: number; vy: number } {
  let best = { vx: 18, vy: -8, miss: Infinity, t: 0 };
  const cands: { vx: number; vy: number; miss: number; t: number }[] = [];
  for (let speed = 8; speed <= 26; speed += 1) {
    for (let a = -1.45; a <= 0.35; a += 0.02) {
      const vx0 = Math.cos(a) * speed, vy0 = Math.sin(a) * speed;
      let x = WORLD.LAUNCH_X, y = WORLD.LAUNCH_Y, vy = vy0, miss = Infinity, at = 0;
      for (let i = 1; i < 260; i++) {
        vy += g;
        x += vx0;
        y += vy;
        const d = Math.hypot(x - goal.x, y - goal.y);
        if (d < miss) (miss = d), (at = i);
        if (y > WORLD.GROUND_Y + 40 || x > goal.x + 80) break;
      }
      if (miss < best.miss) best = { vx: vx0, vy: vy0, miss, t: at };
      if (miss < 10) cands.push({ vx: vx0, vy: vy0, miss, t: at });
    }
  }
  if (!cands.length) return best;
  cands.sort((p, q) => p.t - q.t);
  return direct ? cands[0] : cands[cands.length - 1];
}
