import type { WeaponId } from '../config/weapons';
import { WORLD } from '../config/world';
import { TAU, clamp } from '../core/math';
import { PALETTE } from './palette';
import { QUALITY } from './quality';

export type MimikaStyle = 'live' | 'decoy' | 'ghost';

export interface MimikaOpts {
  style: MimikaStyle;
  /** opacità (per lo scintillio mimetico) */
  alpha?: number;
  /** punto verso cui guarda */
  look?: { x: number; y: number };
  angle?: number;
  scale?: number;
  /** 0..1 paura (un colpo è arrivato vicino): trema, pupille piccole, goccia di sudore */
  scared?: number;
  /** 0..1 esultanza (la fortezza ha resistito): saltella, occhio felice, bocca aperta */
  cheer?: number;
  /** presa: occhio a spirale */
  dizzy?: boolean;
}

/**
 * Mimika: piccolo camaleonte-spirito iridescente. In attacco è mimetizzato (style 'ghost'):
 * se ne intravede solo il riflesso. Le esche ('decoy') sono pupazzi di juta cuciti.
 */
export function drawMimika(g: CanvasRenderingContext2D, x: number, y: number, t: number, o: MimikaOpts): void {
  const R = 17 * (o.scale ?? 1);
  const alpha = o.alpha ?? 1;
  if (alpha <= 0.01) return;
  const scared = o.scared ?? 0;
  const cheer = o.cheer ?? 0;
  g.save();
  g.translate(x + Math.sin(t * 70) * 1.6 * scared, y - Math.abs(Math.sin(t * 8)) * R * 0.55 * cheer);
  g.rotate((o.angle ?? 0) + Math.sin(t * 8) * 0.12 * cheer);
  g.globalAlpha = alpha;

  const bob = Math.sin(t * 2.4 + x) * 0.06;
  const blob = () => {
    g.beginPath();
    for (let i = 0; i <= 30; i++) {
      const a = (i / 30) * TAU;
      const wob = 1 + 0.05 * Math.sin(a * 3 + t * 3.1) + 0.03 * Math.sin(a * 5 - t * 2.3);
      const px = Math.cos(a) * R * wob * (1 + bob * 0.5);
      const py = Math.sin(a) * R * wob * (1 - bob) * (a > 0 && a < Math.PI ? 0.88 : 1);
      if (i) g.lineTo(px, py); else g.moveTo(px, py);
    }
    g.closePath();
  };

  if (o.style === 'ghost') {
    blob();
    const hue = (t * 90) % 360;
    g.fillStyle = `hsla(${hue},90%,80%,0.10)`;
    g.fill();
    g.strokeStyle = `hsla(${hue},100%,88%,0.75)`;
    g.lineWidth = 1.6;
    g.setLineDash([4, 5]);
    g.lineDashOffset = -t * 30;
    g.stroke();
    g.setLineDash([]);
    g.restore();
    return;
  }

  // coda arrotolata (dietro)
  g.lineCap = 'round';
  g.strokeStyle = PALETTE.ink;
  g.lineWidth = 7;
  tail(g, R);
  g.strokeStyle = o.style === 'decoy' ? '#b08d58' : `hsl(${(t * 30 + 140) % 360},70%,55%)`;
  g.lineWidth = 4;
  tail(g, R);

  // cresta a foglie
  for (let k = -1; k <= 1; k++) {
    g.save();
    g.translate(k * R * 0.35, -R * 0.82);
    g.rotate(k * (0.45 + cheer * 0.35 - scared * 0.2) + Math.sin(t * (3 + cheer * 9) + k) * 0.08);
    g.beginPath();
    g.ellipse(0, -R * 0.22, R * 0.14, R * 0.3, 0, 0, TAU);
    g.fillStyle = o.style === 'decoy' ? '#9c7a48' : '#6de0a8';
    g.fill();
    g.strokeStyle = PALETTE.ink;
    g.lineWidth = 1.5;
    g.stroke();
    g.restore();
  }

  blob();
  if (o.style === 'decoy') {
    g.fillStyle = '#c9a66b';
  } else {
    const h = (t * 30) % 360;
    const gr = g.createLinearGradient(-R, -R, R, R);
    gr.addColorStop(0, `hsl(${h},85%,68%)`);
    gr.addColorStop(0.5, `hsl(${(h + 60) % 360},80%,62%)`);
    gr.addColorStop(1, `hsl(${(h + 150) % 360},75%,52%)`);
    g.fillStyle = gr;
  }
  g.fill();
  g.save();
  g.clip();
  // pancia chiara
  g.fillStyle = 'rgba(255,255,255,0.28)';
  g.beginPath();
  g.ellipse(-R * 0.1, R * 0.55, R * 0.75, R * 0.45, 0, 0, TAU);
  g.fill();
  if (o.style === 'decoy') {
    g.strokeStyle = 'rgba(90,60,30,0.6)';
    g.setLineDash([3, 3]);
    g.lineWidth = 1.2;
    g.beginPath();
    g.moveTo(-R, 0);
    g.quadraticCurveTo(0, R * 0.3, R, 0);
    g.stroke();
    g.setLineDash([]);
  }
  g.restore();
  blob();
  g.strokeStyle = PALETTE.ink;
  g.lineWidth = 2.2;
  g.stroke();

  // occhio
  const ex = R * 0.22, ey = -R * 0.18, er = R * 0.42;
  if (o.style === 'decoy') {
    g.strokeStyle = PALETTE.ink;
    g.lineWidth = 2.2;
    g.beginPath();
    g.moveTo(ex - 5, ey - 5); g.lineTo(ex + 5, ey + 5);
    g.moveTo(ex + 5, ey - 5); g.lineTo(ex - 5, ey + 5);
    g.stroke();
  } else if (o.dizzy) {
    g.fillStyle = '#fffaf2';
    g.beginPath();
    g.arc(ex, ey, er, 0, TAU);
    g.fill();
    g.strokeStyle = PALETTE.ink;
    g.lineWidth = 2;
    g.stroke();
    g.beginPath();
    for (let i = 0; i <= 24; i++) {
      const a = i * 0.55 + t * 8;
      const rr = (i / 24) * er * 0.8;
      g.lineTo(ex + Math.cos(a) * rr, ey + Math.sin(a) * rr);
    }
    g.lineWidth = 1.6;
    g.stroke();
  } else if (cheer > 0.3) {
    // occhio felice "^"
    g.strokeStyle = PALETTE.ink;
    g.lineWidth = 2.6;
    g.beginPath();
    g.arc(ex, ey + er * 0.35, er * 0.62, Math.PI * 1.15, Math.PI * 1.85);
    g.stroke();
  } else {
    const blink = (t % 4.3) < 0.12 && !scared;
    g.fillStyle = '#fffaf2';
    g.beginPath();
    g.arc(ex, ey, er, 0, TAU);
    g.fill();
    g.strokeStyle = PALETTE.ink;
    g.lineWidth = 2;
    g.stroke();
    if (blink) {
      g.beginPath();
      g.moveTo(ex - er, ey);
      g.lineTo(ex + er, ey);
      g.stroke();
    } else {
      let lx = 0, ly = 0;
      if (o.look) {
        const dx = o.look.x - x, dy = o.look.y - y, d = Math.hypot(dx, dy) || 1;
        lx = (dx / d) * er * 0.4;
        ly = (dy / d) * er * 0.4;
      }
      const pr = er * (0.5 - scared * 0.22);
      g.fillStyle = PALETTE.ink;
      g.beginPath();
      g.arc(ex + lx, ey + ly, pr, 0, TAU);
      g.fill();
      g.fillStyle = '#fff';
      g.beginPath();
      g.arc(ex + lx - pr * 0.35, ey + ly - pr * 0.4, pr * 0.35, 0, TAU);
      g.fill();
    }
  }
  // guance
  g.fillStyle = o.style === 'decoy' ? 'rgba(150,90,60,0.35)' : `rgba(255,120,160,${0.45 + cheer * 0.35})`;
  g.beginPath();
  g.ellipse(R * 0.62, R * 0.2, R * 0.16, R * 0.1, 0, 0, TAU);
  g.fill();
  if (o.style === 'live') expression(g, R, t, scared, cheer, !!o.dizzy);
  g.restore();
}

/** Bocca e dettagli d'espressione: paura (bocca a "o" tremante, sudore), gioia (bocca aperta), presa. */
function expression(g: CanvasRenderingContext2D, R: number, t: number, scared: number, cheer: number, dizzy: boolean): void {
  const mx = R * 0.5, my = R * 0.36;
  g.strokeStyle = PALETTE.ink;
  g.fillStyle = '#5a1f3a';
  g.lineWidth = 1.8;
  if (cheer > 0.3) {
    g.beginPath();
    g.moveTo(mx - R * 0.22, my - R * 0.04);
    g.quadraticCurveTo(mx, my + R * 0.34, mx + R * 0.2, my - R * 0.06);
    g.closePath();
    g.fill();
    g.stroke();
  } else if (scared > 0.25 || dizzy) {
    g.beginPath();
    g.ellipse(mx, my + Math.sin(t * 50) * 0.6, R * 0.09, R * 0.12 * (0.6 + scared * 0.4), 0, 0, TAU);
    g.fill();
    g.stroke();
  }
  if (scared > 0.35) {
    // goccia di sudore
    const dy = ((t * 1.4) % 1) * R * 0.25;
    g.globalAlpha *= Math.min(1, scared * 1.5);
    g.fillStyle = '#bfefff';
    g.beginPath();
    g.moveTo(-R * 0.2, -R * 0.62 + dy);
    g.quadraticCurveTo(-R * 0.34, -R * 0.36 + dy, -R * 0.2, -R * 0.32 + dy);
    g.quadraticCurveTo(-R * 0.06, -R * 0.36 + dy, -R * 0.2, -R * 0.62 + dy);
    g.fill();
    g.lineWidth = 1.2;
    g.stroke();
  }
}

function tail(g: CanvasRenderingContext2D, R: number): void {
  g.beginPath();
  g.moveTo(-R * 0.7, R * 0.35);
  g.quadraticCurveTo(-R * 1.5, R * 0.6, -R * 1.45, R * 0.05);
  g.arc(-R * 1.15, R * 0.05, R * 0.3, Math.PI, Math.PI * 2.6);
  g.stroke();
}

/** Fionda-totem dell'attaccante. pouch = posizione della sacca (tesa durante la mira). */
export function drawLauncher(
  g: CanvasRenderingContext2D, t: number, pouch: { x: number; y: number } | null, loaded: WeaponId | null, recoil = 0,
): void {
  const X = WORLD.LAUNCH_X, G = WORLD.GROUND_Y;
  const tipL = { x: X - 26, y: WORLD.LAUNCH_Y - 8 };
  const tipR = { x: X + 26, y: WORLD.LAUNCH_Y - 8 };
  // appena rilasciato l'elastico vibra avanti e indietro
  const p = pouch ?? { x: X + Math.sin(t * 46) * 14 * recoil * recoil, y: WORLD.LAUNCH_Y - Math.sin(t * 46) * 4 * recoil };

  // base di pietra
  g.fillStyle = '#3d3256';
  g.strokeStyle = PALETTE.ink;
  g.lineWidth = 3;
  g.beginPath();
  g.ellipse(X, G - 4, 52, 16, 0, Math.PI, 0);
  g.fill();
  g.stroke();

  // elastico posteriore
  g.strokeStyle = '#7a2f3b';
  g.lineWidth = 5;
  g.beginPath();
  g.moveTo(tipR.x, tipR.y);
  g.lineTo(p.x, p.y);
  g.stroke();

  // tronco a Y
  g.lineCap = 'round';
  g.lineJoin = 'round';
  for (const [color, w] of [[PALETTE.ink, 17], ['#8a5a34', 11]] as const) {
    g.strokeStyle = color;
    g.lineWidth = w;
    g.beginPath();
    g.moveTo(X, G - 8);
    g.lineTo(X, G - 85);
    g.lineTo(tipL.x, tipL.y);
    g.moveTo(X, G - 85);
    g.lineTo(tipR.x, tipR.y);
    g.stroke();
  }
  // nastri decorativi
  g.strokeStyle = PALETTE.attacker;
  g.lineWidth = 5;
  g.beginPath();
  g.moveTo(X - 6, G - 50); g.lineTo(X + 6, G - 58);
  g.moveTo(X - 6, G - 38); g.lineTo(X + 6, G - 46);
  g.stroke();
  const flutter = Math.sin(t * 5) * 6;
  g.fillStyle = PALETTE.attacker;
  g.beginPath();
  g.moveTo(tipL.x, tipL.y + 6);
  g.quadraticCurveTo(tipL.x - 18, tipL.y + 16 + flutter, tipL.x - 30, tipL.y + 8 + flutter);
  g.lineTo(tipL.x - 4, tipL.y + 12);
  g.fill();

  if (loaded) drawProjectile(g, loaded, p.x, p.y, Math.atan2(WORLD.LAUNCH_Y - p.y, X - p.x), t);

  // elastico anteriore + sacca
  g.strokeStyle = '#b3434f';
  g.lineWidth = 5;
  g.beginPath();
  g.moveTo(tipL.x, tipL.y);
  g.lineTo(p.x, p.y);
  g.stroke();
  g.fillStyle = '#5a2430';
  g.beginPath();
  g.ellipse(p.x, p.y, 9, 6, 0, 0, TAU);
  g.fill();
}

export interface HunterPose {
  /** sacca della fionda mentre si mira (coordinate mondo): il braccio la tiene e il corpo si inclina */
  pouch?: { x: number; y: number } | null;
  /** 0..1 subito dopo il tiro: braccio teso in avanti, mantello che sventola */
  recoil?: number;
  /** braccio alzato verso il cielo (mira del fulmine) */
  cast?: boolean;
  /** 0..1 esultanza (Mimika presa) */
  cheer?: number;
  /** 0..1 sconfitta: testa bassa, occhi spenti */
  slump?: number;
  /** 0..1 abbagliato dal fulmine riflesso dalla seta: stelline attorno alla testa */
  daze?: number;
  /** posizione dei piedi e scala (default: accanto alla fionda) */
  at?: { x: number; y: number };
  scale?: number;
}

const HUNTER_X = WORLD.LAUNCH_X - 95;

/** Il Cacciatore: figura incappucciata con maschera luminosa, accanto alla fionda. */
export function drawHunter(g: CanvasRenderingContext2D, t: number, o: HunterPose = {}): void {
  const at = o.at ?? { x: HUNTER_X, y: WORLD.GROUND_Y };
  const k = o.scale ?? 1;
  const recoil = o.recoil ?? 0;
  const cheer = o.cheer ?? 0;
  const slump = o.slump ?? 0;
  const aiming = !!o.pouch;
  const pull = o.pouch ? clamp(Math.hypot(o.pouch.x - WORLD.LAUNCH_X, o.pouch.y - WORLD.LAUNCH_Y) / 86, 0, 1) : 0;
  const breathe = Math.sin(t * 2) * 2;
  const hop = Math.abs(Math.sin(t * 7)) * 10 * cheer;
  // inclinazione: indietro mentre tende, in avanti al rilascio, giù se sconfitto
  const lean = -0.14 * pull + 0.16 * recoil * recoil + 0.2 * slump;
  g.save();
  g.translate(at.x, at.y - hop * k);
  g.scale(k, k);
  g.rotate(lean);
  // mantello
  const sway = Math.sin(t * 9) * 5 * recoil;
  g.fillStyle = '#4a1f3d';
  g.strokeStyle = PALETTE.ink;
  g.lineWidth = 3;
  g.beginPath();
  g.moveTo(-30 - sway, 0);
  g.quadraticCurveTo(-26 - sway, -60 - breathe, 0, -88 - breathe);
  g.quadraticCurveTo(26, -60 - breathe, 32, 0);
  g.closePath();
  g.fill();
  g.stroke();
  g.fillStyle = PALETTE.attacker;
  g.fillRect(-26, -20, 54, 6);
  // braccio dietro (alzato quando esulta)
  if (cheer > 0.2) arm(g, { x: -12, y: -66 - breathe }, { x: -30, y: -128 - Math.sin(t * 7) * 6 });
  // cappuccio
  const nod = slump * 10;
  g.fillStyle = '#5e2a4e';
  g.beginPath();
  g.ellipse(2 + nod * 0.4, -88 - breathe + nod, 22, 24, 0, 0, TAU);
  g.fill();
  g.stroke();
  // maschera
  g.fillStyle = '#f8ecd9';
  g.beginPath();
  g.ellipse(6 + nod * 0.5, -86 - breathe + nod, 14, 16, 0.1 + slump * 0.3, 0, TAU);
  g.fill();
  g.stroke();
  const glow = slump > 0.5 ? 0.25 : aiming || o.cast || cheer > 0 ? 1 : 0.6 + Math.sin(t * 3) * 0.2;
  g.fillStyle = `rgba(255,122,107,${glow})`;
  if (!QUALITY.low) {
    g.shadowColor = PALETTE.attacker;
    g.shadowBlur = aiming || o.cast ? 14 : 6;
  }
  const ey = -91 - breathe + nod;
  if (cheer > 0.3) {
    // occhi sorridenti
    g.strokeStyle = `rgba(255,122,107,1)`;
    g.lineWidth = 2.4;
    g.beginPath();
    g.arc(4.5, ey + 3, 3, Math.PI * 1.1, Math.PI * 1.9);
    g.moveTo(16.5, ey + 3);
    g.arc(13.5, ey + 3, 3, Math.PI * 1.1, Math.PI * 1.9);
    g.stroke();
  } else {
    // occhi stretti quando tende la fionda
    const eh = 3 - pull * 1.5;
    g.fillRect(2 + nod * 0.5, ey, 5, eh);
    g.fillRect(11 + nod * 0.5, ey, 5, eh);
  }
  g.shadowBlur = 0;
  g.strokeStyle = PALETTE.attacker;
  g.lineWidth = 2;
  g.beginPath();
  g.moveTo(9 + nod * 0.5, -80 - breathe + nod);
  g.lineTo(9 + nod * 0.5, -74 - breathe + nod);
  g.stroke();
  // braccio davanti
  const shoulder = { x: 12, y: -64 - breathe };
  let hand: { x: number; y: number };
  if (o.pouch) {
    // mano sulla sacca: coordinate mondo -> locali (inverso di translate + rotate)
    const dx = o.pouch.x - at.x, dy = o.pouch.y - at.y;
    const c = Math.cos(-lean), sn = Math.sin(-lean);
    hand = { x: (dx * c - dy * sn) / k, y: (dx * sn + dy * c) / k };
    const reach = Math.hypot(hand.x - shoulder.x, hand.y - shoulder.y);
    if (reach > 70) hand = { x: shoulder.x + ((hand.x - shoulder.x) / reach) * 70, y: shoulder.y + ((hand.y - shoulder.y) / reach) * 70 };
  } else if (o.cast) hand = { x: 30, y: -134 + Math.sin(t * 6) * 3 };
  else if (cheer > 0.2) hand = { x: 34, y: -130 - Math.sin(t * 7 + 1) * 6 };
  else if (recoil > 0.05) hand = { x: 30 + 40 * recoil, y: -70 - 14 * recoil };
  else hand = { x: 22, y: -30 + Math.sin(t * 2 + 1) * 2 + slump * 8 };
  arm(g, shoulder, hand);
  const daze = o.daze ?? 0;
  if (daze > 0.02) {
    // stelline color seta che girano attorno al cappuccio
    for (let i = 0; i < 4; i++) {
      const a = t * 5 + (i / 4) * TAU;
      const sx = 4 + Math.cos(a) * 28, sy = -112 - breathe + Math.sin(a) * 9;
      g.globalAlpha = daze * (0.6 + 0.4 * Math.sin(a));
      g.fillStyle = i % 2 ? PALETTE.gold : '#e4dbff';
      star(g, sx, sy, 5.5);
    }
    g.globalAlpha = 1;
  }
  g.restore();
}

function star(g: CanvasRenderingContext2D, x: number, y: number, r: number): void {
  g.beginPath();
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * TAU - Math.PI / 2;
    const k = i % 2 ? r * 0.42 : r;
    if (i) g.lineTo(x + Math.cos(a) * k, y + Math.sin(a) * k); else g.moveTo(x + Math.cos(a) * k, y + Math.sin(a) * k);
  }
  g.closePath();
  g.fill();
}

function arm(g: CanvasRenderingContext2D, from: { x: number; y: number }, to: { x: number; y: number }): void {
  g.lineCap = 'round';
  // gomito leggermente piegato verso il basso
  const mx = (from.x + to.x) / 2 - (to.y - from.y) * 0.15;
  const my = (from.y + to.y) / 2 + Math.abs(to.x - from.x) * 0.15;
  for (const [color, w] of [[PALETTE.ink, 11], ['#5e2a4e', 6.5]] as const) {
    g.strokeStyle = color;
    g.lineWidth = w;
    g.beginPath();
    g.moveTo(from.x, from.y);
    g.quadraticCurveTo(mx, my, to.x, to.y);
    g.stroke();
  }
  g.fillStyle = '#2a1430';
  g.strokeStyle = PALETTE.ink;
  g.lineWidth = 2;
  g.beginPath();
  g.arc(to.x, to.y, 5.5, 0, TAU);
  g.fill();
  g.stroke();
}

export function drawProjectile(g: CanvasRenderingContext2D, w: WeaponId, x: number, y: number, angle: number, t: number): void {
  g.save();
  g.translate(x, y);
  g.rotate(angle);
  g.strokeStyle = PALETTE.ink;
  g.lineWidth = 2.5;
  if (w === 'boulder') {
    const gr = g.createRadialGradient(-7, -7, 3, 0, 0, 24);
    gr.addColorStop(0, '#b9b4cf');
    gr.addColorStop(1, '#4d4866');
    g.fillStyle = gr;
    g.beginPath();
    for (let i = 0; i <= 10; i++) {
      const a = (i / 10) * TAU;
      const r = 22 * (1 + 0.06 * Math.sin(i * 2.7));
      if (i) g.lineTo(Math.cos(a) * r, Math.sin(a) * r); else g.moveTo(Math.cos(a) * r, Math.sin(a) * r);
    }
    g.closePath();
    g.fill();
    g.stroke();
    g.strokeStyle = 'rgba(30,20,50,0.5)';
    g.beginPath();
    g.moveTo(-6, -10); g.lineTo(2, -2); g.lineTo(-2, 8);
    g.stroke();
  } else if (w === 'bomb') {
    g.rotate(-angle);
    const gr = g.createRadialGradient(-6, -6, 2, 0, 0, 20);
    gr.addColorStop(0, '#5b5a7a');
    gr.addColorStop(1, '#16142a');
    g.fillStyle = gr;
    g.beginPath();
    g.arc(0, 0, 18, 0, TAU);
    g.fill();
    g.stroke();
    g.fillStyle = PALETTE.attacker;
    g.fillRect(-18, -3, 36, 6);
    g.strokeStyle = '#d6b07a';
    g.lineWidth = 3;
    g.beginPath();
    g.moveTo(6, -16);
    g.quadraticCurveTo(14, -26, 10, -30);
    g.stroke();
    const flick = 3 + Math.sin(t * 40) * 1.5;
    g.fillStyle = '#ffe28a';
    g.beginPath();
    g.arc(10, -31, flick, 0, TAU);
    g.fill();
  } else if (w === 'drill') {
    const gr = g.createLinearGradient(0, -8, 0, 8);
    gr.addColorStop(0, '#dfe8f0');
    gr.addColorStop(1, '#55657a');
    g.fillStyle = gr;
    g.beginPath();
    g.moveTo(-23, -8);
    g.lineTo(6, -8);
    g.lineTo(25, 0);
    g.lineTo(6, 8);
    g.lineTo(-23, 8);
    g.closePath();
    g.fill();
    g.stroke();
    g.strokeStyle = 'rgba(30,40,60,0.6)';
    g.lineWidth = 1.5;
    const off = (t * 60) % 8;
    for (let k = -20 + off; k < 6; k += 8) {
      g.beginPath();
      g.moveTo(k, -8);
      g.lineTo(k + 5, 8);
      g.stroke();
    }
    g.fillStyle = PALETTE.attacker;
    g.fillRect(-23, -8, 6, 16);
  } else if (w === 'termite') {
    // vaso di terracotta con tappo di foglie: le termiti sbirciano dal collo
    g.rotate(-angle + Math.sin(t * 9) * 0.25);
    const gr = g.createRadialGradient(-5, -4, 2, 0, 2, 17);
    gr.addColorStop(0, '#e39a62');
    gr.addColorStop(1, '#8a4224');
    g.fillStyle = gr;
    g.beginPath();
    g.ellipse(0, 3, 13, 12, 0, 0, TAU);
    g.fill();
    g.stroke();
    g.fillStyle = '#9c4e2c';
    g.fillRect(-6.5, -13, 13, 6);
    g.strokeRect(-6.5, -13, 13, 6);
    g.fillStyle = PALETTE.attacker;
    g.fillRect(-12, 1, 24, 4);
    g.fillStyle = PALETTE.grass;
    g.beginPath();
    g.ellipse(-3, -15, 6, 3, -0.5, 0, TAU);
    g.ellipse(4, -15, 6, 3, 0.5, 0, TAU);
    g.fill();
    g.fillStyle = '#3a2210';
    for (const [dx, dy] of [[-4, -8], [3, -9], [8, -3]]) {
      g.beginPath();
      g.arc(dx + Math.sin(t * 14 + dx) * 0.8, dy, 1.6, 0, TAU);
      g.fill();
    }
  }
  g.restore();
}

/** Piena: corpo d'acqua che avanza da sinistra con la cresta di schiuma sul fronte (front = x della cresta). */
export function drawFlood(g: CanvasRenderingContext2D, front: number, h: number, t: number): void {
  if (h < 2) return;
  const G = WORLD.GROUND_Y;
  const back = front - 560;
  g.save();
  const gr = g.createLinearGradient(0, G - h, 0, G);
  gr.addColorStop(0, 'rgba(126,214,235,0.78)');
  gr.addColorStop(1, 'rgba(46,92,168,0.88)');
  g.fillStyle = gr;
  g.strokeStyle = PALETTE.ink;
  g.lineWidth = 2.5;
  g.beginPath();
  g.moveTo(back, G);
  const surface = (x: number) => h * (0.25 + 0.75 * ((x - back) / (front - back))) + Math.sin(x * 0.045 - t * 7) * 4;
  for (let x = back; x <= front; x += 12) g.lineTo(x, G - surface(x));
  g.quadraticCurveTo(front + h * 0.5, G - h * 1.08, front + h * 0.3, G - h * 0.5);
  g.lineTo(front + h * 0.34, G);
  g.closePath();
  g.fill();
  g.stroke();
  // schiuma e spruzzi sulla cresta
  g.fillStyle = 'rgba(240,252,255,0.9)';
  for (let i = 0; i < 9; i++) {
    const x = front - i * 16 + Math.sin(t * 9 + i) * 3;
    g.beginPath();
    g.arc(x, G - surface(x) + 2, 4 + (i % 3), 0, TAU);
    g.fill();
  }
  g.strokeStyle = 'rgba(240,252,255,0.55)';
  g.lineWidth = 2;
  for (let x = back + 40; x < front - 40; x += 70) {
    const y = G - surface(x) * 0.55;
    g.beginPath();
    g.moveTo(x, y);
    g.quadraticCurveTo(x + 14, y - 5, x + 28, y);
    g.stroke();
  }
  g.restore();
}

export function drawTrajectory(g: CanvasRenderingContext2D, pts: { x: number; y: number }[], color: string): void {
  pts.forEach((p, i) => {
    const k = 1 - i / pts.length;
    g.fillStyle = color;
    g.globalAlpha = clamp(k, 0, 1) * 0.9;
    g.beginPath();
    g.arc(p.x, p.y, 2 + 4 * k, 0, TAU);
    g.fill();
  });
  g.globalAlpha = 1;
}

type Pt = { x: number; y: number };

/** Fulmine con alone; k = vita residua 0..1. */
export function drawBolt(g: CanvasRenderingContext2D, path: Pt[], branches: Pt[][], k: number): void {
  const flicker = 0.6 + Math.random() * 0.4;
  for (const [color, width] of [[`rgba(203,184,255,${0.35 * k})`, 16], [`rgba(255,255,255,${k * flicker})`, 4]] as const) {
    g.strokeStyle = color;
    g.lineWidth = width;
    g.lineJoin = 'round';
    for (const line of [path, ...branches]) {
      g.beginPath();
      line.forEach((p, i) => (i ? g.lineTo(p.x, p.y) : g.moveTo(p.x, p.y)));
      g.stroke();
    }
  }
}

/** Mirino del fulmine: colonna tratteggiata e nuvole temporalesche sopra la x scelta. */
export function drawStormMarker(g: CanvasRenderingContext2D, x: number, t: number): void {
  g.save();
  g.strokeStyle = 'rgba(203,184,255,0.8)';
  g.setLineDash([8, 10]);
  g.lineDashOffset = -t * 60;
  g.lineWidth = 3;
  g.beginPath();
  g.moveTo(x, 260);
  g.lineTo(x, WORLD.GROUND_Y);
  g.stroke();
  g.setLineDash([]);
  g.fillStyle = 'rgba(70,50,110,0.85)';
  for (let i = 0; i < 4; i++) {
    g.beginPath();
    g.ellipse(x - 45 + i * 30, 250 + Math.sin(t * 3 + i) * 4, 32, 18, 0, 0, TAU);
    g.fill();
  }
  g.restore();
}

/** Onda dell'Eco che parte dalla fionda; k = 0..1 avanzamento. */
export function drawSonarRing(g: CanvasRenderingContext2D, k: number): void {
  g.strokeStyle = `rgba(94,230,197,${(1 - k) * 0.8})`;
  g.lineWidth = 3 + (1 - k) * 6;
  g.beginPath();
  g.arc(WORLD.LAUNCH_X, WORLD.LAUNCH_Y, k * 1900, -0.9, 0.5);
  g.stroke();
}
