import { MODES, type ModeId } from '../config/modes';
import { isNative } from '../native';
import { h, icon, type UI } from './dom';
import { ICONS } from './icons';
import { actionBtn, shareRow, type Action } from './screens';

/**
 * Schermate del duello live: home, invito (host), risposta (ospite), attesa e avvisi.
 * Le funzioni che restituiscono un "handle" permettono a LiveDuel di aggiornare stato,
 * conto alla rovescia ed errori senza ridisegnare il pannello.
 */
export type NetTone = 'wait' | 'ok' | 'err';

function statusLine() {
  const text = h('span', {});
  const el = h('div', { class: 'net-status wait', role: 'status' }, h('i', {}), text);
  return {
    el,
    set(tone: NetTone, msg: string) {
      el.className = `net-status ${tone}`;
      text.textContent = msg;
    },
  };
}

const warnBox = () => isNative()
  ? h('div', { class: 'warn-box' }, h('b', {}, "Non chiudere l'app"),
    h('span', {}, ' finché il duello non parte: puoi passare a WhatsApp e tornare qui, il collegamento nasce in questa schermata.'))
  : h('div', { class: 'warn-box' }, h('b', {}, 'Non chiudere né ricaricare questa pagina'),
    h('span', {}, ' finché il duello non parte: il collegamento nasce qui.'));

const step = (n: number, title: string, ...body: (HTMLElement | null)[]) =>
  h('section', { class: 'step' }, h('h3', {}, h('em', {}, String(n)), title), ...body);

function failBox(actions: Action[]) {
  const text = h('p', {});
  const el = h('div', { class: 'fail-box hidden' }, text, h('div', { class: 'row wrap' }, ...actions.map((a) =>
    h('button', { class: `btn${a.primary ? ' primary' : ''}`, onclick: a.onClick }, a.ico ? icon(a.ico) : null, a.label))));
  return { el, show(msg: string) { text.textContent = msg; el.classList.remove('hidden'); } };
}

export interface LobbyHandle {
  el: HTMLElement;
  status(tone: NetTone, msg: string): void;
  countdown(text: string): void;
  fail(msg: string): void;
}

// ---------------------------------------------------------------- home del duello

export function liveHomeScreen(o: { mode: ModeId; onHost(): void; onJoin(text: string): void; onBack(): void }): HTMLElement {
  const ta = h('textarea', { rows: '3', placeholder: "Incolla qui il link d'invito (#o=…)" });
  return h('div', { class: 'screen center' },
    h('div', { class: 'panel lobby' },
      h('div', { class: 'role-badge' }, 'DUELLO LIVE'),
      h('h2', {}, 'Sfida in diretta'),
      h('p', {}, `Ognuno sul suo dispositivo, collegati direttamente e senza server. Chi invita sceglie la modalità (ora: ${MODES[o.mode].name}) e difende per primo; l'altro guarda… e poi assedia.`),
      h('div', { class: 'steps' },
        h('section', { class: 'step' },
          h('h3', {}, icon(ICONS.live, 'ico tiny'), 'Invita tu'),
          h('p', {}, "Crea un link d'invito e mandalo all'avversario (WhatsApp, messaggio…)."),
          h('button', { class: 'btn primary', onclick: o.onHost }, icon(ICONS.link), 'Crea invito')),
        h('section', { class: 'step' },
          h('h3', {}, icon(ICONS.key, 'ico tiny'), 'Hai un invito?'),
          ta,
          h('button', { class: 'btn', onclick: () => o.onJoin(ta.value) }, icon(ICONS.check), 'Unisciti')),
      ),
      h('p', { class: 'tip' }, 'Siate online entrambi adesso. Se la connessione diretta non riesce (alcune reti la bloccano), usate la Sfida via link.'),
      h('div', { class: 'row' }, h('button', { class: 'btn ghost', onclick: o.onBack }, icon(ICONS.back), 'Menu')),
    ),
  );
}

// ---------------------------------------------------------------- chi invita (host)

export interface InviteHandle extends LobbyHandle {
  setInvite(link: string, shareText: string): void;
  answerSent(): void;
  answerRejected(): void;
}

export function inviteScreen(ui: UI, o: {
  /** invito corto (cassetta cifrata): niente risposta da incollare, il duello parte da solo */
  auto?: boolean;
  onAnswer(text: string): void; onRetry(): void; onManual?: () => void; onFallback(): void; onCancel(): void;
}): InviteHandle {
  const st = statusLine();
  const countdown = h('small', { class: 'countdown' });
  const linkBox = h('textarea', { readonly: true, rows: o.auto ? '1' : '3', class: 'link-box', placeholder: "Preparo l'invito…" });
  const shareSlot = h('div', {});
  const answer = h('textarea', { rows: '2', placeholder: 'Incolla qui il link di risposta (#a=…)' });
  const connectBtn = h('button', { class: 'btn', onclick: () => o.onAnswer(answer.value) }, icon(ICONS.check), 'Connetti');
  const fail = failBox([
    { label: 'Nuovo invito', ico: ICONS.rotate, primary: true, onClick: o.onRetry },
    { label: 'Sfida via link', ico: ICONS.link, onClick: o.onFallback },
  ]);
  const step1 = step(1, "Manda l'invito", linkBox, shareSlot);
  const step2 = o.auto
    ? step(2, 'Aspetta qui',
      h('p', {}, "Quando l'avversario tocca il link e accetta, il duello parte da solo: non deve rimandarti niente. Puoi passare a WhatsApp e tornare."),
      o.onManual ? h('button', { class: 'btn ghost small', onclick: o.onManual }, icon(ICONS.key), 'Problemi? Usa il metodo manuale') : null)
    : step(2, 'Apri la sua risposta',
      h('p', {}, 'Quando ti rimanda il link di risposta, toccalo: il duello parte qui da solo. Oppure incollalo:'),
      h('div', { class: 'paste-row' }, answer, connectBtn));
  const el = h('div', { class: 'screen center' },
    h('div', { class: 'panel lobby' },
      h('div', { class: 'role-badge' }, 'DUELLO LIVE · INVITO'),
      h('h2', {}, 'Invita un avversario'),
      h('div', { class: 'steps' }, step1, step2),
      h('div', { class: 'status-row' }, st.el, countdown),
      warnBox(),
      fail.el,
      h('div', { class: 'row wrap' },
        h('button', { class: 'btn ghost', onclick: o.onCancel }, icon(ICONS.back), 'Annulla'),
        h('button', { class: 'btn ghost', onclick: o.onFallback }, icon(ICONS.link), 'Usa la sfida via link')),
    ));
  return {
    el,
    status: st.set,
    countdown: (t) => (countdown.textContent = t),
    fail(msg) {
      st.set('err', 'Collegamento non riuscito');
      countdown.textContent = '';
      connectBtn.disabled = true;
      fail.show(msg);
    },
    setInvite(link, shareText) {
      linkBox.value = link;
      shareSlot.replaceChildren(shareRow(ui, link, shareText));
    },
    answerSent() {
      step1.classList.add('done');
      connectBtn.disabled = true;
      answer.value = '';
    },
    answerRejected() {
      connectBtn.disabled = false;
      answer.focus();
    },
  };
}

// ---------------------------------------------------------------- chi riceve l'invito (ospite)

export interface JoinHandle extends LobbyHandle {
  setAnswer(link: string, shareText: string): void;
}

export function joinScreen(ui: UI, o: { auto?: boolean; name: string; onName(n: string): void; onAccept(): void; onFallback(): void; onCancel(): void }): JoinHandle {
  const st = statusLine();
  const countdown = h('small', { class: 'countdown' });
  const nameInput = h('input', { class: 'name-input', maxlength: '16', value: o.name, placeholder: 'Il tuo nome',
    oninput: (e: Event) => o.onName((e.target as HTMLInputElement).value) });
  const acceptBtn = h('button', { class: 'btn primary', onclick: () => {
    acceptBtn.disabled = true;
    nameInput.disabled = true;
    o.onAccept();
  } }, icon(ICONS.check), "Accetta l'invito");
  const linkBox = h('textarea', { readonly: true, rows: '3', class: 'link-box', placeholder: 'La risposta comparirà qui…' });
  const shareSlot = h('div', {});
  const fail = failBox([
    { label: 'Menu', ico: ICONS.back, onClick: o.onCancel },
    { label: 'Crea una sfida via link', ico: ICONS.link, primary: true, onClick: o.onFallback },
  ]);
  const step1 = step(1, 'Chi sei?', h('div', { class: 'paste-row' }, nameInput, acceptBtn));
  const step2 = step(2, 'Rimanda la risposta', linkBox, shareSlot,
    h('p', {}, "Il duello parte appena l'avversario apre questo link."));
  step2.classList.add('pending');
  // invito corto: la risposta parte da sola, il secondo passo non serve
  if (o.auto) step2.style.display = 'none';
  const el = h('div', { class: 'screen center' },
    h('div', { class: 'panel lobby' },
      h('div', { class: 'role-badge' }, 'DUELLO LIVE'),
      h('h2', {}, 'Sei stato sfidato in diretta!'),
      h('div', { class: 'steps' }, step1, step2),
      h('div', { class: 'status-row' }, st.el, countdown),
      warnBox(),
      fail.el,
      h('div', { class: 'row' }, h('button', { class: 'btn ghost', onclick: o.onCancel }, icon(ICONS.back), 'Annulla')),
    ));
  setTimeout(() => !o.name && nameInput.focus(), 50);
  return {
    el,
    status: st.set,
    countdown: (t) => (countdown.textContent = t),
    fail(msg) {
      st.set('err', 'Collegamento non riuscito');
      countdown.textContent = '';
      fail.show(msg);
    },
    setAnswer(link, shareText) {
      step1.classList.add('done');
      step2.classList.remove('pending');
      linkBox.value = link;
      shareSlot.replaceChildren(shareRow(ui, link, shareText));
    },
  };
}

// ---------------------------------------------------------------- attesa dell'attaccante

export interface WaitHandle {
  el: HTMLElement;
  progress(p: { blocks: number; spent: number; left: number }): void;
  status(tone: NetTone, msg: string): void;
}

export function waitBuildScreen(o: { defender: string; mode: ModeId; onQuit(): void }): WaitHandle {
  const mode = MODES[o.mode];
  const st = statusLine();
  const blocks = h('b', {}, '0');
  const spent = h('b', {}, '0');
  const left = h('b', {}, String(mode.buildTime));
  const bar = h('i', {});
  const title = h('h2', {}, `${o.defender} si prepara…`);
  st.set('ok', 'Collegati');
  const el = h('div', { class: 'screen center' },
    h('div', { class: 'panel handoff atk' },
      h('div', { class: 'role-badge' }, 'ATTACCO'),
      title,
      h('p', {}, 'Mimika si sta nascondendo nella sua fortezza. Appena è pronta tocca a te: studia bene i riflessi!'),
      h('div', { class: 'stat-row' },
        h('div', { class: 'stat' }, blocks, h('small', {}, 'Blocchi')),
        h('div', { class: 'stat' }, spent, h('small', {}, `Risorse su ${mode.budget}`)),
        h('div', { class: 'stat' }, left, h('small', {}, 'Secondi'))),
      h('div', { class: 'build-bar' }, bar),
      h('div', { class: 'status-row' }, st.el),
      h('div', { class: 'row' }, h('button', { class: 'btn ghost', onclick: o.onQuit }, icon(ICONS.back), 'Esci dal duello')),
    ));
  return {
    el,
    status: st.set,
    progress(p) {
      title.textContent = `${o.defender} sta costruendo…`;
      blocks.textContent = String(p.blocks);
      spent.textContent = String(p.spent);
      left.textContent = String(p.left);
      bar.style.width = `${Math.min(100, (100 * p.spent) / mode.budget)}%`;
    },
  };
}

// ---------------------------------------------------------------- avvisi generici

export function noticeScreen(o: { tone?: 'def' | 'atk'; badge: string; title: string; text: string; actions: Action[] }): HTMLElement {
  return h('div', { class: 'screen center' },
    h('div', { class: `panel handoff${o.tone ? ` ${o.tone}` : ''}` },
      h('div', { class: 'role-badge' }, o.badge),
      h('h2', {}, o.title),
      h('p', {}, o.text),
      h('div', { class: 'actions' }, ...o.actions.map(actionBtn)),
    ));
}
