import { MATERIALS, MATERIAL_ORDER, SHAPES, type MaterialId } from '../config/materials';
import { MODES, type ModeDef, type ModeId } from '../config/modes';
import { cellRect, inZone, pointToCell, type Cell } from '../config/world';
import type { PointerInfo } from '../core/input';
import { formatTime } from '../core/math';
import type { Game } from '../game/Game';
import {
  blockCost, blockIndexAt, blueprintCost, canPlaceBlock, decoyIndexAt, emptyBlueprint, isCellFree,
  type Blueprint, type PlacedBlock,
} from '../game/blueprint';
import { World } from '../game/World';
import { drawHunter, drawLauncher, drawMimika } from '../render/actors';
import { PALETTE, roundRectPath } from '../render/palette';
import { blueprintBlocks, drawBlocks, drawBlueprintCreatures, drawWorld, drawZone } from '../render/scenery';
import { h, icon, tip } from '../ui/dom';
import { ICONS } from '../ui/icons';
import { Coach } from '../ui/tutorial';
import type { Scene } from './Scene';

type Tool = 'build' | 'erase' | 'core' | 'decoy';

export interface BuildOptions {
  author: string;
  onDone: (bp: Blueprint) => void;
  onQuit: () => void;
  /** duello live: avanzamento visibile all'avversario (blocchi, risorse spese, secondi rimasti) */
  onProgress?: (p: { blocks: number; spent: number; left: number }) => void;
}

/** Fase del difensore: costruire la fortezza e nascondere Mimika (più le esche). */
export class BuildScene implements Scene {
  private readonly mode: ModeDef;
  private readonly bp: Blueprint;
  private mat: MaterialId = 'wood';
  private shapeIdx = 0;
  private rotated = false;
  private tool: Tool = 'build';
  private timeLeft: number;
  private hover: Cell | null = null;
  private pressed = false;
  private test: World | null = null;
  private done = false;
  private lastSecond = -1;
  private coach: Coach | null = null;
  private hud!: {
    timer: HTMLElement; budgetText: HTMLElement; budgetBar: HTMLElement; hint: HTMLElement;
    buttons: Map<string, HTMLElement>; decoyCount: HTMLElement; testBtn: HTMLElement;
  };

  constructor(private game: Game, modeId: ModeId, private opts: BuildOptions) {
    this.mode = MODES[modeId];
    this.bp = emptyBlueprint(modeId, opts.author);
    this.timeLeft = this.mode.buildTime;
  }

  // ------------------------------------------------------------------ ciclo di vita

  enter(): void {
    this.game.ui.hud(this.buildHud());
    this.refresh();
    this.setHint(`Costruisci attorno a Mimika. ${MATERIALS[this.mat].name}: ${MATERIALS[this.mat].blurb}`);
    this.coach = Coach.start(this.game.ui, 'build');
  }

  exit(): void {
    this.coach?.close();
    this.game.ui.hud(null);
  }

  update(dt: number): void {
    if (this.test) this.test.step(dt);
    if (this.done) return;
    this.timeLeft -= dt / 1000;
    const sec = Math.ceil(this.timeLeft);
    if (sec !== this.lastSecond) {
      this.lastSecond = sec;
      this.hud.timer.textContent = formatTime(this.timeLeft);
      this.hud.timer.classList.toggle('warn', this.timeLeft <= 10);
      if (this.timeLeft <= 5 && this.timeLeft > 0) this.game.sfx.tick();
      this.report();
    }
    if (this.timeLeft <= 0) {
      this.game.ui.toast('Tempo! La fortezza è pronta.', 'warn');
      this.finish();
    }
  }

  // ------------------------------------------------------------------ disegno

  render(g: CanvasRenderingContext2D, t: number): void {
    drawZone(g, t, this.test ? 0.3 : 1);
    drawHunter(g, t);
    drawLauncher(g, t, null, null);
    if (this.test) {
      drawWorld(g, this.test, t, { creature: (e) => ({ style: e.kind === 'core' ? 'live' : 'decoy', alpha: 1 }) });
      return;
    }
    drawBlocks(g, blueprintBlocks(this.bp));
    drawBlueprintCreatures(g, this.bp, t, this.hover ? cellRect(this.hover.col, this.hover.row) : undefined);
    if (this.hover) this.drawGhost(g, t);
  }

  private drawGhost(g: CanvasRenderingContext2D, t: number): void {
    const cell = this.hover!;
    if (this.tool === 'build') {
      const b = this.ghostAt(cell);
      const ok = this.canAfford(b) && canPlaceBlock(this.bp, b);
      const r = cellRect(b.col, b.row, b.w, b.h);
      drawBlocks(g, [{ mat: b.mat, x: r.cx, y: r.cy, w: r.w, h: r.h, angle: 0, hp: 1, maxHp: 1, seed: 1, flash: 0 }], 0.55);
      outline(g, r, ok ? PALETTE.defender : PALETTE.attacker);
    } else if (this.tool === 'erase') {
      const i = blockIndexAt(this.bp, cell.col, cell.row);
      const d = decoyIndexAt(this.bp, cell.col, cell.row);
      if (i >= 0) {
        const b = this.bp.blocks[i];
        const r = cellRect(b.col, b.row, b.w, b.h);
        g.fillStyle = 'rgba(255,122,107,0.35)';
        g.fillRect(r.x, r.y, r.w, r.h);
        outline(g, r, PALETTE.attacker);
      } else if (d >= 0) outline(g, cellRect(cell.col, cell.row), PALETTE.attacker);
    } else if (inZone(cell.col, cell.row)) {
      const r = cellRect(cell.col, cell.row);
      const ok = this.tool === 'core' ? isCellFree(this.bp, cell.col, cell.row) : this.decoyAllowed(cell);
      drawMimika(g, r.cx, r.cy + 3, t, { style: this.tool === 'core' ? 'live' : 'decoy', alpha: 0.5 });
      outline(g, r, ok ? PALETTE.defender : PALETTE.attacker);
    }
  }

  // ------------------------------------------------------------------ input

  down(p: PointerInfo): void {
    if (this.test || this.done) return;
    this.pressed = true;
    this.hover = pointToCell(p.x, p.y);
    if (this.tool === 'erase') this.eraseAt(this.hover);
  }

  move(p: PointerInfo, pressed: boolean): void {
    if (this.test || this.done) return;
    if (!pressed && p.type === 'touch') return;
    const cell = pointToCell(p.x, p.y);
    const changed = !this.hover || cell.col !== this.hover.col || cell.row !== this.hover.row;
    this.hover = cell;
    if (pressed && changed && this.tool === 'erase') this.eraseAt(cell);
  }

  up(p: PointerInfo): void {
    if (this.test || this.done || !this.pressed) return;
    this.pressed = false;
    const cell = pointToCell(p.x, p.y);
    if (this.tool === 'build') this.place(cell);
    else if (this.tool === 'core') this.moveCore(cell);
    else if (this.tool === 'decoy') this.toggleDecoy(cell);
    if (p.type === 'touch') this.hover = null;
  }

  key(e: KeyboardEvent): void {
    const k = e.key.toLowerCase();
    const n = Number(k);
    if (n >= 1 && n <= MATERIAL_ORDER.length) this.selectMaterial(MATERIAL_ORDER[n - 1]);
    else if (k === 'r') this.rotate();
    else if (k === 'q') this.selectShape((this.shapeIdx + SHAPES.length - 1) % SHAPES.length);
    else if (k === 'w') this.selectShape((this.shapeIdx + 1) % SHAPES.length);
    else if (k === 'e') this.setTool('erase');
    else if (k === 'm') this.setTool('core');
    else if (k === 'd') this.setTool('decoy');
    else if (k === 'b') this.setTool('build');
    else if (k === 'g') this.toggleTest();
    else if (k === 'enter') this.finish();
  }

  // ------------------------------------------------------------------ azioni

  private ghostAt(cell: Cell): PlacedBlock {
    const s = SHAPES[this.shapeIdx];
    const w = this.rotated ? s.h : s.w;
    const hgt = this.rotated ? s.w : s.h;
    return { mat: this.mat, col: cell.col - Math.floor((w - 1) / 2), row: cell.row - Math.floor((hgt - 1) / 2), w, h: hgt };
  }

  private canAfford(b: PlacedBlock): boolean {
    return blueprintCost(this.bp) + blockCost(b) <= this.mode.budget;
  }

  private place(cell: Cell): void {
    const b = this.ghostAt(cell);
    if (!inZone(b.col, b.row, b.w, b.h)) return;
    if (!this.canAfford(b)) return this.deny('Risorse insufficienti per questo blocco.');
    if (!canPlaceBlock(this.bp, b)) return this.deny('Spazio occupato.');
    this.bp.blocks.push(b);
    const r = cellRect(b.col, b.row, b.w, b.h);
    this.game.particles.dust(r.cx, r.y + r.h, 3, 'rgba(255,255,255,0.35)');
    this.game.sfx.place();
    this.coach?.signal('place');
    this.refresh();
  }

  private eraseAt(cell: Cell): void {
    const i = blockIndexAt(this.bp, cell.col, cell.row);
    const d = decoyIndexAt(this.bp, cell.col, cell.row);
    if (i >= 0) {
      const [b] = this.bp.blocks.splice(i, 1);
      const r = cellRect(b.col, b.row, b.w, b.h);
      this.game.particles.debris(r.cx, r.cy, b.mat, 5);
    } else if (d >= 0) this.bp.decoys.splice(d, 1);
    else return;
    this.game.sfx.erase();
    this.refresh();
  }

  private moveCore(cell: Cell): void {
    if (!inZone(cell.col, cell.row) || !isCellFree(this.bp, cell.col, cell.row)) return this.deny('Mimika ha bisogno di una cella libera.');
    this.bp.core = cell;
    this.game.sfx.squeak();
    this.coach?.signal('core');
    this.game.ui.toast('Mimika si è nascosta qui.', 'good');
  }

  private decoyAllowed(cell: Cell): boolean {
    return inZone(cell.col, cell.row) && isCellFree(this.bp, cell.col, cell.row) && this.bp.decoys.length < this.mode.decoys;
  }

  private toggleDecoy(cell: Cell): void {
    const d = decoyIndexAt(this.bp, cell.col, cell.row);
    if (d >= 0) {
      this.bp.decoys.splice(d, 1);
      this.game.sfx.erase();
    } else if (this.decoyAllowed(cell)) {
      this.bp.decoys.push(cell);
      this.game.sfx.pop();
      this.coach?.signal('decoy');
    } else {
      return this.deny(this.bp.decoys.length >= this.mode.decoys ? 'Hai finito le esche.' : 'Cella occupata.');
    }
    this.refresh();
  }

  private toggleTest(): void {
    if (this.done) return;
    if (this.test) {
      this.test = null;
      this.setHint('Progetto ripristinato. Rinforza i punti deboli!');
    } else {
      let crushed = false;
      this.test = new World(this.bp, {
        broken: (e) => e.mat && this.game.particles.debris(e.body.position.x, e.body.position.y, e.mat, 8),
        impact: (x, y, s) => s > 0.3 && this.game.particles.dust(x, y, 2),
        coreHit: () => (crushed = true),
      });
      setTimeout(() => crushed && this.test && this.game.ui.toast('Attenzione: così Mimika verrebbe schiacciata!', 'warn'), 2500);
      this.setHint('Prova di gravità: i blocchi senza appoggio cadono. Il progetto non cambia.');
    }
    this.hud.testBtn.classList.toggle('active', !!this.test);
    this.game.sfx.click();
  }

  private finish(): void {
    if (this.done) return;
    this.done = true;
    this.test = null;
    this.hover = null;
    this.coach?.signal('done');
    this.game.sfx.click();
    this.opts.onDone(this.bp);
  }

  private deny(msg: string): void {
    this.game.sfx.deny();
    this.setHint(msg, true);
  }

  private selectMaterial(m: MaterialId): void {
    this.mat = m;
    this.tool = 'build';
    this.game.sfx.click();
    this.coach?.signal('material');
    this.setHint(`${MATERIALS[m].name} (${MATERIALS[m].cost}/cella): ${MATERIALS[m].blurb}`);
    this.refresh();
  }

  private selectShape(i: number): void {
    this.shapeIdx = i;
    this.tool = 'build';
    this.game.sfx.click();
    this.refresh();
  }

  private rotate(): void {
    this.rotated = !this.rotated;
    this.tool = 'build';
    this.game.sfx.click();
    this.refresh();
  }

  private setTool(t: Tool): void {
    this.tool = t;
    this.game.sfx.click();
    const hints: Record<Tool, string> = {
      build: 'Tocca la zona tratteggiata per piazzare il blocco.',
      erase: 'Tocca o trascina sui blocchi per rimuoverli (rimborso pieno).',
      core: 'Tocca una cella libera: Mimika si nasconderà lì. In attacco sarà quasi invisibile.',
      decoy: `Le esche luccicano come Mimika e confondono l'attaccante (${this.bp.decoys.length}/${this.mode.decoys}).`,
    };
    this.setHint(hints[t]);
    this.refresh();
  }

  // ------------------------------------------------------------------ HUD

  private setHint(text: string, warn = false): void {
    this.hud.hint.textContent = text;
    this.hud.hint.classList.toggle('warn', warn);
  }

  private refresh(): void {
    const spent = blueprintCost(this.bp);
    this.hud.budgetText.textContent = `${this.mode.budget - spent}`;
    this.hud.budgetBar.style.width = `${(100 * (this.mode.budget - spent)) / this.mode.budget}%`;
    this.hud.decoyCount.textContent = `${this.mode.decoys - this.bp.decoys.length}`;
    for (const [key, el] of this.hud.buttons) {
      const [kind, id] = key.split(':');
      const active =
        (kind === 'mat' && this.tool === 'build' && id === this.mat) ||
        (kind === 'shape' && this.tool === 'build' && Number(id) === this.shapeIdx) ||
        (kind === 'tool' && id === this.tool) ||
        (kind === 'rot' && this.rotated);
      el.classList.toggle('active', active);
      if (kind === 'shape') el.classList.toggle('rotated', this.rotated);
    }
    this.report();
  }

  private report(): void {
    this.opts.onProgress?.({ blocks: this.bp.blocks.length, spent: blueprintCost(this.bp), left: Math.max(0, Math.ceil(this.timeLeft)) });
  }

  private buildHud(): HTMLElement {
    const buttons = new Map<string, HTMLElement>();
    const reg = (key: string, el: HTMLElement) => (buttons.set(key, el), el);

    const timer = h('div', { class: 'timer' }, formatTime(this.timeLeft));
    const budgetText = h('b', {}, String(this.mode.budget));
    const budgetBar = h('i', {});
    const hint = h('div', { class: 'hint' });
    const decoyCount = h('em', { class: 'badge' }, String(this.mode.decoys));
    const testBtn = h('button', { class: 'btn small', onclick: () => this.toggleTest(), 'data-tut': 'test', 'aria-label': 'Prova gravità',
      'data-tip': tip('Prova gravità (G)', 'Simula il crollo: i blocchi senza appoggio cadono.', 'Il progetto non cambia.') }, icon(ICONS.gravity), h('span', {}, 'Prova'));

    const materials = MATERIAL_ORDER.map((m) =>
      reg(`mat:${m}`, h('button', {
        class: `tool mat mat-${m}`, 'aria-label': MATERIALS[m].name, onclick: () => this.selectMaterial(m),
        'data-tip': tip(`${MATERIALS[m].name} · ${MATERIALS[m].cost} per cella (${MATERIAL_ORDER.indexOf(m) + 1})`, MATERIALS[m].blurb),
        style: { '--swatch': MATERIALS[m].color, '--swatch-dark': MATERIALS[m].dark },
      }, h('span', { class: 'swatch' }), h('small', {}, `${MATERIALS[m].name} ${MATERIALS[m].cost}`))),
    );
    const shapes = SHAPES.map((s, i) =>
      reg(`shape:${i}`, h('button', { class: 'tool shape', 'aria-label': `Forma ${s.id}`, 'data-tip': tip(`Forma ${s.w}×${s.h}`, 'Q / W per cambiare forma, R per ruotare.'), onclick: () => this.selectShape(i) },
        h('span', { class: 'shape-preview', style: { '--w': String(s.w), '--h': String(s.h) } },
          ...Array.from({ length: s.w * s.h }, () => h('i', {}))))),
    );
    const rot = reg('rot:0', h('button', { class: 'tool', 'aria-label': 'Ruota', 'data-tip': tip('Ruota (R)', 'Gira la forma di 90°.'), onclick: () => this.rotate() }, icon(ICONS.rotate), h('small', {}, 'Ruota')));
    const tools = [
      reg('tool:core', h('button', { class: 'tool', 'data-tut': 'core', 'aria-label': 'Sposta Mimika', 'data-tip': tip('Sposta Mimika (M)', 'Tocca una cella libera: si nasconde lì.', 'In attacco sarà quasi invisibile.'), onclick: () => this.setTool('core') }, icon(ICONS.mimika), h('small', {}, 'Mimika'))),
      reg('tool:decoy', h('button', { class: 'tool', 'data-tut': 'decoy', 'aria-label': 'Esca', 'data-tip': tip(`Esca (D) · ${this.mode.decoys} disponibili`, 'Luccica come Mimika e inganna chi attacca.', 'Tocca di nuovo per toglierla.'), onclick: () => this.setTool('decoy') }, icon(ICONS.decoy), decoyCount, h('small', {}, 'Esca'))),
      reg('tool:erase', h('button', { class: 'tool', 'aria-label': 'Gomma', 'data-tip': tip('Gomma (E)', 'Tocca o trascina sui blocchi per toglierli.', 'Rimborso pieno delle risorse.'), onclick: () => this.setTool('erase') }, icon(ICONS.erase), h('small', {}, 'Gomma'))),
    ];

    this.hud = { timer, budgetText, budgetBar, hint, buttons, decoyCount, testBtn };

    return h('div', { class: 'hud build-hud' },
      h('div', { class: 'hud-top' },
        h('div', { class: 'role-pill def' }, h('b', {}, 'DIFESA'), h('span', {}, `${this.opts.author} · ${this.mode.name}`)),
        timer,
        h('div', { class: 'hud-actions' },
          h('div', { class: 'budget', 'data-tip': tip('Risorse rimaste', 'Ogni cella costa secondo il materiale.') }, h('span', {}, 'Risorse'), budgetText, h('div', { class: 'bar' }, budgetBar)),
          testBtn,
          h('button', { class: 'btn small primary', onclick: () => this.finish(), 'data-tut': 'done', 'aria-label': 'Pronto', 'data-tip': tip('Pronto (Invio)', 'La fortezza passa a chi attacca.') }, icon(ICONS.check), h('span', {}, 'Pronto')),
        ),
      ),
      hint,
      h('div', { class: 'dock' },
        h('div', { class: 'dock-group' }, ...materials),
        h('div', { class: 'dock-sep' }),
        h('div', { class: 'dock-group' }, ...shapes, rot),
        h('div', { class: 'dock-sep' }),
        h('div', { class: 'dock-group' }, ...tools),
      ),
      h('button', { class: 'quit-btn', 'aria-label': 'Esci', 'data-tip': 'Esci', onclick: () => this.opts.onQuit() }, icon(ICONS.back)),
    );
  }
}

function outline(g: CanvasRenderingContext2D, r: { x: number; y: number; w: number; h: number }, color: string): void {
  g.save();
  g.strokeStyle = color;
  g.lineWidth = 3;
  g.setLineDash([6, 5]);
  roundRectPath(g, r.x + 1, r.y + 1, r.w - 2, r.h - 2, 6);
  g.stroke();
  g.restore();
}
