export interface PointerInfo {
  /** coordinate mondo */
  x: number;
  y: number;
  /** coordinate schermo (px CSS) */
  sx: number;
  sy: number;
  type: string;
}

export interface PointerHandlers {
  down(p: PointerInfo): void;
  move(p: PointerInfo, pressed: boolean): void;
  up(p: PointerInfo): void;
}

/**
 * Input unificato mouse/touch/penna con Pointer Events. Segue un solo puntatore alla volta
 * (il gioco è a un dito): un secondo dito non disturba la mira in corso.
 */
export class Input {
  private active: number | null = null;

  constructor(
    canvas: HTMLCanvasElement,
    toWorld: (sx: number, sy: number) => { x: number; y: number },
    handlers: () => PointerHandlers | null,
  ) {
    const info = (e: PointerEvent): PointerInfo => {
      const rect = canvas.getBoundingClientRect();
      const sx = e.clientX - rect.left;
      const sy = e.clientY - rect.top;
      return { ...toWorld(sx, sy), sx, sy, type: e.pointerType };
    };
    canvas.addEventListener('pointerdown', (e) => {
      if (this.active !== null) return;
      this.active = e.pointerId;
      canvas.setPointerCapture(e.pointerId);
      handlers()?.down(info(e));
    });
    canvas.addEventListener('pointermove', (e) => {
      if (this.active !== null && e.pointerId !== this.active) return;
      handlers()?.move(info(e), this.active !== null);
    });
    const end = (e: PointerEvent) => {
      if (e.pointerId !== this.active) return;
      this.active = null;
      handlers()?.up(info(e));
    };
    canvas.addEventListener('pointerup', end);
    canvas.addEventListener('pointercancel', end);
    canvas.addEventListener('contextmenu', (e) => e.preventDefault());
  }
}
