import { MODES, type ModeId } from '../config/modes';
import { THEMES } from '../render/themes';
import { formatTime } from '../core/math';
import { makeLink, parseLinkInput, type MatchReport } from '../net/links';
import { PROTOCOL_VERSION, type NetMessage } from '../net/protocol';
import { NetSession } from '../net/session';
import { LiveBroadcaster } from '../net/snapshot';
import { PeerLink, listenForwardedAnswers, type PeerState } from '../net/webrtc';
import { isRoomCode, listen, newRoom, openRoom, post, randomId, relaySupported, roomCode, type RelayMsg, type Room } from '../net/relay';
import type { AttackResult } from '../scenes/AttackScene';
import { BackdropScene } from '../scenes/BackdropScene';
import { SpectatorScene } from '../scenes/SpectatorScene';
import { ICONS } from '../ui/icons';
import {
  inviteScreen, joinScreen, noticeScreen, waitBuildScreen, type InviteHandle, type JoinHandle, type LobbyHandle, type WaitHandle,
} from '../ui/lobby';
import { resultScreen, type Action } from '../ui/screens';
import { emptyBlueprint, fromWire, toWire, type Blueprint } from './blueprint';
import type { Game } from './Game';

/** secondi di validità di invito e risposta: oltre, le mappature NAT scadono (doc 04) */
const INVITE_TTL = 120;
/** invito corto (cassetta cifrata): la trattativa WebRTC parte solo quando l'ospite accetta, quindi può durare di più */
const ROOM_TTL = 30 * 60;
/** l'ospite aspetta l'offerta (chi invita può essere ancora su WhatsApp e tornare dopo) */
const OFFER_WAIT = 5 * 60_000;
/** messaggio quando il collegamento diretto non riesce: il caso più comune è tra due telefoni su dati mobili */
const DIRECT_FAIL = 'Collegamento diretto non riuscito. Succede spesso quando tutti e due i telefoni sono su dati mobili: provate con almeno uno dei due collegato a una Wi-Fi, oppure usate la sfida via link (funziona sempre).';
/** dopo aver applicato la risposta, entro quanto deve aprirsi il canale */
const CONNECT_TIMEOUT = 25_000;
const PROGRESS_THROTTLE = 250;

type Phase = 'lobby' | 'defend' | 'wait-build' | 'ready' | 'attack' | 'spectate' | 'result';
type Progress = { blocks: number; spent: number; left: number };

const isNum = (v: unknown): v is number => typeof v === 'number' && Number.isFinite(v);

/**
 * Duello live P2P: lobby con signaling manuale, poi round a ruoli alterni sullo stesso canale.
 *   host  = chi crea l'invito (#o=): sceglie la modalità e difende per primo
 *   guest = chi lo accetta e rimanda la risposta (#a=)
 * Fisica autorevole sull'attaccante: il difensore guarda l'assedio in SpectatorScene.
 * Se la connessione cade, si ripiega sui link (sfida #c= o referto #r=).
 */
export class LiveDuel {
  private peer: PeerLink | null = null;
  private session: NetSession | null = null;
  private phase: Phase = 'lobby';
  /** [host, guest] */
  private readonly names: [string, string];
  private readonly score: [number, number] = [0, 0];
  private mode: ModeId;
  private defender: 0 | 1 = 0;
  private offline = false;
  private disposed = false;
  private answerApplied = false;
  private rematch = { me: false, peer: false };
  private bp: Blueprint | null = null;
  private report: MatchReport | null = null;
  private invite: InviteHandle | null = null;
  private join: JoinHandle | null = null;
  private wait: WaitHandle | null = null;
  private spectator: SpectatorScene | null = null;
  private stopForward: () => void = () => {};
  /** cassetta cifrata del signaling (inviti corti) */
  private room: Room | null = null;
  private stopRelay: () => void = () => {};
  /** sessione dell'ospite con cui si sta trattando (join → offer → answer) */
  private relayN = '';
  private countdownTimer: ReturnType<typeof setInterval> | undefined;
  private connectTimer: ReturnType<typeof setTimeout> | undefined;
  private progressTimer: ReturnType<typeof setTimeout> | undefined;
  private pendingProgress: Progress | null = null;

  private constructor(private readonly game: Game, readonly role: 'host' | 'guest') {
    this.mode = game.currentMode;
    this.names = role === 'host' ? [game.nameOr('Giocatore 1'), 'Avversario'] : ['Avversario', game.nameOr('Giocatore 2')];
    window.addEventListener('pagehide', this.onPageHide);
  }

  /** Crea l'invito (link corto se c'è la cassetta, altrimenti offerta manuale) e attende l'avversario. */
  static host(game: Game): LiveDuel {
    const duel = new LiveDuel(game, 'host');
    if (relaySupported()) void duel.createRoomInvite();
    else void duel.createInvite();
    return duel;
  }

  /** Ha ricevuto un invito: chiede il nome e prepara la risposta. */
  static guest(game: Game, offerCode: string): LiveDuel {
    const duel = new LiveDuel(game, 'guest');
    duel.showJoin(offerCode);
    return duel;
  }

  private get me(): 0 | 1 {
    return this.role === 'host' ? 0 : 1;
  }

  private get myName(): string {
    return this.names[this.me];
  }

  private get peerName(): string {
    return this.names[1 - this.me];
  }

  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    this.stopTimers();
    this.stopForward();
    this.stopRelay();
    if (this.session) this.session.close();
    else this.peer?.close();
    this.session = null;
    this.peer = null;
    window.removeEventListener('beforeunload', this.onUnload);
    window.removeEventListener('pagehide', this.onPageHide);
  }

  // ------------------------------------------------------------------ lobby: chi invita (link corto)

  /**
   * Invito corto: il link porta solo il segreto della cassetta. Quando l'ospite accetta manda "join",
   * qui si crea un'offerta fresca, lui risponde e il duello parte da solo (nessun link di ritorno).
   */
  private async createRoomInvite(): Promise<void> {
    this.resetPeer();
    this.stopRelay();
    const view = (this.invite = inviteScreen(this.game.ui, {
      auto: true,
      onAnswer: () => {},
      onRetry: () => void this.createRoomInvite(),
      onManual: () => void this.createInvite(),
      onFallback: () => this.fallback(),
      onCancel: () => this.game.showMenu(),
    }));
    this.game.setScene(new BackdropScene(this.game));
    this.game.ui.screen(view.el);
    const room = (this.room = await newRoom());
    if (this.disposed || this.invite !== view) return;
    window.addEventListener('beforeunload', this.onUnload);
    view.setInvite(makeLink('o', roomCode(room)), `${this.myName} ti sfida a un duello live a Mimika! Tocca il link e accetta:`);
    view.status('wait', "Invito pronto: quando l'avversario lo apre e accetta, il duello parte da solo");
    this.stopRelay = listen(room, (m) => void this.onRelayHost(m), () => {
      if (this.invite !== view || this.session || this.relayN) return;
      this.game.ui.toast('Il servizio per gli inviti corti non risponde: uso il metodo manuale.', 'warn');
      void this.createInvite();
    });
    this.startCountdown(view, () => {
      this.stopRelay();
      this.peer?.close();
      view.fail("L'invito è scaduto. Creane uno nuovo, oppure usa la sfida via link.");
    }, ROOM_TTL);
  }

  private async onRelayHost(m: RelayMsg): Promise<void> {
    const room = this.room;
    if (!room || this.role !== 'host' || this.phase !== 'lobby' || this.session || this.disposed) return;
    const view = this.invite!;
    if (m.t === 'join') {
      // l'ultimo join vince (l'ospite può aver ricaricato la pagina): offerta nuova, NAT appena aperto
      this.relayN = m.n;
      this.names[1] = String(m.name || 'Avversario').trim().slice(0, 16) || 'Avversario';
      this.resetPeer();
      view.answerSent();
      view.status('wait', `${this.peerName} ha accettato: mi collego…`);
      const peer = this.newPeer();
      let sdp: string;
      try {
        sdp = await peer.createOffer();
      } catch {
        if (peer === this.peer) view.fail('Questo browser non riesce a creare la connessione diretta. Usa la sfida via link.');
        return;
      }
      if (peer !== this.peer || this.relayN !== m.n) return;
      view.status('wait', `${this.peerName} ha accettato: mi collego…`);
      if (!(await post(room, { t: 'offer', n: m.n, sdp })) && this.relayN === m.n) view.status('wait', 'La rete non risponde: controlla la connessione');
    } else if (m.t === 'answer' && m.n === this.relayN) {
      this.applyAnswer(m.sdp);
    }
  }

  // ------------------------------------------------------------------ lobby: chi invita (metodo manuale)

  private async createInvite(): Promise<void> {
    this.resetPeer();
    this.stopRelay();
    this.stopRelay = () => {};
    this.room = null;
    const view = (this.invite = inviteScreen(this.game.ui, {
      onAnswer: (text) => this.submitAnswer(text),
      onRetry: () => void this.createInvite(),
      onFallback: () => this.fallback(),
      onCancel: () => this.game.showMenu(),
    }));
    this.game.setScene(new BackdropScene(this.game));
    this.game.ui.screen(view.el);
    view.status('wait', "Preparo l'invito…");
    const peer = this.newPeer();
    let code: string;
    try {
      code = await peer.createOffer();
    } catch {
      if (peer === this.peer) view.fail('Questo browser non riesce a creare la connessione diretta. Usa la sfida via link.');
      return;
    }
    if (peer !== this.peer || this.disposed) return;
    view.setInvite(makeLink('o', code), `${this.myName} ti sfida a un duello live a Mimika! Apri il link e rimandami la risposta entro 2 minuti:`);
    view.status('wait', 'Invito pronto: mandalo e attendi la risposta');
    this.stopForward = listenForwardedAnswers((answer) => this.applyAnswer(answer));
    this.startCountdown(view, () => {
      peer.close();
      view.fail("L'invito è scaduto: dopo un paio di minuti la rete chiude le \"porte\" aperte per voi. Creane uno nuovo, oppure usa la sfida via link.");
    });
  }

  private submitAnswer(text: string): void {
    const parsed = parseLinkInput(text, 'a');
    if (parsed?.key === 'o') return this.game.ui.toast('Questo è il tuo invito: serve il link di risposta.', 'warn');
    if (parsed?.key !== 'a') return this.game.ui.toast('Link di risposta non riconosciuto.', 'warn');
    if (!this.applyAnswer(parsed.code)) this.game.ui.toast('Nessun invito in attesa in questa scheda.', 'warn');
  }

  /** Risposta dell'ospite (incollata, da link nella stessa scheda o inoltrata via BroadcastChannel). */
  applyAnswer(code: string): boolean {
    const peer = this.peer;
    if (this.role !== 'host' || this.phase !== 'lobby' || !peer || this.answerApplied || this.offline || this.disposed) return false;
    this.answerApplied = true;
    this.stopTimers();
    const view = this.invite!;
    view.answerSent();
    view.status('wait', 'Risposta ricevuta: mi collego…');
    peer.acceptAnswer(code).catch(() => {
      if (peer !== this.peer) return;
      this.answerApplied = false;
      view.answerRejected();
      view.status('wait', 'Risposta non valida: incollala di nuovo');
      this.game.ui.toast('Risposta incompleta o non valida: fattela rimandare copiandola tutta.', 'warn');
    });
    this.connectTimer = setTimeout(() => this.lobbyFail(DIRECT_FAIL), CONNECT_TIMEOUT);
    return true;
  }

  // ------------------------------------------------------------------ lobby: chi riceve l'invito

  private showJoin(offerCode: string): void {
    const view = (this.join = joinScreen(this.game.ui, {
      auto: isRoomCode(offerCode),
      name: this.game.nameOr(''),
      onName: (n) => this.game.setName(n),
      onAccept: () => void this.acceptInvite(offerCode),
      onFallback: () => this.fallback(),
      onCancel: () => this.game.showMenu(),
    }));
    this.game.setScene(new BackdropScene(this.game));
    this.game.ui.screen(view.el);
    view.status('wait', 'Scrivi il tuo nome e accetta');
  }

  private async acceptInvite(offerCode: string): Promise<void> {
    if (isRoomCode(offerCode)) return this.joinRoom(offerCode);
    const view = this.join!;
    this.names[1] = this.game.nameOr('Giocatore 2');
    const peer = this.newPeer();
    view.status('wait', 'Preparo la risposta…');
    let answer: string;
    try {
      answer = await peer.acceptOffer(offerCode);
    } catch {
      if (peer === this.peer) this.lobbyFail("Invito incompleto o non valido: fattelo rimandare copiandolo tutto.");
      return;
    }
    if (peer !== this.peer || this.disposed || this.session) return;
    view.setAnswer(makeLink('a', answer), 'Ecco la mia risposta al duello live di Mimika: aprila per iniziare!');
    view.status('wait', "In attesa che l'avversario apra la risposta…");
    this.startCountdown(view, () => this.lobbyFail(
      "Tempo scaduto: l'avversario non ha aperto la risposta in tempo. Fatti mandare un nuovo invito, oppure create una sfida via link.",
    ));
  }

  /** Invito corto: "join" nella cassetta, poi offerta → risposta automatica. */
  private async joinRoom(code: string): Promise<void> {
    const view = this.join!;
    this.names[1] = this.game.nameOr('Giocatore 2');
    if (!relaySupported()) return this.lobbyFail('Questo browser è troppo vecchio per gli inviti corti: fatti mandare una sfida via link.');
    view.status('wait', 'Mi collego a chi ti ha invitato…');
    const room = (this.room = await openRoom(code.slice(1)));
    const n = (this.relayN = randomId());
    let handled = false;
    window.addEventListener('beforeunload', this.onUnload);
    this.stopRelay = listen(room, async (m) => {
      if (m.t !== 'offer' || m.n !== n || handled || this.session || this.disposed) return;
      handled = true;
      clearTimeout(this.connectTimer);
      const peer = this.newPeer();
      let sdp: string;
      try {
        sdp = await peer.acceptOffer(m.sdp);
      } catch {
        if (peer === this.peer) this.lobbyFail('Invito non valido: fattene mandare uno nuovo.');
        return;
      }
      if (peer !== this.peer || this.disposed) return;
      await post(room, { t: 'answer', n, sdp });
      view.status('wait', 'Mi collego…');
      this.connectTimer = setTimeout(() => this.lobbyFail(DIRECT_FAIL), CONNECT_TIMEOUT);
    }, () => this.lobbyFail('Il servizio per gli inviti corti non risponde. Chiedi un invito col «metodo manuale», oppure usate la sfida via link.'));
    if (!(await post(room, { t: 'join', n, name: this.names[1] }))) return this.lobbyFail('Non riesco a raggiungere il servizio degli inviti: controlla la connessione e riprova.');
    // chi invita può essere ancora su WhatsApp: appena torna sulla pagina dell'invito, l'offerta arriva
    setTimeout(() => !handled && !this.disposed && view.status('wait', `In attesa che chi ti ha invitato torni sulla pagina del gioco…`), 6000);
    this.connectTimer = setTimeout(() => !handled && this.lobbyFail(
      "Chi ti ha invitato non ha risposto: deve tenere aperta la pagina dell'invito. Fatti mandare un nuovo link.",
    ), OFFER_WAIT);
  }

  // ------------------------------------------------------------------ connessione

  private newPeer(): PeerLink {
    // da qui c'è un collegamento da proteggere: chiudere la scheda lo perderebbe (stesso listener = nessun doppione)
    window.addEventListener('beforeunload', this.onUnload);
    const peer = (this.peer = new PeerLink());
    peer.onState = (s) => this.onPeerState(peer, s);
    peer.onOpen = () => this.onOpen(peer);
    return peer;
  }

  private resetPeer(): void {
    this.stopTimers();
    this.stopForward();
    this.stopForward = () => {};
    this.peer?.close();
    this.peer = null;
    this.answerApplied = false;
  }

  private onPeerState(peer: PeerLink, s: PeerState): void {
    if (peer !== this.peer || this.phase !== 'lobby' || this.session) return;
    const view = this.invite ?? this.join;
    if (s === 'connecting' && this.answerApplied) view?.status('wait', 'Mi collego…');
    else if (s === 'failed') this.lobbyFail(DIRECT_FAIL);
  }

  private onOpen(peer: PeerLink): void {
    if (peer !== this.peer || this.session || this.disposed) return;
    this.stopTimers();
    this.stopForward();
    this.stopRelay();
    this.session = new NetSession(peer, { message: (m) => this.onMessage(m), lost: (r) => this.onLost(r) });
    this.session.send({ t: 'hello', ver: PROTOCOL_VERSION, name: this.myName });
    (this.invite ?? this.join)?.status('ok', 'Collegati! Un attimo…');
    this.game.sfx.ping();
  }

  private lobbyFail(msg: string): void {
    if (this.phase !== 'lobby' || this.session) return;
    this.stopTimers();
    this.stopRelay();
    this.peer?.close();
    (this.invite ?? this.join)?.fail(msg);
  }

  private startCountdown(view: LobbyHandle, onExpire: () => void, ttl = INVITE_TTL): void {
    clearInterval(this.countdownTimer);
    let left = ttl;
    const tick = () => {
      view.countdown(`scade tra ${formatTime(left)}`);
      if (left-- <= 0) {
        clearInterval(this.countdownTimer);
        onExpire();
      }
    };
    tick();
    this.countdownTimer = setInterval(tick, 1000);
  }

  private stopTimers(): void {
    clearInterval(this.countdownTimer);
    clearTimeout(this.connectTimer);
    clearTimeout(this.progressTimer);
    this.progressTimer = undefined;
  }

  private fallback(): void {
    this.game.showMenu();
    this.game.startChallenge();
  }

  private readonly onUnload = (e: BeforeUnloadEvent) => {
    if (this.offline || this.disposed) return;
    e.preventDefault();
    e.returnValue = '';
  };

  /** scheda chiusa o ricaricata: l'avversario lo sa subito (bye) invece di aspettare il keep-alive */
  private readonly onPageHide = () => this.dispose();

  // ------------------------------------------------------------------ messaggi

  private onMessage(m: NetMessage): void {
    switch (m.t) {
      case 'hello':
        if (m.ver !== PROTOCOL_VERSION) {
          this.onLost('Il gioco dell\'avversario è di un\'altra versione: aggiornate entrambi la pagina.');
          return;
        }
        this.names[1 - this.me] = String(m.name || 'Avversario').trim().slice(0, 16) || 'Avversario';
        this.game.ui.toast(`Collegato con ${this.peerName}!`, 'good');
        if (this.role === 'host' && this.phase === 'lobby') this.startRound(this.mode, 0);
        break;
      case 'config':
        if (this.role === 'guest' && m.mode in MODES && (m.defender === 0 || m.defender === 1) && (this.phase === 'lobby' || this.phase === 'result')) {
          // stesso ambiente per entrambi: il tema lo sceglie l'host (campo facoltativo)
          if (typeof m.theme === 'string' && m.theme in THEMES) this.game.renderer.setTheme(m.theme);
          this.startRound(m.mode, m.defender);
        }
        break;
      case 'build-progress':
        if (this.phase === 'wait-build' && isNum(m.blocks) && isNum(m.spent) && isNum(m.left)) this.wait?.progress(m);
        break;
      case 'build-done':
        if (this.phase === 'wait-build') {
          const bp = fromWire(m.bp);
          if (bp) this.ready(bp);
          else this.onLost('La fortezza ricevuta non è valida.');
        }
        break;
      case 'snap':
      case 'event':
        if (this.phase === 'spectate') this.spectator?.feed(m);
        break;
      case 'result':
        if (this.phase === 'spectate' || this.phase === 'defend') this.onRemoteResult(m.report);
        break;
      case 'rematch':
        this.rematch.peer = true;
        if (this.phase === 'result') {
          this.game.ui.toast(`${this.peerName} vuole la rivincita!`, 'good');
          this.showResult();
          this.maybeRematch();
        }
        break;
      case 'bye':
        this.session?.close(false);
        this.onLost(`${this.peerName} ha lasciato il duello.`);
        break;
    }
  }

  private onLost(reason: string): void {
    if (this.disposed || this.offline) return;
    this.session?.close(false);
    this.session = null;
    this.stopTimers();
    // in lobby si può ancora riprovare con un nuovo invito
    if (this.phase === 'lobby') return this.lobbyFail(`${reason} Puoi riprovare o usare la sfida via link.`);
    this.offline = true;
    window.removeEventListener('beforeunload', this.onUnload);
    const ui = this.game.ui;
    const menu: Action = { label: 'Menu', ico: ICONS.back, primary: true, onClick: () => this.game.showMenu() };
    switch (this.phase) {
      case 'defend':
        ui.toast('Connessione persa: finita la costruzione potrai mandare la fortezza come sfida via link.', 'warn');
        break;
      case 'ready':
      case 'attack':
        ui.toast('Connessione persa: continua pure, alla fine potrai mandare il referto via link.', 'warn');
        break;
      case 'wait-build':
        this.game.setScene(new BackdropScene(this.game));
        ui.screen(noticeScreen({ tone: 'atk', badge: 'DUELLO INTERROTTO', title: 'Connessione persa',
          text: `${reason} Chiedi a ${this.peerName} di mandarti la sua fortezza come sfida via link.`, actions: [menu] }));
        break;
      case 'spectate':
        ui.hud(null);
        this.game.setScene(new BackdropScene(this.game, this.bp ?? undefined));
        ui.screen(noticeScreen({ tone: 'def', badge: 'DIRETTA INTERROTTA', title: 'Connessione persa',
          text: `${reason} ${this.peerName} può comunque finire l'assedio e mandarti il referto via link.`, actions: [menu] }));
        break;
      case 'result':
        ui.toast(reason, 'warn');
        this.showResult();
        break;
    }
  }

  // ------------------------------------------------------------------ round

  private startRound(mode: ModeId, defender: 0 | 1): void {
    this.phase = defender === this.me ? 'defend' : 'wait-build';
    this.mode = mode;
    this.defender = defender;
    this.rematch = { me: false, peer: false };
    this.bp = null;
    this.report = null;
    this.spectator = null;
    this.invite = this.join = null;
    if (this.role === 'host') this.session?.send({ t: 'config', mode, defender, theme: this.game.renderer.theme.id });
    const m = MODES[mode];
    if (this.phase === 'defend') {
      this.game.handoff({
        role: 'def',
        title: 'Tu difendi!',
        text: `${this.peerName} attaccherà in diretta e tu guarderai l'assedio. Modalità ${m.name}: ${m.buildTime} secondi per costruire e nascondere Mimika.`,
        cta: 'Inizia a costruire',
        onGo: () => {
          this.sendProgress({ blocks: 0, spent: 0, left: m.buildTime });
          this.game.build(mode, this.myName, (bp) => this.buildDone(bp), (p) => this.sendProgress(p));
        },
      });
    } else {
      this.game.ui.hud(null);
      this.game.setScene(new BackdropScene(this.game, emptyBlueprint(mode, ''), true));
      this.wait = waitBuildScreen({ defender: this.peerName, mode, onQuit: () => this.game.confirmQuit() });
      this.wait.status('ok', `Collegati con ${this.peerName}`);
      this.game.ui.screen(this.wait.el);
    }
  }

  /** Avanzamento della costruzione, con limite di frequenza (l'ultimo valore parte sempre). */
  private sendProgress(p: Progress): void {
    this.pendingProgress = p;
    if (this.progressTimer !== undefined) return;
    this.progressTimer = setTimeout(() => {
      this.progressTimer = undefined;
      if (this.pendingProgress && this.phase === 'defend') this.session?.send({ t: 'build-progress', ...this.pendingProgress });
    }, PROGRESS_THROTTLE);
  }

  private buildDone(bp: Blueprint): void {
    if (this.offline) {
      this.game.ui.toast('La diretta è chiusa: manda la fortezza come sfida via link.', 'warn');
      void this.game.shareChallenge(bp);
      return;
    }
    const wire = toWire(bp);
    clearTimeout(this.progressTimer);
    this.progressTimer = undefined;
    this.session?.send({ t: 'build-done', bp: wire });
    // lo spettatore usa la stessa decodifica dell'attaccante: stessi corpi, stesso ordine (nid)
    const view = fromWire(wire) ?? bp;
    this.phase = 'spectate';
    this.bp = view;
    this.spectator = new SpectatorScene(this.game, view, {
      attacker: this.peerName,
      defender: this.myName,
      rtt: () => this.session?.rtt ?? null,
      onQuit: () => this.game.confirmQuit(),
    });
    this.game.ui.screen(null);
    this.game.setScene(this.spectator);
  }

  private ready(bp: Blueprint): void {
    this.phase = 'ready';
    this.bp = bp;
    this.wait = null;
    const m = MODES[bp.mode];
    this.game.handoff({
      role: 'atk',
      title: `La fortezza di ${this.peerName} è pronta!`,
      text: `Modalità ${m.name}: hai ${m.attackTime} secondi per scovare e colpire Mimika. ${this.peerName} ti guarda in diretta…`,
      cta: "All'attacco!",
      bp,
      onGo: () => {
        this.phase = 'attack';
        const live = this.offline ? undefined : new LiveBroadcaster((msg) => this.session?.send(msg));
        this.game.attack(bp, this.myName, this.peerName, (res) => this.attackDone(bp, res), live);
      },
    });
  }

  private attackDone(bp: Blueprint, res: AttackResult): void {
    if (this.offline) return void this.game.challengeResult(bp, res);
    const report: MatchReport = {
      v: 1, w: res.winner === 'attacker' ? 'atk' : 'def', an: this.myName, dn: this.peerName, m: bp.mode,
      s: res.shots, k: res.broken, t: res.seconds, c: res.cause,
    };
    this.session?.send({ t: 'result', report });
    this.finishRound(report);
  }

  private onRemoteResult(raw: MatchReport): void {
    if (!raw || (raw.w !== 'atk' && raw.w !== 'def')) return;
    // i nomi e la modalità li conosciamo già: dall'esterno si accettano solo esito e statistiche
    this.finishRound({
      v: 1, w: raw.w, an: this.peerName, dn: this.myName, m: this.mode,
      s: isNum(raw.s) ? raw.s : 0, k: isNum(raw.k) ? raw.k : 0, t: isNum(raw.t) ? raw.t : 0,
      c: String(raw.c ?? '').slice(0, 60),
    });
  }

  private finishRound(report: MatchReport): void {
    this.phase = 'result';
    this.report = report;
    this.score[report.w === 'atk' ? 1 - this.defender : this.defender]++;
    this.game.ui.hud(null);
    this.game.setScene(new BackdropScene(this.game, this.bp ?? undefined));
    this.showResult();
    this.maybeRematch();
  }

  private showResult(): void {
    const r = this.report;
    if (!r || this.phase !== 'result') return;
    const atkWon = r.w === 'atk';
    const nextDefender = this.names[1 - this.defender];
    let rematch: Action;
    if (this.offline) rematch = { label: 'Rivincita non disponibile', sub: 'Avversario disconnesso', ico: ICONS.users, disabled: true, onClick: () => {} };
    else if (this.rematch.me) rematch = { label: `In attesa di ${this.peerName}…`, sub: `Poi difende ${nextDefender}`, ico: ICONS.users, disabled: true, onClick: () => {} };
    else if (this.rematch.peer) rematch = { label: `${this.peerName} vuole la rivincita!`, sub: `Accetta: ora difende ${nextDefender}`, ico: ICONS.users, primary: true, onClick: () => this.askRematch() };
    else rematch = { label: 'Rivincita a ruoli invertiti', sub: `Ora difende ${nextDefender}`, ico: ICONS.users, primary: true, onClick: () => this.askRematch() };
    this.game.ui.screen(resultScreen({
      winnerName: atkWon ? r.an : r.dn,
      winnerRole: r.w,
      cause: r.c,
      shots: r.s,
      broken: r.k,
      seconds: r.t,
      score: { names: this.names, values: this.score },
      actions: [rematch, { label: 'Esci dal duello', ico: ICONS.back, onClick: () => this.game.showMenu() }],
    }));
  }

  private askRematch(): void {
    if (this.offline || this.rematch.me) return;
    this.rematch.me = true;
    this.game.sfx.click();
    this.session?.send({ t: 'rematch' });
    this.showResult();
    this.maybeRematch();
  }

  /** Quando entrambi vogliono la rivincita, l'host inverte i ruoli e manda la nuova config. */
  private maybeRematch(): void {
    if (this.role === 'host' && this.rematch.me && this.rematch.peer && !this.offline) this.startRound(this.mode, this.defender === 0 ? 1 : 0);
  }
}
