import { MATERIALS, type MaterialId } from '../config/materials';
import { WORLD } from '../config/world';
import { TAU, rand } from '../core/math';
import { QUALITY } from './quality';

type Kind = 'chunk' | 'dust' | 'spark' | 'ring' | 'shard' | 'glow' | 'text' | 'streak' | 'firefly';

interface P {
  k: Kind;
  x: number;
  y: number;
  vx: number;
  vy: number;
  g: number;
  drag: number;
  life: number;
  max: number;
  size: number;
  rot: number;
  vr: number;
  color: string;
  text?: string;
}

const MAX = 900;

/** Sistema particellare unico, in coordinate mondo. */
export class Particles {
  private list: P[] = [];

  clear(): void {
    this.list.length = 0;
  }

  add(p: Partial<P> & Pick<P, 'k' | 'x' | 'y'>): void {
    // qualità bassa: metà delle particelle "di massa" (schegge, polvere, scintille), mai quelle che informano
    if (QUALITY.particles < 1 && (p.k === 'chunk' || p.k === 'shard' || p.k === 'dust' || p.k === 'spark' || p.k === 'streak') && Math.random() > QUALITY.particles) return;
    if (this.list.length >= MAX * QUALITY.particles) this.list.shift();
    const life = p.life ?? 800;
    this.list.push({
      vx: 0, vy: 0, g: 0, drag: 0.98, size: 4, rot: 0, vr: 0, color: '#fff', max: life, ...p, life,
    });
  }

  debris(x: number, y: number, mat: MaterialId, n = 14): void {
    const m = MATERIALS[mat];
    const colors = [m.color, m.light, m.dark];
    for (let i = 0; i < n; i++) {
      const a = rand(0, TAU), s = rand(1.5, 7);
      this.add({
        k: mat === 'glass' ? 'shard' : 'chunk', x: x + rand(-14, 14), y: y + rand(-14, 14),
        vx: Math.cos(a) * s, vy: Math.sin(a) * s - 3, g: 0.32, drag: 0.99, life: rand(700, 1500),
        size: rand(4, 10), rot: rand(0, TAU), vr: rand(-0.3, 0.3), color: colors[i % 3],
      });
    }
    this.dust(x, y, 6, mat === 'moss' ? 'rgba(190,240,150,0.5)' : 'rgba(230,210,230,0.45)');
    if (mat === 'glass') this.sparks(x, y, 8, '#e9fbff');
  }

  dust(x: number, y: number, n: number, color = 'rgba(230,210,230,0.45)'): void {
    for (let i = 0; i < n; i++) {
      this.add({
        k: 'dust', x: x + rand(-10, 10), y: y + rand(-6, 6), vx: rand(-1.2, 1.2), vy: rand(-1.4, -0.2),
        drag: 0.96, life: rand(600, 1300), size: rand(8, 20), color,
      });
    }
  }

  sparks(x: number, y: number, n: number, color = '#ffe28a'): void {
    for (let i = 0; i < n; i++) {
      const a = rand(0, TAU), s = rand(3, 10);
      this.add({ k: 'spark', x, y, vx: Math.cos(a) * s, vy: Math.sin(a) * s, g: 0.2, drag: 0.94, life: rand(250, 600), size: rand(1.5, 3), color });
    }
  }

  explosion(x: number, y: number, r: number): void {
    this.add({ k: 'glow', x, y, life: 420, size: r * 1.3, color: '255,200,120' });
    this.add({ k: 'ring', x, y, life: 520, size: r, color: '#ffe7b0' });
    this.add({ k: 'ring', x, y, life: 750, size: r * 1.4, color: 'rgba(255,122,107,0.8)' });
    this.sparks(x, y, 30, '#ffd27a');
    for (let i = 0; i < 18; i++) {
      const a = rand(0, TAU), s = rand(1, 4);
      this.add({
        k: 'dust', x: x + Math.cos(a) * 20, y: y + Math.sin(a) * 20, vx: Math.cos(a) * s, vy: Math.sin(a) * s - 1,
        drag: 0.93, life: rand(800, 1600), size: rand(18, 38), color: 'rgba(60,40,70,0.55)',
      });
    }
  }

  ring(x: number, y: number, size: number, color: string, life = 600): void {
    this.add({ k: 'ring', x, y, life, size, color });
  }

  text(x: number, y: number, text: string, color = '#fff'): void {
    this.add({ k: 'text', x, y, vy: -1.1, drag: 0.97, life: 1400, size: 34, color, text });
  }

  streak(x: number, y: number): void {
    this.add({ k: 'streak', x, y, vx: rand(18, 30), vy: rand(-1, 1), drag: 1, life: rand(400, 800), size: rand(40, 120), color: 'rgba(255,240,255,0.35)' });
  }

  firefly(x: number, y: number): void {
    this.add({ k: 'firefly', x, y, vx: rand(-0.3, 0.3), vy: rand(-0.4, -0.1), drag: 1, life: rand(3000, 6000), size: rand(1.5, 3), color: '255,230,150', rot: rand(0, TAU) });
  }

  update(dt: number): void {
    const s = dt / 16.67;
    const list = this.list;
    for (let i = list.length - 1; i >= 0; i--) {
      const p = list[i];
      p.life -= dt;
      if (p.life <= 0) {
        list[i] = list[list.length - 1];
        list.pop();
        continue;
      }
      p.vx *= Math.pow(p.drag, s);
      p.vy = p.vy * Math.pow(p.drag, s) + p.g * s;
      p.x += p.vx * s;
      p.y += p.vy * s;
      p.rot += p.vr * s;
      if (p.k === 'firefly') p.vx += Math.sin(p.life * 0.003 + p.rot) * 0.02;
      if ((p.k === 'chunk' || p.k === 'shard') && p.y > WORLD.GROUND_Y - 3) {
        p.y = WORLD.GROUND_Y - 3;
        p.vy *= -0.35;
        p.vx *= 0.6;
        p.vr *= 0.5;
      }
    }
  }

  draw(g: CanvasRenderingContext2D): void {
    for (const p of this.list) {
      const t = p.life / p.max;
      switch (p.k) {
        case 'chunk':
        case 'shard':
          g.save();
          g.globalAlpha = Math.min(1, t * 2);
          g.translate(p.x, p.y);
          g.rotate(p.rot);
          g.fillStyle = p.color;
          g.strokeStyle = 'rgba(27,18,51,0.8)';
          g.lineWidth = 1.2;
          g.beginPath();
          if (p.k === 'shard') {
            g.moveTo(-p.size / 2, p.size / 3);
            g.lineTo(0, -p.size / 2);
            g.lineTo(p.size / 2, p.size / 2);
          } else {
            g.rect(-p.size / 2, -p.size / 2, p.size, p.size * 0.7);
          }
          g.closePath();
          g.fill();
          g.stroke();
          g.restore();
          break;
        case 'dust':
          g.globalAlpha = t * 0.9;
          g.fillStyle = p.color;
          g.beginPath();
          g.arc(p.x, p.y, p.size * (1.6 - t * 0.6), 0, TAU);
          g.fill();
          break;
        case 'spark':
          g.globalAlpha = t;
          g.strokeStyle = p.color;
          g.lineWidth = p.size;
          g.beginPath();
          g.moveTo(p.x, p.y);
          g.lineTo(p.x - p.vx * 2, p.y - p.vy * 2);
          g.stroke();
          break;
        case 'ring':
          g.globalAlpha = t;
          g.strokeStyle = p.color;
          g.lineWidth = 2 + 8 * t;
          g.beginPath();
          g.arc(p.x, p.y, p.size * (1 - t * t) + 4, 0, TAU);
          g.stroke();
          break;
        case 'glow': {
          const r = p.size * (1.2 - t * 0.4);
          const gr = g.createRadialGradient(p.x, p.y, 0, p.x, p.y, r);
          gr.addColorStop(0, `rgba(${p.color},${0.9 * t})`);
          gr.addColorStop(1, `rgba(${p.color},0)`);
          g.globalAlpha = 1;
          g.fillStyle = gr;
          g.fillRect(p.x - r, p.y - r, r * 2, r * 2);
          break;
        }
        case 'text':
          g.globalAlpha = Math.min(1, t * 2.5);
          g.font = `700 ${p.size}px Fredoka, system-ui, sans-serif`;
          g.textAlign = 'center';
          g.lineWidth = 6;
          g.strokeStyle = 'rgba(27,18,51,0.9)';
          g.strokeText(p.text ?? '', p.x, p.y);
          g.fillStyle = p.color;
          g.fillText(p.text ?? '', p.x, p.y);
          break;
        case 'streak':
          g.globalAlpha = Math.sin(t * Math.PI);
          g.strokeStyle = p.color;
          g.lineWidth = 2;
          g.beginPath();
          g.moveTo(p.x, p.y);
          g.lineTo(p.x - p.size, p.y);
          g.stroke();
          break;
        case 'firefly': {
          const a = Math.sin(t * Math.PI) * (0.5 + 0.5 * Math.sin(p.life * 0.01));
          g.globalAlpha = 1;
          g.fillStyle = `rgba(${p.color},${(a * 0.25).toFixed(3)})`;
          g.beginPath();
          g.arc(p.x, p.y, p.size * 4, 0, TAU);
          g.fill();
          g.fillStyle = `rgba(${p.color},${a.toFixed(3)})`;
          g.beginPath();
          g.arc(p.x, p.y, p.size, 0, TAU);
          g.fill();
          break;
        }
      }
    }
    g.globalAlpha = 1;
  }
}
