/**
 * Materiali da costruzione. Bilanciamento: vedi docs/01-GAME-DESIGN.md (tabella materiali).
 * density/friction/restitution sono parametri Matter.js; hp = punti struttura;
 * blast/bolt/shock = moltiplicatori di danno da esplosione/fulmine/urti;
 * termite = velocità con cui le termiti lo corrodono (0 = immune).
 */
export type MaterialId = 'wood' | 'stone' | 'glass' | 'metal' | 'moss' | 'silk';

export interface MaterialDef {
  id: MaterialId;
  name: string;
  blurb: string;
  density: number;
  friction: number;
  restitution: number;
  hp: number;
  cost: number;
  blast: number;
  bolt: number;
  shock: number;
  termite: number;
  conductive: boolean;
  /** riflette il fulmine verso il Cacciatore invece di riceverlo */
  mirror: boolean;
  drillProof: boolean;
  color: string;
  light: string;
  dark: string;
}

