import Matter from 'matter-js';
import { MATERIALS, type MaterialId } from '../config/materials';
import { TUNING, type WeaponId } from '../config/weapons';
import { WORLD, cellRect, type Cell } from '../config/world';
import { hashString, mulberry32 } from '../core/math';
import type { Blueprint } from './blueprint';

const { Engine, Bodies, Body, Composite, Events, Query, Sleeping } = Matter;

export const STEP_MS = 1000 / 60;
export const CREATURE_R = 15;
/** testa del Cacciatore: dove arriva il fulmine riflesso dalla seta */
export const HUNTER_HEAD: Vec = { x: WORLD.LAUNCH_X - 95, y: WORLD.GROUND_Y - 120 };
/** la piena parte da qui e arriva in fondo al campo */
const FLOOD_X0 = 300;
const FLOOD_X1 = 2050;

export type EntityKind = 'block' | 'core' | 'decoy' | 'projectile';

export interface Vec {
  x: number;
  y: number;
}

export interface Entity {
  id: number;
  /** id di rete: progressivo nell'ordine di creazione, uguale su tutti i dispositivi (snapshot del duello live) */
  nid: number;
  kind: EntityKind;
  body: Matter.Body;
  mat?: MaterialId;
  weapon?: WeaponId;
  hp: number;
  maxHp: number;
  w: number;
  h: number;
  seed: number;
  born: number;
  /** trivella: blocchi ancora perforabili */
  pierce: number;
  /** ms trascorsi da fermo (per rimuovere i massi esausti) */
  restMs: number;
  /** 0..1, lampo bianco quando viene colpito */
  flash: number;
  /** trivella: velocità costante */
  vel?: Vec;
  /** termiti: ms di infestazione rimasti (0 = sano) */
  infest?: number;
  /** termiti: blocchi che la colonia può ancora raggiungere da qui, e ms al prossimo salto */
  spread?: number;
  hop?: number;
  /** ferro bagnato dalla piena: conduce più lontano il prossimo fulmine */
  wet?: boolean;
  dead?: boolean;
}

/** Eventi verso la scena (effetti, suoni, esito). Il World non sa nulla di grafica. */
export interface WorldListener {
  impact?(x: number, y: number, strength: number, mat?: MaterialId): void;
  broken?(e: Entity): void;
  coreHit?(cause: string, x: number, y: number): void;
  decoyPopped?(e: Entity): void;
  explosion?(x: number, y: number, r: number): void;
  bolt?(path: Vec[], branches: Vec[][]): void;
  spark?(x: number, y: number): void;
  projectileGone?(e: Entity): void;
  /** il vaso di termiti si è rotto in (x, y); target = blocco infestato (null = nessun blocco commestibile) */
  termite?(x: number, y: number, target: Entity | null): void;
  /** la seta ha rimandato il fulmine verso il Cacciatore */
  reflect?(x: number, y: number): void;
  /** fine della piena: blocchi di ferro bagnati */
  wet?(blocks: Entity[]): void;
}

/**
 * Simulazione fisica della partita, creata da un Blueprint.
 * Passo fisso a 60 Hz (accumulatore): stesso comportamento a 30, 60 o 120 fps.
 * Deterministica: stessa fortezza + stesse azioni agli stessi passi = stesso risultato
 * (il caso che tocca la fisica viene da un PRNG interno, mai da Math.random).
 */
export class World {
  readonly engine: Matter.Engine;
  readonly entities = new Map<number, Entity>();
  readonly core: Entity;
  /** ms simulati */
  time = 0;
  /** passi di simulazione eseguiti (orologio dei replay) */
  steps = 0;
  coreHit = false;
  broken = 0;
  /** ms iniziali di assestamento: niente danni da contatto tra blocchi */
  readonly grace = 1400;
  windMs = 0;
  readonly windTotal: number = TUNING.windMs;
  floodMs = 0;
  readonly floodTotal: number = TUNING.floodMs;
  /** ms in cui la fionda è inutilizzabile (fulmine riflesso dalla seta) */
  jamMs = 0;
  /** chiamato prima di ogni passo con l'indice del passo: lì replay e attaccante automatico agiscono */
  onBeforeStep: ((step: number) => void) | null = null;
  private acc = 0;
  private nextNid = 1;
  private readonly rng = mulberry32(0x6d696b61);
  private readonly wetted = new Set<Entity>();

  constructor(bp: Blueprint, private listener: WorldListener = {}) {
    this.engine = Engine.create({ enableSleeping: true, positionIterations: 10, velocityIterations: 8 });
    const ground = Bodies.rectangle(WORLD.W / 2, WORLD.GROUND_Y + 150, 8000, 300, {
      isStatic: true, friction: 1, label: 'ground',
    });
    Composite.add(this.engine.world, ground);

    bp.blocks.forEach((b, i) => {
      const r = cellRect(b.col, b.row, b.w, b.h);
      const m = MATERIALS[b.mat];
      const body = Bodies.rectangle(r.cx, r.cy, r.w - 0.5, r.h - 0.5, {
        density: m.density, friction: m.friction, frictionStatic: 1, restitution: m.restitution,
        chamfer: { radius: 2 }, label: 'block',
      });
      this.add({ kind: 'block', body, mat: b.mat, hp: m.hp, maxHp: m.hp, w: r.w, h: r.h, seed: i * 7919 + 13 });
    });

    this.core = this.addCreature('core', bp.core, 1);
    bp.decoys.forEach((d, i) => this.addCreature('decoy', d, 100 + i));

    Events.on(this.engine, 'collisionStart', (e) => this.onCollisions(e.pairs));
    Events.on(this.engine, 'beforeUpdate', () => this.beforeUpdate());
  }

  // ---------------------------------------------------------------- simulazione

  /** Avanza la simulazione. timeScale < 1 = slow motion fluido. */
  step(dtMs: number, timeScale = 1): void {
    this.engine.timing.timeScale = timeScale;
    this.acc += Math.min(dtMs, 100);
    while (this.acc >= STEP_MS) {
      this.onBeforeStep?.(this.steps);
      Engine.update(this.engine, STEP_MS);
      this.steps++;
      this.time += STEP_MS * timeScale;
      this.acc -= STEP_MS;
      this.afterStep(timeScale);
    }
  }

  get projectiles(): Entity[] {
    return [...this.entities.values()].filter((e) => e.kind === 'projectile');
  }

  get decoys(): Entity[] {
    return [...this.entities.values()].filter((e) => e.kind === 'decoy');
  }

  /** Accelerazione di gravità per passo (px/step²), usata dall'anteprima di traiettoria. */
  get gravityPerStep(): number {
    const g = this.engine.gravity;
    return g.y * g.scale * STEP_MS * STEP_MS;
  }

  /** Tutto fermo: nessun corpo in moto, niente vento o piena in corso, nessuna termite al lavoro. */
  isSettled(): boolean {
    if (this.windMs > 0 || this.floodMs > 0) return false;
    for (const e of this.entities.values()) {
      if (e.infest) return false;
      const b = e.body;
      if (!b.isSleeping && b.speed > 0.35) return false;
    }
    return true;
  }

  /** Impronta dello stato (esito + corpi arrotondati al pixel): la confronta il replay dei referti. */
  digest(outcome: string): string {
    let s = `${outcome}|${this.broken}|${this.steps}`;
    for (const e of this.entities.values()) s += `|${e.nid}:${Math.round(e.body.position.x)}:${Math.round(e.body.position.y)}`;
    return hashString(s);
  }

  // ---------------------------------------------------------------- azioni dell'attaccante

  launch(weapon: WeaponId, vx: number, vy: number): Entity {
    const x = WORLD.LAUNCH_X;
    const y = WORLD.LAUNCH_Y;
    let body: Matter.Body;
    if (weapon === 'drill') {
      body = Bodies.rectangle(x, y, 46, 16, { isSensor: true, frictionAir: 0, density: 0.004, label: 'drill' });
      Body.setAngle(body, Math.atan2(vy, vx));
    } else if (weapon === 'bomb') {
      body = Bodies.circle(x, y, 18, { density: 0.007, frictionAir: 0, restitution: 0.3, label: 'bomb' });
    } else if (weapon === 'termite') {
      body = Bodies.circle(x, y, 15, { density: 0.003, frictionAir: 0, restitution: 0.1, label: 'termite' });
    } else {
      body = Bodies.circle(x, y, 22, { density: TUNING.boulderDensity, frictionAir: 0, restitution: 0.15, friction: 0.6, label: 'boulder' });
    }
    Body.setVelocity(body, { x: vx, y: vy });
    return this.add({ kind: 'projectile', body, weapon, pierce: TUNING.drillPierce, vel: { x: vx, y: vy }, w: 44, h: 44, seed: this.time | 0 });
  }

  startWind(): void {
    this.windMs = this.windTotal;
    this.wakeAll();
  }

  /** Onda d'acqua dal suolo, da sinistra verso destra. */
  startFlood(): void {
    this.floodMs = this.floodTotal;
    this.wetted.clear();
    this.wakeAll();
  }

  /** Fronte della piena in corso (x) e altezza attuale dell'onda, o null. Usato anche dal disegno. */
  floodWave(): { x: number; h: number } | null {
    return floodShape(this.floodMs, this.floodTotal);
  }

  /**
   * Fulmine verticale sulla coordinata x. Il ferro propaga la scarica ai ferri a contatto
   * (bagnato: anche attraverso piccole fessure); la seta lo rimanda verso il Cacciatore.
   */
  lightning(x: number): void {
    const targets = [...this.entities.values()].filter((e) => e.kind !== 'projectile');
    const bodies = targets.map((e) => e.body);
    let hit: Entity | null = null;
    let hitY: number = WORLD.GROUND_Y;
    for (let y = -100; y < WORLD.GROUND_Y; y += 5) {
      const found = Query.point(bodies, { x, y });
      if (found.length) {
        hit = this.entities.get(found[0].id) ?? null;
        hitY = y;
        break;
      }
    }
    const path = zigzag({ x: x + (Math.random() - 0.5) * 160, y: -260 }, { x, y: hitY }, 14, 26);
    const branches: Vec[][] = [];
    if (hit) {
      const m = hit.mat ? MATERIALS[hit.mat] : null;
      if (hit.kind === 'core' || hit.kind === 'decoy') this.creatureHit(hit, 'fulmine');
      else if (m?.mirror) {
        branches.push(zigzag({ x, y: hitY }, HUNTER_HEAD, 16, 30));
        this.damage(hit, TUNING.boltDamage * m.bolt);
        this.jamMs = TUNING.reflectJamMs;
        this.listener.reflect?.(x, hitY);
      } else if (m?.conductive) {
        const net = this.metalNetwork(hit);
        for (const n of net) {
          if (n !== hit) branches.push(zigzag(hit.body.position, n.body.position, 4, 8));
          this.damage(n, TUNING.boltDamage * MATERIALS.metal.bolt * (n.wet ? TUNING.wetBolt : 1));
        }
        for (const c of [this.core, ...this.decoys]) {
          if (c.dead) continue;
          const touching = net.find((n) => !n.dead && boundsTouch(n.body, c.body, n.wet ? TUNING.wetArc : 4));
          if (touching) {
            branches.push(zigzag(touching.body.position, c.body.position, 4, 6));
            this.creatureHit(c, touching.wet ? 'fulmine (il ferro bagnato conduce)' : 'fulmine (il ferro conduce)');
          }
        }
      } else if (m) {
        this.damage(hit, TUNING.boltDamage * m.bolt);
      }
    }
    // l'acqua evapora: vale solo per il primo fulmine dopo la piena
    for (const e of this.entities.values()) e.wet = false;
    this.listener.bolt?.(path, branches);
    this.wakeAll();
  }

  explode(x: number, y: number, radius: number, power = 1): void {
    this.listener.explosion?.(x, y, radius);
    for (const e of [...this.entities.values()]) {
      if (e.dead) continue;
      const b = e.body;
      const dx = b.position.x - x;
      const dy = b.position.y - y;
      const d = Math.hypot(dx, dy);
      if (d > radius) continue;
      const f = 1 - d / radius;
      const nx = dx / (d || 1);
      const ny = dy / (d || 1) - 0.35;
      if (e.kind === 'core' || e.kind === 'decoy') {
        if (d < 48 || (d < radius * 0.85 && this.lineClear({ x, y }, b.position))) this.creatureHit(e, 'esplosione');
        continue;
      }
      const blast = e.mat ? MATERIALS[e.mat].blast : 1;
      const dv = Math.min(20, (f * power * 34 * blast) / b.mass);
      Sleeping.set(b, false);
      Body.setVelocity(b, { x: b.velocity.x + nx * dv, y: b.velocity.y + ny * dv });
      Body.setAngularVelocity(b, b.angularVelocity + (this.rng() - 0.5) * 0.2 * f);
      if (e.kind === 'block') this.damage(e, TUNING.bombDamage * f * blast * power);
    }
    this.wakeAll();
  }

  // ---------------------------------------------------------------- interni

  private add(partial: Pick<Entity, 'kind' | 'body'> & Partial<Entity>): Entity {
    const e: Entity = {
      id: partial.body.id, nid: this.nextNid++, hp: 1, maxHp: 1, w: 0, h: 0, seed: 0, born: this.time, pierce: 0, restMs: 0, flash: 0,
      ...partial,
    };
    this.entities.set(e.id, e);
    Composite.add(this.engine.world, e.body);
    return e;
  }

  private addCreature(kind: 'core' | 'decoy', cell: Cell, seed: number): Entity {
    const r = cellRect(cell.col, cell.row);
    const body = Bodies.circle(r.cx, r.y + r.h - CREATURE_R - 0.5, CREATURE_R, {
      density: 0.002, friction: 0.9, frictionAir: 0.02, restitution: 0.15, label: kind,
    });
    return this.add({ kind, body, w: CREATURE_R * 2, h: CREATURE_R * 2, seed });
  }

  remove(e: Entity): void {
    if (e.dead) return;
    e.dead = true;
    Composite.remove(this.engine.world, e.body);
    this.entities.delete(e.id);
    this.wakeAll();
  }

  private wakeAll(): void {
    for (const e of this.entities.values()) if (!e.body.isStatic) Sleeping.set(e.body, false);
  }

  private damage(e: Entity, amount: number, flash = true): void {
    if (e.dead || amount <= 0) return;
    e.hp -= amount;
    if (flash) e.flash = 1;
    if (e.hp <= 0) {
      this.broken++;
      this.listener.broken?.(e);
      this.remove(e);
    }
  }

  private creatureHit(e: Entity, cause: string): void {
    if (e.dead) return;
    if (e.kind === 'decoy') {
      this.listener.decoyPopped?.(e);
      this.remove(e);
      return;
    }
    if (e.kind === 'core' && !this.coreHit) {
      this.coreHit = true;
      e.flash = 1;
      this.listener.coreHit?.(cause, e.body.position.x, e.body.position.y);
    }
  }

  private beforeUpdate(): void {
    for (const e of this.entities.values()) {
      if (e.weapon === 'drill' && e.vel) Body.setVelocity(e.body, e.vel);
    }
    if (this.windMs > 0) {
      const t = 1 - this.windMs / this.windTotal;
      const env = Math.pow(Math.sin(Math.PI * t), 0.7);
      for (const e of this.entities.values()) {
        const b = e.body;
        if (b.isStatic || e.weapon === 'drill') continue;
        const gust = 0.8 + 0.4 * Math.sin(this.time * 0.02 + e.seed);
        const f = b.area * TUNING.windForce * env * gust;
        Body.applyForce(b, b.position, { x: f, y: -f * 0.12 });
      }
    }
    const wave = this.floodWave();
    if (wave) {
      const top = WORLD.GROUND_Y - wave.h;
      for (const e of this.entities.values()) {
        const b = e.body;
        if (b.isStatic || e.weapon === 'drill') continue;
        if (b.position.x > wave.x + 30 || b.position.x < wave.x - 420) continue;
        const sub = (b.bounds.max.y - top) / Math.max(1, b.bounds.max.y - b.bounds.min.y);
        if (sub <= 0) continue;
        const f = b.area * Math.min(1, sub) * TUNING.floodForce;
        Body.applyForce(b, b.position, { x: f, y: -f * 0.35 });
        if (e.kind === 'block' && e.mat === 'metal' && !e.wet) {
          e.wet = true;
          this.wetted.add(e);
        }
      }
    }
  }

  private afterStep(timeScale: number): void {
    const dt = STEP_MS * timeScale;
    if (this.windMs > 0) this.windMs -= dt;
    if (this.jamMs > 0) this.jamMs -= dt;
    if (this.floodMs > 0 && (this.floodMs -= dt) <= 0) {
      this.listener.wet?.([...this.wetted].filter((e) => !e.dead && e.wet));
      this.wetted.clear();
    }
    for (const e of [...this.entities.values()]) {
      if (e.dead) continue;
      if (e.flash > 0) e.flash = Math.max(0, e.flash - dt / 250);
      const p = e.body.position;
      if (p.y > WORLD.KILL_Y || p.x < -800 || p.x > WORLD.W + 1200) {
        if (e.kind === 'core') this.creatureHit(e, 'caduta nel vuoto');
        this.remove(e);
        continue;
      }
      if (e.infest) this.corrode(e, dt);
      if (e.kind !== 'projectile') continue;
      const age = this.time - e.born;
      if (e.weapon === 'bomb' && age > TUNING.bombFuseMs) {
        this.remove(e);
        this.explode(p.x, p.y, TUNING.bombRadius);
      } else if ((e.weapon === 'drill' && age > 2600) || (e.weapon === 'termite' && age > 6000)) {
        this.listener.projectileGone?.(e);
        this.remove(e);
      } else if (e.weapon === 'boulder') {
        e.restMs = e.body.speed < 0.5 ? e.restMs + dt : 0;
        if (e.restMs > 1800 || age > 12000) {
          this.listener.projectileGone?.(e);
          this.remove(e);
        }
      }
    }
  }

  // ---------------------------------------------------------------- termiti

  /** Il vaso si rompe: le termiti cercano il legno o il muschio più vicino. */
  private releaseTermites(pos: Vec, other: Entity | undefined): void {
    const eats = (e: Entity) => e.kind === 'block' && !e.dead && !e.infest && !!e.mat && MATERIALS[e.mat].termite > 0;
    let target = other && eats(other) ? other : null;
    if (!target) {
      let best = 120;
      for (const e of this.entities.values()) {
        if (!eats(e)) continue;
        const d = Math.hypot(e.body.position.x - pos.x, e.body.position.y - pos.y) - Math.max(e.w, e.h) / 2;
        if (d < best) (best = d), (target = e);
      }
    }
    this.listener.termite?.(pos.x, pos.y, target);
    if (target) this.infest(target, TUNING.termiteBlocks - 1);
  }

  private infest(e: Entity, spread: number): void {
    e.infest = TUNING.termiteMs;
    e.spread = spread;
    e.hop = TUNING.termiteHopMs;
  }

  private corrode(e: Entity, dt: number): void {
    e.infest = Math.max(0, e.infest! - dt);
    this.damage(e, (TUNING.termiteDps * MATERIALS[e.mat!].termite * dt) / 1000, false);
    if (e.dead || ((e.hop! -= dt) <= 0 && e.spread! > 0)) this.spreadTermites(e);
  }

  /** La colonia passa al blocco commestibile a contatto più vicino (anche quando il blocco crolla). */
  private spreadTermites(from: Entity): void {
    from.hop = TUNING.termiteHopMs;
    if (!from.spread) return;
    let best: Entity | null = null;
    let bestD = Infinity;
    for (const e of this.entities.values()) {
      if (e === from || e.kind !== 'block' || e.infest || !e.mat || MATERIALS[e.mat].termite <= 0) continue;
      if (!boundsTouch(from.body, e.body, 4)) continue;
      const d = Math.hypot(e.body.position.x - from.body.position.x, e.body.position.y - from.body.position.y);
      if (d < bestD) (bestD = d), (best = e);
    }
    if (!best) return;
    this.infest(best, from.spread - 1);
    from.spread = 0;
    this.listener.termite?.(best.body.position.x, best.body.position.y, best);
  }

  // ---------------------------------------------------------------- contatti

  private onCollisions(pairs: Matter.Pair[]): void {
    for (const pair of pairs) {
      const A = pair.bodyA.parent ?? pair.bodyA;
      const B = pair.bodyB.parent ?? pair.bodyB;
      const ea = this.entities.get(A.id);
      const eb = this.entities.get(B.id);
      if (!ea && !eb) continue;
      const n = pair.collision.normal;
      const speed = Math.abs((A.velocity.x - B.velocity.x) * n.x + (A.velocity.y - B.velocity.y) * n.y);
      const mA = A.isStatic ? Infinity : A.mass;
      const mB = B.isStatic ? Infinity : B.mass;
      const reduced = !isFinite(mA) ? mB : !isFinite(mB) ? mA : (mA * mB) / (mA + mB);
      const impulse = speed * reduced;
      if (ea) this.contact(ea, eb, B, impulse, speed);
      if (eb) this.contact(eb, ea, A, impulse, speed);
    }
  }

  private contact(self: Entity, other: Entity | undefined, otherBody: Matter.Body, impulse: number, speed: number): void {
    if (self.dead) return;
    const pos = self.body.position;
    switch (self.kind) {
      case 'projectile':
        this.projectileContact(self, other, otherBody);
        return;
      case 'block': {
        const fromProjectile = other?.kind === 'projectile';
        if (fromProjectile && (other!.weapon === 'drill' || other!.weapon === 'termite')) return;
        if (!fromProjectile && this.time < this.grace) return;
        if (impulse > 6) this.listener.impact?.(pos.x, pos.y, Math.min(1, impulse / 80), self.mat);
        const k = (fromProjectile ? TUNING.impactProjectile : TUNING.impactBlock) * (self.mat ? MATERIALS[self.mat].shock : 1);
        this.damage(self, Math.max(0, impulse - TUNING.impactFloor) * k);
        return;
      }
      case 'core':
      case 'decoy': {
        if (other?.kind === 'projectile') {
          if (other.weapon !== 'drill' && other.weapon !== 'termite' && speed > TUNING.creatureHitSpeed) this.creatureHit(self, other.weapon === 'bomb' ? 'bomba' : 'masso');
          return;
        }
        if (this.time < this.grace) return;
        const crush = otherBody.isStatic ? (speed > 9 ? Infinity : 0) : speed * otherBody.mass;
        if (crush > TUNING.crushThreshold) this.creatureHit(self, otherBody.isStatic ? 'caduta rovinosa' : 'schiacciata dai crolli');
      }
    }
  }

  private projectileContact(p: Entity, other: Entity | undefined, otherBody: Matter.Body): void {
    if (other?.kind === 'projectile') return;
    const pos = p.body.position;
    if (p.weapon === 'bomb' || p.weapon === 'termite') {
      if (this.time - p.born < 50) return;
      this.remove(p);
      if (p.weapon === 'bomb') this.explode(pos.x, pos.y, TUNING.bombRadius);
      else this.releaseTermites(pos, other);
      return;
    }
    if (p.weapon === 'drill') {
      if (!other) {
        if (otherBody.isStatic) {
          this.listener.spark?.(pos.x, pos.y);
          this.remove(p);
        }
        return;
      }
      if (other.kind === 'block') {
        if (other.mat && MATERIALS[other.mat].drillProof) {
          this.listener.spark?.(pos.x, pos.y);
          this.damage(other, 40);
          this.remove(p);
        } else {
          this.damage(other, 9999);
          if (--p.pierce <= 0) this.remove(p);
        }
      } else {
        this.creatureHit(other, 'trivella');
      }
    }
  }

  /** true se nessun blocco si frappone tra a e b (campionamento ogni 8 px). */
  private lineClear(a: Vec, b: Vec): boolean {
    const blocks = [...this.entities.values()].filter((e) => e.kind === 'block').map((e) => e.body);
    const d = Math.hypot(b.x - a.x, b.y - a.y);
    const steps = Math.ceil(d / 8);
    for (let i = 1; i < steps - 1; i++) {
      const t = i / steps;
      if (Query.point(blocks, { x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t }).length) return false;
    }
    return true;
  }

  /** Ferri a contatto con start (il ferro bagnato fa saltare la scarica anche attraverso le fessure). */
  private metalNetwork(start: Entity): Entity[] {
    const metals = [...this.entities.values()].filter((e) => e.mat === 'metal');
    const seen = new Set<Entity>([start]);
    const queue = [start];
    while (queue.length) {
      const cur = queue.pop()!;
      for (const m of metals) {
        if (!seen.has(m) && boundsTouch(cur.body, m.body, cur.wet || m.wet ? TUNING.wetArc : 3)) {
          seen.add(m);
          queue.push(m);
        }
      }
    }
    return [...seen];
  }
}

/** Forma della piena dopo (total − ms) ms: fronte che avanza, onda che cresce e poi cala. */
export function floodShape(ms: number, total: number): { x: number; h: number } | null {
  if (ms <= 0) return null;
  const k = 1 - ms / total;
  return { x: FLOOD_X0 + k * (FLOOD_X1 - FLOOD_X0), h: TUNING.floodHeight * Math.min(1, Math.sin(Math.PI * k) * 1.6) };
}

function boundsTouch(a: Matter.Body, b: Matter.Body, pad: number): boolean {
  return (
    a.bounds.min.x - pad <= b.bounds.max.x && a.bounds.max.x + pad >= b.bounds.min.x &&
    a.bounds.min.y - pad <= b.bounds.max.y && a.bounds.max.y + pad >= b.bounds.min.y
  );
}

function zigzag(a: Vec, b: Vec, segments: number, jitter: number): Vec[] {
  const pts: Vec[] = [{ x: a.x, y: a.y }];
  const len = Math.hypot(b.x - a.x, b.y - a.y) || 1;
  const nx = -(b.y - a.y) / len;
  const ny = (b.x - a.x) / len;
  for (let i = 1; i < segments; i++) {
    const t = i / segments;
    const off = (Math.random() - 0.5) * 2 * jitter;
    pts.push({ x: a.x + (b.x - a.x) * t + nx * off, y: a.y + (b.y - a.y) * t + ny * off });
  }
  pts.push({ x: b.x, y: b.y });
  return pts;
}
