import type { ModeId } from '../config/modes';
import { toWire, type Blueprint, type WireBlueprint } from '../game/blueprint';
import type { Shot } from '../game/siege';
import { packJson } from './codec';

/**
 * Link "senza server" (cap. 9.1 del documento P2P): i dati piccoli viaggiano nel fragment (#)
 * dell'URL, che il browser non invia mai al server. Chiavi del fragment:
 *   #c=  sfida asincrona (blueprint della fortezza)
 *   #r=  referto della partita (risultato da rimandare al difensore)
 *   #o=  offerta WebRTC   (Step 2: duello live)
 *   #a=  risposta WebRTC  (Step 2: duello live)
 *   #d=  sfida del giorno (data AAAAMMGG: la fortezza si rigenera dal seme, uguale per tutti)
 */
export type HashKey = 'c' | 'r' | 'o' | 'a' | 'd';

export interface MatchReport {
  v: 1;
  /** vincitore: atk = attaccante, def = difensore */
  w: 'atk' | 'def';
  /** nome attaccante / difensore */
  an: string;
  dn: string;
  m: ModeId;
  /** colpi usati, blocchi distrutti, secondi impiegati */
  s: number;
  k: number;
  t: number;
  /** causa (es. "bomba", "tempo scaduto") */
  c: string;
  /**
   * Replay (facoltativo, dalla v0.5): fortezza attaccata, tiri [passo, arma, a, b], passo finale e impronta del risultato.
   * Chi difende lo rigioca e confronta l'impronta (vedi game/siege.ts).
   */
  p?: { b: WireBlueprint; s: Shot[]; e: number; h: string };
}

/** Base pubblica per i link. Nell'app nativa serve VITE_PUBLIC_URL (vedi .env.example). */
export function publicBase(): string {
  const env = import.meta.env.VITE_PUBLIC_URL;
  if (env) return env.replace(/#.*$/, '');
  // Nella WebView nativa (capacitor://localhost) l'origine non è condivisibile: senza
  // VITE_PUBLIC_URL si condivide il solo codice, da incollare in "Ho un codice".
  const isNativeShell = location.hostname === 'localhost' && !location.port;
  if (location.protocol.startsWith('http') && !isNativeShell) return location.origin + location.pathname;
  return '';
}

export function makeLink(key: HashKey, code: string): string {
  return `${publicBase()}#${key}=${code}`;
}

export async function challengeLink(bp: Blueprint): Promise<string> {
  return makeLink('c', await packJson(toWire(bp)));
}

export async function reportLink(r: MatchReport): Promise<string> {
  return makeLink('r', await packJson(r));
}

export function readHash(): { key: HashKey; code: string } | null {
  return parseLinkInput(location.hash);
}

/** Accetta un link intero, un fragment "#c=..." o un codice nudo (in quel caso serve fallbackKey). */
export function parseLinkInput(text: string, fallbackKey?: HashKey): { key: HashKey; code: string } | null {
  const t = text.trim();
  if (!t) return null;
  const hash = t.includes('#') ? t.slice(t.indexOf('#') + 1) : t;
  const params = new URLSearchParams(hash);
  for (const key of ['c', 'r', 'o', 'a', 'd'] as HashKey[]) {
    const v = params.get(key);
    if (v) return { key, code: v };
  }
  if (fallbackKey && /^[zpm][A-Za-z0-9_-]+$/.test(t)) return { key: fallbackKey, code: t };
  return null;
}

export function clearHash(): void {
  history.replaceState(null, '', location.pathname + location.search);
}
