import type { MaterialId } from '../config/materials';
import type { ModeId } from '../config/modes';
import type { WeaponId } from '../config/weapons';
import type { WireBlueprint } from '../game/blueprint';
import type { ThemeId } from '../render/themes';
import type { MatchReport } from './links';

/**
 * Protocollo dei messaggi sul DataChannel (duello live).
 * Modello: l'ATTACCANTE è autorevole sulla fisica e trasmette snapshot; il difensore guarda in diretta.
 * Dettagli e diagrammi: docs/04-P2P-NETWORKING.md.
 */
/**
 * v3 (Step 5): stessi messaggi di v2 più campi ed eventi facoltativi (termite, reflect, flood, wet, tema nella config).
 * Il numero cambia perché una fortezza con la Seta o un attacco con Termite/Piena non sarebbe capito da v2:
 * meglio l'avviso chiaro "aggiornate entrambi" che un duello desincronizzato.
 */
export const PROTOCOL_VERSION = 3;

/** Frequenza degli snapshot (ms tra uno e l'altro, ~15 Hz). */
export const SNAP_INTERVAL = 66;

/**
 * Eventi della battaglia: servono al difensore per effetti e suoni (la posizione dei corpi arriva dagli snapshot).
 * Coordinate in unità mondo, arrotondate.
 */
export type NetEvent =
  | { k: 'shot'; w: WeaponId }
  /** mat (facoltativo): materiale del blocco colpito, per il timbro del suono */
  | { k: 'impact'; x: number; y: number; s: number; mat?: MaterialId }
  | { k: 'broken'; x: number; y: number; mat: MaterialId }
  | { k: 'decoy'; x: number; y: number }
  | { k: 'explosion'; x: number; y: number; r: number }
  /** fulmine: percorso e ramificazioni come coordinate appiattite [x0, y0, x1, y1, …] */
  | { k: 'bolt'; path: number[]; br: number[][] }
  | { k: 'spark'; x: number; y: number }
  | { k: 'gone'; x: number; y: number }
  | { k: 'wind' }
  | { k: 'echo' }
  /** vaso di termiti rotto in (x, y); n = nid del blocco infestato, -1 se nessuno */
  | { k: 'termite'; x: number; y: number; n: number }
  /** la seta ha rimandato il fulmine verso il Cacciatore (fionda bloccata per un attimo) */
  | { k: 'reflect'; x: number; y: number }
  | { k: 'flood' }
  /** fine della piena: nid dei blocchi di ferro rimasti bagnati */
  | { k: 'wet'; n: number[] }
  | { k: 'core-hit'; x: number; y: number; cause: string }
  /** fine dell'assedio; x, y = posizione di Mimika */
  | { k: 'end'; winner: 'attacker' | 'defender'; cause: string; x: number; y: number };

export type NetMessage =
  | { t: 'hello'; ver: number; name: string }
  /** solo chi ha creato l'invito (host) decide modalità e ruoli: defender 0 = host, 1 = ospite */
  | { t: 'config'; mode: ModeId; defender: 0 | 1; theme?: ThemeId }
  | { t: 'build-progress'; blocks: number; spent: number; left: number }
  | { t: 'build-done'; bp: WireBlueprint }
  /**
   * Snapshot delta a ~15 Hz (tick = ms dall'inizio dell'attacco):
   *  b = [nid, x, y, angolo, hp] ripetuti, solo i corpi mossi o danneggiati
   *  p = [nid, indiceArma, x, y, angolo] ripetuti, tutti i proiettili in volo
   *  x = nid rimossi dall'ultimo snapshot
   *  s = [secondi rimasti, colpi, crolli]
   *  a = [sacca x, sacca y, indiceArma caricata | -1] mentre l'attaccante mira, [] altrimenti
   *  f = x del mirino del fulmine, oppure -1
   */
  | { t: 'snap'; tick: number; b: number[]; p: number[]; x: number[]; s: number[]; a: number[]; f: number }
  | { t: 'event'; tick: number; ev: NetEvent }
  | { t: 'result'; report: MatchReport }
  | { t: 'rematch' }
  | { t: 'bye' }
  | { t: 'ping'; ts: number }
  | { t: 'pong'; ts: number };

export type SnapMessage = Extract<NetMessage, { t: 'snap' }>;
export type EventMessage = Extract<NetMessage, { t: 'event' }>;

const TYPES = new Set(['hello', 'config', 'build-progress', 'build-done', 'snap', 'event', 'result', 'rematch', 'bye', 'ping', 'pong']);

/** Filtro difensivo: scarta tutto ciò che non ha la forma minima di un messaggio noto. */
export function isNetMessage(raw: unknown): raw is NetMessage {
  return !!raw && typeof raw === 'object' && TYPES.has((raw as { t?: unknown }).t as string);
}
