import { isNetMessage, type NetMessage } from './protocol';
import type { PeerLink } from './webrtc';

const PING_EVERY = 2000;
/** senza alcun messaggio per questo tempo la connessione si considera persa */
const SILENCE_LIMIT = 15000;

export interface SessionHandlers {
  message(msg: NetMessage): void;
  lost(reason: string): void;
}

/**
 * Sessione di gioco sopra un PeerLink già aperto: messaggi tipizzati, ping/pong (latenza)
 * e keep-alive. Chiama lost() una sola volta, qualunque sia la causa.
 */
export class NetSession {
  /** latenza andata-ritorno in ms (null finché non arriva il primo pong) */
  rtt: number | null = null;
  private lastSeen = performance.now();
  private readonly timer: ReturnType<typeof setInterval>;
  private ended = false;

  constructor(private readonly link: PeerLink, private readonly h: SessionHandlers) {
    link.onMessage = (raw) => this.receive(raw);
    link.onClose = () => this.lose('Il canale si è chiuso.');
    link.onState = (s) => s === 'failed' && this.lose('Connessione diretta interrotta.');
    this.timer = setInterval(() => {
      if (performance.now() - this.lastSeen > SILENCE_LIMIT) return this.lose('Nessuna risposta da 15 secondi.');
      this.send({ t: 'ping', ts: performance.now() });
    }, PING_EVERY);
  }

  get open(): boolean {
    return !this.ended && this.link.isOpen;
  }

  send(msg: NetMessage): boolean {
    if (this.ended) return false;
    try {
      return this.link.send(msg);
    } catch {
      return false; // buffer pieno o canale in chiusura: ci penserà il keep-alive
    }
  }

  /** Chiusura volontaria: avvisa l'altro (bye) e libera le risorse senza chiamare lost(). */
  close(sayBye = true): void {
    if (this.ended) return;
    if (sayBye) this.send({ t: 'bye' });
    this.shutdown();
    // il bye deve partire prima che il canale si chiuda
    setTimeout(() => this.link.close(), 150);
  }

  private receive(raw: unknown): void {
    if (this.ended || !isNetMessage(raw)) return;
    this.lastSeen = performance.now();
    if (raw.t === 'ping') this.send({ t: 'pong', ts: raw.ts });
    else if (raw.t === 'pong') {
      if (typeof raw.ts === 'number') this.rtt = Math.round(performance.now() - raw.ts);
    } else this.h.message(raw);
  }

  private lose(reason: string): void {
    if (this.ended) return;
    this.shutdown();
    this.link.close();
    this.h.lost(reason);
  }

  private shutdown(): void {
    this.ended = true;
    clearInterval(this.timer);
    this.link.onMessage = undefined;
    this.link.onClose = undefined;
    this.link.onState = undefined;
  }
}
