/**
 * Integrazione con le app native (Capacitor): tutto qui, il resto del gioco non sa di girare in un'app.
 * - barra di stato nascosta, splash nascosto quando il gioco è pronto
 * - deep link: mimika://open#c=… e https://<VITE_PUBLIC_URL>#c=… aprono il codice nell'app (appUrlOpen)
 * - pulsante Indietro di Android, pausa dell'audio in background (appStateChange)
 * - condivisione col foglio di sistema (@capacitor/share), schermo sempre acceso durante la partita
 * I plugin si caricano solo nell'app (import dinamici): il sito non li scarica.
 */
import { Capacitor, registerPlugin } from '@capacitor/core';

export const isNative = (): boolean => Capacitor.isNativePlatform();

export interface NativeHooks {
  /** link ricevuto dal sistema (avvio a freddo o app già aperta) */
  openLink(url: string): void;
  /** pulsante Indietro di Android */
  back(): void;
  /** app in primo piano (true) o in background (false) */
  active(on: boolean): void;
}

let exitApp: () => void = () => {};

export async function initNative(hooks: NativeHooks): Promise<void> {
  if (!isNative()) return;
  document.documentElement.classList.add('native', `native-${Capacitor.getPlatform()}`);
  const [{ App }, { StatusBar }, { SplashScreen }] = await Promise.all([
    import('@capacitor/app'), import('@capacitor/status-bar'), import('@capacitor/splash-screen'),
  ]);
  exitApp = () => void App.exitApp();
  StatusBar.hide().catch(() => {});
  void App.addListener('appUrlOpen', ({ url }) => hooks.openLink(url));
  void App.addListener('backButton', () => hooks.back());
  void App.addListener('appStateChange', ({ isActive }) => hooks.active(isActive));
  const launch = await App.getLaunchUrl().catch(() => undefined);
  if (launch?.url) hooks.openLink(launch.url);
  void SplashScreen.hide();
}

export function exitNativeApp(): void {
  exitApp();
}

/** Foglio di condivisione di sistema: plugin nativo nell'app, navigator.share sul web. false se non disponibile o annullato. */
export async function shareText(text: string): Promise<boolean> {
  try {
    if (isNative()) {
      const { Share } = await import('@capacitor/share');
      await Share.share({ text, dialogTitle: 'Condividi con…' });
      return true;
    }
    if (typeof navigator.share !== 'function') return false;
    await navigator.share({ text });
    return true;
  } catch {
    return false;
  }
}

export const canShare = (): boolean => isNative() || typeof navigator.share === 'function';

// ---------------------------------------------------------------- schermo acceso

interface KeepAwakePlugin {
  set(o: { on: boolean }): Promise<void>;
}
/** Plugin minimo in android/…/MainActivity.java (FLAG_KEEP_SCREEN_ON). Su iOS e web si usa la Wake Lock API. */
const KeepAwake = registerPlugin<KeepAwakePlugin>('KeepAwake');
let wakeLock: { release(): Promise<void> } | null = null;
let awake = false;

/** Tiene lo schermo acceso (durante costruzione, attacco e diretta). Best effort: se non si può, pazienza. */
export async function keepAwake(on: boolean): Promise<void> {
  if (on === awake) return;
  awake = on;
  if (Capacitor.getPlatform() === 'android') return KeepAwake.set({ on }).catch(() => {});
  const wl = (navigator as Navigator & { wakeLock?: { request(t: 'screen'): Promise<{ release(): Promise<void> }> } }).wakeLock;
  if (!on) {
    void wakeLock?.release().catch(() => {});
    wakeLock = null;
  } else if (wl && !document.hidden) {
    wakeLock = await wl.request('screen').catch(() => null);
  }
}

// la Wake Lock API si perde quando la pagina va in background: la richiediamo al ritorno
document.addEventListener('visibilitychange', () => {
  if (!document.hidden && awake && Capacitor.getPlatform() !== 'android') {
    awake = false;
    void keepAwake(true);
  }
});
