import { MODES, type ModeDef } from '../config/modes';
import { TUNING, WEAPONS, WEAPON_ORDER, type WeaponId } from '../config/weapons';
import { WORLD } from '../config/world';
import type { PointerInfo } from '../core/input';
import { formatTime, rand } from '../core/math';
import type { Game } from '../game/Game';
import type { Blueprint } from '../game/blueprint';
import { applyShot, makeShot, outcomeKey, type Shot } from '../game/siege';
import { World, type Entity, type Vec } from '../game/World';
import type { NetEvent } from '../net/protocol';
import type { LiveBroadcaster } from '../net/snapshot';
import { drawHunter, drawLauncher, drawStormMarker, drawTrajectory } from '../render/actors';
import { drawWorld } from '../render/scenery';
import { h, icon, tip } from '../ui/dom';
import { ICONS } from '../ui/icons';
import type { CamFocus } from '../render/Renderer';
import { battleFocus, drawEffects, flatPath, hunterMood, mimikaMood, newFxState, playEffect, updateEffects } from './effects';
import { Coach } from '../ui/tutorial';
import type { Scene } from './Scene';

export interface AttackResult {
  winner: 'attacker' | 'defender';
  cause: string;
  shots: number;
  broken: number;
  seconds: number;
  /** per il replay del referto: tiri, passo finale e impronta del risultato */
  replay: { shots: Shot[]; end: number; hash: string };
}

export interface AttackOptions {
  attacker: string;
  defender: string;
  onDone: (r: AttackResult) => void;
  onQuit: () => void;
  /** duello live: trasmette snapshot ed eventi al difensore */
  live?: LiveBroadcaster;
}

const MAX_PULL = 260;
const SHIMMER_PERIOD = 3400;
const AIM_HINT: Record<string, string> = {
  sling: "Trascina all'indietro e rilascia per lanciare.",
  line: "Trascina all'indietro per mirare: la trivella vola dritta.",
  tap: 'Tocca il punto della fortezza da colpire.',
};

/** Fase dell'attaccante: trovare Mimika (mimetizzata) e colpirla con un arsenale limitato. */
export class AttackScene implements Scene {
  readonly mood = 'siege';
  private readonly world: World;
  private readonly mode: ModeDef;
  private readonly ammo: Record<WeaponId, number>;
  private selected: WeaponId = 'boulder';
  private aim: { x0: number; y0: number; x: number; y: number } | null = null;
  private tapX: number | null = null;
  private timeLeft: number;
  private shots = 0;
  private elapsed = 0;
  private lastShotAt = -1e9;
  private overtime = 0;
  private revealMs = 0;
  private slowMs = 0;
  private ended = false;
  private endTimer = 0;
  private result: AttackResult | null = null;
  private lastSecond = -1;
  private readonly log: Shot[] = [];
  private readonly fx = newFxState('atk');
  private readonly shimmerOffset = new Map<number, number>();
  private coach: Coach | null = null;
  private hud!: { timer: HTMLElement; hint: HTMLElement; stats: HTMLElement; cards: Map<WeaponId, HTMLElement>; dock: HTMLElement };

  constructor(private game: Game, bp: Blueprint, private opts: AttackOptions) {
    this.mode = MODES[bp.mode];
    this.ammo = { ...this.mode.arsenal };
    this.timeLeft = this.mode.attackTime;
    const r = (v: number) => Math.round(v);
    this.world = new World(bp, {
      impact: (x, y, s, mat) => this.emit({ k: 'impact', x: r(x), y: r(y), s: Math.round(s * 100) / 100, ...(mat ? { mat } : {}) }),
      broken: (e) => this.emit({ k: 'broken', x: r(e.body.position.x), y: r(e.body.position.y), mat: e.mat! }),
      coreHit: (cause, x, y) => {
        this.emit({ k: 'core-hit', x: r(x), y: r(y), cause });
        this.slowMs = 1600;
        this.end('attacker', cause);
      },
      decoyPopped: (e) => this.emit({ k: 'decoy', x: r(e.body.position.x), y: r(e.body.position.y) }),
      explosion: (x, y, rad) => this.emit({ k: 'explosion', x: r(x), y: r(y), r: rad }),
      bolt: (path, branches) => this.emit({ k: 'bolt', path: flatPath(path), br: branches.map(flatPath) }),
      spark: (x, y) => this.emit({ k: 'spark', x: r(x), y: r(y) }),
      projectileGone: (e) => this.emit({ k: 'gone', x: r(e.body.position.x), y: r(e.body.position.y) }),
      termite: (x, y, target) => this.emit({ k: 'termite', x: r(x), y: r(y), n: target?.nid ?? -1 }),
      reflect: (x, y) => {
        this.emit({ k: 'reflect', x: r(x), y: r(y) });
        this.aim = null;
        this.setHint('La seta specchiante rimanda il fulmine: il Cacciatore è abbagliato per un attimo!');
      },
      wet: (blocks) => blocks.length && this.emit({ k: 'wet', n: blocks.map((e) => e.nid) }),
    });
  }

  /** Effetto locale + inoltro al difensore (duello live). */
  private emit(ev: NetEvent): void {
    playEffect(this.game, ev, this.fx);
    this.opts.live?.event(ev);
  }

  // ------------------------------------------------------------------ ciclo di vita

  enter(): void {
    this.game.ui.hud(this.buildHud());
    this.select(this.firstAvailable() ?? 'boulder', true);
    this.coach = Coach.start(this.game.ui, 'attack');
  }

  exit(): void {
    this.coach?.close();
    this.game.ui.hud(null);
  }

  update(dt: number): void {
    this.elapsed += dt;
    const timeScale = this.slowMs > 0 ? 0.25 : 1;
    this.slowMs -= dt;
    this.world.step(dt, timeScale);
    this.revealMs -= dt;
    updateEffects(this.game, this.fx, dt, this.world);
    this.game.sfx.music.tension = this.ended ? 0 : this.timeLeft <= 10 ? 1 : this.timeLeft <= 30 ? 0.45 : 0;
    this.opts.live?.frame(this.world, this.elapsed, {
      timeLeft: this.timeLeft, shots: this.shots, broken: this.world.broken,
      pouch: this.pouch(), loaded: this.loadedWeapon(), stormX: this.tapX,
    });
    if (this.world.windMs > 0) for (let k = 0; k < 2; k++) this.game.particles.streak(rand(-200, 900), rand(250, 930));

    if (this.ended) {
      this.endTimer -= dt;
      if (this.endTimer <= 0 && this.result) {
        const res = this.result;
        this.result = null;
        this.opts.onDone(res);
      }
      return;
    }

    this.timeLeft -= dt / 1000;
    const sec = Math.ceil(this.timeLeft);
    if (sec !== this.lastSecond) {
      this.lastSecond = sec;
      this.hud.timer.textContent = formatTime(this.timeLeft);
      this.hud.timer.classList.toggle('warn', this.timeLeft <= 10);
      if (this.timeLeft <= 5 && this.timeLeft > 0) this.game.sfx.tick();
    }

    const inFlight = this.world.projectiles.length;
    const sinceShot = this.elapsed - this.lastShotAt;
    if (this.timeLeft <= 0) {
      this.overtime += dt;
      if (inFlight === 0 || this.overtime > 3000) this.end('defender', 'tempo scaduto');
    } else if (this.ammoLeft() === 0 && inFlight === 0 && sinceShot > 1500 && (this.world.isSettled() || sinceShot > 7000)) {
      this.end('defender', 'arsenale esaurito');
    }
  }

  // ------------------------------------------------------------------ disegno

  render(g: CanvasRenderingContext2D, t: number): void {
    const v = this.aimVelocity();
    drawHunter(g, t, { ...hunterMood(this.fx), pouch: this.pouch(), cast: this.tapX !== null });
    drawLauncher(g, t, this.pouch(), this.loadedWeapon(), this.fx.recoil);
    drawWorld(g, this.world, t, { creature: (e) => this.creatureLook(e), look: { x: WORLD.LAUNCH_X, y: WORLD.LAUNCH_Y } });

    if (v) {
      if (this.selected === 'drill') {
        const pts: Vec[] = [];
        for (let i = 1; i < 30; i++) pts.push({ x: WORLD.LAUNCH_X + v.vx * i * 2.2, y: WORLD.LAUNCH_Y + v.vy * i * 2.2 });
        drawTrajectory(g, pts, '#dfe8f0');
      } else drawTrajectory(g, this.trajectory(v.vx, v.vy), '#fff3d6');
    }

    if (this.tapX !== null) drawStormMarker(g, this.tapX, t);
    drawEffects(g, this.fx, t);
  }

  private loadedWeapon(): WeaponId | null {
    const aim = WEAPONS[this.selected].aim;
    return !this.ended && this.ammo[this.selected] > 0 && (aim === 'sling' || aim === 'line') ? this.selected : null;
  }

  private creatureLook(e: Entity) {
    if (this.revealMs > 0 || this.ended) return e.kind === 'core' ? { style: 'live' as const, alpha: 1, ...mimikaMood(this.fx) } : { style: 'decoy' as const, alpha: 1 };
    if (!this.shimmerOffset.has(e.id)) this.shimmerOffset.set(e.id, Math.random() * SHIMMER_PERIOD);
    const ph = ((this.elapsed + this.shimmerOffset.get(e.id)!) % SHIMMER_PERIOD) / SHIMMER_PERIOD;
    const a = ph < 0.22 ? Math.sin((ph / 0.22) * Math.PI) : 0;
    return a > 0.02 ? { style: 'ghost' as const, alpha: a * 0.9 } : null;
  }

  camera(): CamFocus | null {
    return battleFocus(this.world, this.fx, !!this.aim || this.tapX !== null);
  }

  // ------------------------------------------------------------------ input

  down(p: PointerInfo): void {
    if (this.ended || this.ammo[this.selected] <= 0) return;
    if (this.world.jamMs > 0) return this.game.sfx.deny();
    const aim = WEAPONS[this.selected].aim;
    if (aim === 'sling' || aim === 'line') {
      this.aim = { x0: p.x, y0: p.y, x: p.x, y: p.y };
      this.game.sfx.stretch();
    }
    else if (aim === 'tap') this.tapX = p.x;
  }

  move(p: PointerInfo, pressed: boolean): void {
    if (!pressed) return;
    if (this.aim) {
      this.aim.x = p.x;
      this.aim.y = p.y;
    } else if (this.tapX !== null) this.tapX = p.x;
  }

  up(): void {
    if (this.aim) {
      const v = this.aimVelocity();
      this.aim = null;
      if (v && this.elapsed - this.lastShotAt > 450 && this.world.jamMs <= 0) {
        this.fire(makeShot(this.world.steps, this.selected, v.vx, v.vy));
        this.emit({ k: 'shot', w: this.selected });
        this.coach?.signal('shot');
        if (this.selected === 'termite') this.coach?.signal('special');
        this.consume();
      }
    } else if (this.tapX !== null) {
      const x = this.tapX;
      this.tapX = null;
      if (this.world.jamMs > 0) return this.game.sfx.deny();
      this.fire(makeShot(this.world.steps, 'lightning', x));
      this.coach?.signal('shot');
      this.consume();
    }
  }

  key(e: KeyboardEvent): void {
    const n = Number(e.key);
    if (n >= 1 && n <= WEAPON_ORDER.length) this.onCard(WEAPON_ORDER[n - 1]);
  }

  // ------------------------------------------------------------------ logica

  /** Ogni azione passa da qui: viene registrata per il replay del referto e poi applicata al World. */
  private fire(s: Shot): void {
    this.log.push(s);
    applyShot(this.world, s);
  }

  private aimVelocity(): { vx: number; vy: number } | null {
    if (!this.aim) return null;
    const dx = this.aim.x0 - this.aim.x;
    const dy = this.aim.y0 - this.aim.y;
    const len = Math.hypot(dx, dy);
    if (len < 18) return null;
    const speed = this.selected === 'drill' ? TUNING.drillSpeed : 6 + (Math.min(len, MAX_PULL) / MAX_PULL) * 20;
    return { vx: (dx / len) * speed, vy: (dy / len) * speed };
  }

  private pouch(): Vec | null {
    if (!this.aim) return null;
    const dx = this.aim.x - this.aim.x0;
    const dy = this.aim.y - this.aim.y0;
    const len = Math.hypot(dx, dy) || 1;
    const pull = Math.min(len, MAX_PULL) * 0.33;
    return { x: WORLD.LAUNCH_X + (dx / len) * pull, y: WORLD.LAUNCH_Y + (dy / len) * pull };
  }

  /** Anteprima parziale (circa un terzo del volo): mira assistita, non automatica. */
  private trajectory(vx: number, vy: number): Vec[] {
    const g = this.world.gravityPerStep;
    const pts: Vec[] = [];
    let x = WORLD.LAUNCH_X, y = WORLD.LAUNCH_Y;
    for (let i = 0; i < 42; i++) {
      vy += g;
      x += vx;
      y += vy;
      if (y > WORLD.GROUND_Y) break;
      if (i % 3 === 0) pts.push({ x, y });
    }
    return pts;
  }

  private onCard(w: WeaponId): void {
    if (this.ended || this.ammo[w] <= 0) return this.game.sfx.deny();
    if (WEAPONS[w].aim !== 'instant') return this.select(w);
    if (this.world.jamMs > 0 && w !== 'sonar') return this.game.sfx.deny();
    if (w === 'wind') {
      this.fire(makeShot(this.world.steps, w));
      this.emit({ k: 'wind' });
      this.setHint('La bufera si abbatte sulla fortezza!');
    } else if (w === 'flood') {
      this.fire(makeShot(this.world.steps, w));
      this.coach?.signal('special');
      this.emit({ k: 'flood' });
      this.setHint("La piena travolge i blocchi bassi e bagna il ferro: ora un fulmine ci salta sopra!");
    } else {
      this.fire(makeShot(this.world.steps, w));
      this.revealMs = 3000;
      this.emit({ k: 'echo' });
      this.coach?.signal('echo');
      this.setHint("L'eco rivela il vero nascondiglio per 3 secondi!");
    }
    this.lastShotAt = this.elapsed;
    this.ammo[w]--;
    this.shots++;
    this.refresh();
  }

  private consume(): void {
    this.ammo[this.selected]--;
    this.shots++;
    this.lastShotAt = this.elapsed;
    if (this.ammo[this.selected] <= 0) {
      const next = this.firstAvailable(true);
      if (next) this.select(next, true);
    }
    this.refresh();
  }

  private firstAvailable(aimableOnly = false): WeaponId | null {
    return WEAPON_ORDER.find((w) => this.ammo[w] > 0 && (!aimableOnly || WEAPONS[w].aim !== 'instant')) ?? null;
  }

  private ammoLeft(): number {
    return WEAPON_ORDER.reduce((s, w) => s + this.ammo[w], 0);
  }

  private select(w: WeaponId, silent = false): void {
    this.selected = w;
    if (!silent) {
      this.game.sfx.click();
      this.coach?.signal('weapon');
    }
    this.setHint(`${WEAPONS[w].name}: ${WEAPONS[w].desc} ${AIM_HINT[WEAPONS[w].aim] ?? ''}`);
    this.refresh();
  }

  private end(winner: AttackResult['winner'], cause: string): void {
    if (this.ended) return;
    this.ended = true;
    this.coach?.close();
    this.aim = null;
    this.tapX = null;
    this.endTimer = winner === 'attacker' ? 2800 : 2400;
    // impronta calcolata qui, nello stesso punto della simulazione in cui la ricalcola il replay (siege.replaySiege)
    const hash = this.world.digest(outcomeKey(winner, winner === 'attacker' ? cause : ''));
    this.result = {
      winner, cause, shots: this.shots, broken: this.world.broken, seconds: Math.round(this.elapsed / 1000),
      replay: { shots: this.log, end: this.world.steps, hash },
    };
    this.hud.dock.classList.add('hidden');
    const c = this.world.core.body.position;
    this.emit({ k: 'end', winner, cause, x: Math.round(c.x), y: Math.round(c.y) });
    this.setHint(winner === 'attacker' ? `Mimika è stata presa (${cause})!` : `Mimika resiste: ${cause}.`);
  }

  // ------------------------------------------------------------------ HUD

  private setHint(text: string): void {
    this.hud.hint.textContent = text;
  }

  private refresh(): void {
    for (const [w, el] of this.hud.cards) {
      el.classList.toggle('active', w === this.selected && WEAPONS[w].aim !== 'instant');
      el.classList.toggle('empty', this.ammo[w] <= 0);
      el.querySelector('.badge')!.textContent = String(this.ammo[w]);
    }
    this.hud.stats.textContent = `Colpi ${this.shots} · Crolli ${this.world.broken}`;
  }

  private buildHud(): HTMLElement {
    const cards = new Map<WeaponId, HTMLElement>();
    for (const w of WEAPON_ORDER) {
      const d = WEAPONS[w];
      const how = d.aim === 'instant' ? 'Effetto immediato.' : AIM_HINT[d.aim];
      cards.set(w, h('button', { class: `tool weapon fam-${d.family.toLowerCase()}`, 'data-tut': w, 'aria-label': d.name,
        'data-tip': tip(`${d.name} · ${d.family} (${WEAPON_ORDER.indexOf(w) + 1})`, d.desc, how), onclick: () => this.onCard(w) },
        icon(ICONS[w]), h('em', { class: 'badge' }, String(this.ammo[w])), h('small', {}, d.name)));
    }
    const timer = h('div', { class: 'timer' }, formatTime(this.timeLeft));
    const hint = h('div', { class: 'hint' });
    const stats = h('div', { class: 'stats' });
    const dock = h('div', { class: 'dock' }, h('div', { class: 'dock-group' }, ...cards.values()));
    this.hud = { timer, hint, stats, cards, dock };
    return h('div', { class: 'hud attack-hud' },
      h('div', { class: 'hud-top' },
        h('div', { class: 'role-pill atk' }, h('b', {}, 'ATTACCO'), h('span', {}, `${this.opts.attacker} vs ${this.opts.defender}`)),
        timer,
        h('div', { class: 'hud-actions' }, stats),
      ),
      hint,
      dock,
      h('button', { class: 'quit-btn', 'aria-label': 'Esci', 'data-tip': 'Esci', onclick: () => this.opts.onQuit() }, icon(ICONS.back)),
    );
  }
}
