import { PALETTE } from './palette';

export type ThemeId = 'dusk' | 'dawn' | 'night' | 'snow';
export type ThemePref = ThemeId | 'random';

/**
 * Temi ambientali: cambiano solo il diorama di sfondo (cielo, astro, creste, suolo) e il meteo.
 * Blocchi, personaggi e UI restano identici: menta = difesa, corallo = attacco, oro = neutro.
 */
export interface AmbientTheme {
  id: ThemeId;
  name: string;
  /** cielo: alto, medio, basso, orizzonte */
  sky: [string, string, string, string];
  stars: number;
  sun: { core: string; edge: string; glow: string; x: number; y: number; r: number; moon?: boolean };
  /** creste lontana, media, vicina + bordo luminoso di ciascuna */
  ridges: [string, string, string];
  rims: [string, string, string];
  rimWidth: number;
  /** foschie tra gli strati (rgb) */
  haze: [string, string];
  grass: string;
  grassTop: string;
  soil: string;
  soilDeep: string;
  cloud: string;
  /** neve che cade */
  snow?: boolean;
  /** lucciole extra nel menu */
  fireflies?: number;
}

