export const THEME_ORDER: ThemeId[] = ['dusk', 'dawn', 'night', 'snow'];

export function resolveTheme(pref: string): ThemeId {
  if ((THEME_ORDER as string[]).includes(pref)) return pref as ThemeId;
  // casuale, ma il tramonto (tema "di casa") esce più spesso
  return Math.random() < 0.4 ? 'dusk' : THEME_ORDER[1 + Math.floor(Math.random() * 3)];
}
