import { WORLD, cellRect } from '../config/world';
import { TAU } from '../core/math';
import type { Blueprint, PlacedBlock } from '../game/blueprint';
import type { Entity, World } from '../game/World';
import { drawMimika, drawProjectile, type MimikaOpts, type MimikaStyle } from './actors';
import { PALETTE, roundRectPath } from './palette';
import { QUALITY } from './quality';
import { SPRITE_PAD, crackLevel, getBlockSprite } from './sprites';

interface BlockDraw {
  mat: PlacedBlock['mat'];
  x: number;
  y: number;
  w: number;
  h: number;
  angle: number;
  hp: number;
  maxHp: number;
  seed: number;
  flash: number;
  /** termiti al lavoro */
  infest?: boolean;
  /** ferro bagnato dalla piena */
  wet?: boolean;
}

/** Due passate: prima tutte le ombre (in spazio mondo), poi i blocchi. */
export function drawBlocks(g: CanvasRenderingContext2D, blocks: BlockDraw[], alpha = 1, t = 0): void {
  g.save();
  g.globalAlpha = alpha * 0.3;
  g.fillStyle = PALETTE.ink;
  if (QUALITY.shadows) for (const b of blocks) {
    g.save();
    g.translate(b.x + 5, b.y + 6);
    g.rotate(b.angle);
    roundRectPath(g, -b.w / 2, -b.h / 2, b.w, b.h, 6);
    g.fill();
    g.restore();
  }
  g.restore();
  for (const b of blocks) {
    const sprite = getBlockSprite(b.mat, b.w, b.h, crackLevel(b.hp, b.maxHp), b.seed);
    g.save();
    g.globalAlpha = alpha;
    g.translate(b.x, b.y);
    g.rotate(b.angle);
    g.drawImage(sprite, -b.w / 2 - SPRITE_PAD, -b.h / 2 - SPRITE_PAD, b.w + SPRITE_PAD * 2, b.h + SPRITE_PAD * 2);
    if (b.mat === 'silk' && !QUALITY.low) silkSheen(g, b, t);
    if (b.wet) wetSheen(g, b, t);
    if (b.infest) termites(g, b, t);
    if (b.flash > 0) {
      g.globalAlpha = b.flash * 0.6;
      g.fillStyle = '#fff';
      roundRectPath(g, -b.w / 2, -b.h / 2, b.w, b.h, 6);
      g.fill();
    }
    g.restore();
  }
}

/** Riflesso che scorre sulla seta (nello spazio del blocco, già ruotato). */
function silkSheen(g: CanvasRenderingContext2D, b: BlockDraw, t: number): void {
  const k = ((t * 0.3 + (b.seed % 97) * 0.017) % 1.8) - 0.4;
  if (k < -0.2 || k > 1.2) return;
  g.save();
  roundRectPath(g, -b.w / 2, -b.h / 2, b.w, b.h, 8);
  g.clip();
  const x = -b.w / 2 - b.h + k * (b.w + b.h * 2);
  const gr = g.createLinearGradient(x, 0, x + 26, 0);
  gr.addColorStop(0, 'rgba(255,255,255,0)');
  gr.addColorStop(0.5, 'rgba(255,250,235,0.55)');
  gr.addColorStop(1, 'rgba(255,255,255,0)');
  g.globalAlpha = 1;
  g.fillStyle = gr;
  g.beginPath();
  g.moveTo(x, b.h / 2);
  g.lineTo(x + b.h, -b.h / 2);
  g.lineTo(x + b.h + 26, -b.h / 2);
  g.lineTo(x + 26, b.h / 2);
  g.fill();
  g.restore();
}

/** Ferro bagnato: velo azzurro e gocce che scivolano. */
function wetSheen(g: CanvasRenderingContext2D, b: BlockDraw, t: number): void {
  g.globalAlpha = 0.28;
  g.fillStyle = '#7fc8ff';
  roundRectPath(g, -b.w / 2, -b.h / 2, b.w, b.h, 6);
  g.fill();
  g.globalAlpha = 0.85;
  g.fillStyle = '#d8f1ff';
  const n = Math.max(2, Math.round(b.w / 20));
  for (let i = 0; i < n; i++) {
    const x = -b.w / 2 + ((i + 0.5) / n) * b.w;
    const y = -b.h / 2 + (((t * 22 + i * 17 + b.seed) % (b.h + 10)) - 4);
    g.beginPath();
    g.ellipse(x, Math.min(y, b.h / 2 - 2), 1.8, 3, 0, 0, TAU);
    g.fill();
  }
  g.globalAlpha = 1;
}

/** Termiti che corrono sul blocco e lo rosicchiano. */
function termites(g: CanvasRenderingContext2D, b: BlockDraw, t: number): void {
  const n = 3 + Math.round((b.w * b.h) / 1600) * 2;
  g.globalAlpha = 0.3 * (1 - b.hp / b.maxHp);
  g.fillStyle = PALETTE.ink;
  roundRectPath(g, -b.w / 2, -b.h / 2, b.w, b.h, 6);
  g.fill();
  g.globalAlpha = 1;
  for (let i = 0; i < n; i++) {
    const dir = i % 2 ? 1 : -1;
    const per = 2 * (b.w + b.h);
    // percorso lungo il bordo del blocco, ognuna con il suo passo
    let d = (((t * (26 + (i % 3) * 9) * dir + i * 53 + b.seed) % per) + per) % per;
    let x: number, y: number;
    if (d < b.w) (x = -b.w / 2 + d), (y = -b.h / 2 + 4);
    else if ((d -= b.w) < b.h) (x = b.w / 2 - 4), (y = -b.h / 2 + d);
    else if ((d -= b.h) < b.w) (x = b.w / 2 - d), (y = b.h / 2 - 4);
    else (x = -b.w / 2 + 4), (y = b.h / 2 - (d - b.w));
    const wob = Math.sin(t * 20 + i) * 1.2;
    g.fillStyle = '#5a3418';
    g.beginPath();
    g.ellipse(x + wob, y, 3.2, 2, 0, 0, TAU);
    g.fill();
    g.fillStyle = '#f2c48a';
    g.beginPath();
    g.arc(x + wob + 2.6 * dir, y, 1.4, 0, TAU);
    g.fill();
  }
}

export function blueprintBlocks(bp: Blueprint): BlockDraw[] {
  return bp.blocks.map((b, i) => {
    const r = cellRect(b.col, b.row, b.w, b.h);
    return { mat: b.mat, x: r.cx, y: r.cy, w: r.w, h: r.h, angle: 0, hp: 1, maxHp: 1, seed: i * 7919 + 13, flash: 0 };
  });
}

/** Mimika ed esche in posizione statica (costruzione e menu). */
export function drawBlueprintCreatures(g: CanvasRenderingContext2D, bp: Blueprint, t: number, look?: { x: number; y: number }): void {
  for (const d of bp.decoys) {
    const r = cellRect(d.col, d.row);
    drawMimika(g, r.cx, r.cy + 3, t, { style: 'decoy', look });
  }
  const r = cellRect(bp.core.col, bp.core.row);
  drawMimika(g, r.cx, r.cy + 3, t, { style: 'live', look });
}

export interface WorldDrawOpts {
  /** come appaiono Mimika e le esche */
  creature: (e: Entity) => ({ style: MimikaStyle; alpha: number } & Pick<MimikaOpts, 'scared' | 'cheer' | 'dizzy'>) | null;
  look?: { x: number; y: number };
}

export function drawWorld(g: CanvasRenderingContext2D, world: World, t: number, opts: WorldDrawOpts): void {
  const blocks: BlockDraw[] = [];
  const creatures: Entity[] = [];
  const projectiles: Entity[] = [];
  for (const e of world.entities.values()) {
    if (e.kind === 'block' && e.mat) {
      blocks.push({
        mat: e.mat, x: e.body.position.x, y: e.body.position.y, w: e.w, h: e.h, angle: e.body.angle,
        hp: e.hp, maxHp: e.maxHp, seed: e.seed, flash: e.flash, infest: !!e.infest, wet: !!e.wet,
      });
    } else if (e.kind === 'projectile') projectiles.push(e);
    else creatures.push(e);
  }
  // creature sopra i blocchi: il riflesso mimetico resta leggibile anche dietro il cristallo
  drawBlocks(g, blocks, 1, t);
  for (const c of creatures) {
    const look = opts.creature(c);
    if (!look) continue;
    drawMimika(g, c.body.position.x, c.body.position.y, t, { ...look, look: opts.look, angle: c.body.angle * 0.3 });
  }
  for (const p of projectiles) {
    const v = p.body.velocity;
    const angle = p.weapon === 'drill' ? p.body.angle : Math.atan2(v.y, v.x);
    drawProjectile(g, p.weapon!, p.body.position.x, p.body.position.y, p.weapon === 'boulder' ? p.body.angle : angle, t);
  }
}

/** Cornice luminosa della zona di costruzione + griglia a puntini. */
export function drawZone(g: CanvasRenderingContext2D, t: number, intensity = 1): void {
  const x = WORLD.ZONE_X, w = WORLD.ZONE_COLS * WORLD.CELL;
  const h = WORLD.ZONE_ROWS * WORLD.CELL, y = WORLD.GROUND_Y - h;
  g.save();
  const gr = g.createLinearGradient(0, y, 0, WORLD.GROUND_Y);
  gr.addColorStop(0, 'rgba(94,230,197,0)');
  gr.addColorStop(1, `rgba(94,230,197,${0.12 * intensity})`);
  g.fillStyle = gr;
  g.fillRect(x, y, w, h);
  g.fillStyle = `rgba(255,255,255,${0.22 * intensity})`;
  for (let c = 0; c <= WORLD.ZONE_COLS; c++)
    for (let r = 0; r <= WORLD.ZONE_ROWS; r++) {
      g.beginPath();
      g.arc(x + c * WORLD.CELL, WORLD.GROUND_Y - r * WORLD.CELL, 1.4, 0, TAU);
      g.fill();
    }
  g.setLineDash([10, 8]);
  g.lineDashOffset = -t * 20;
  g.strokeStyle = `rgba(94,230,197,${0.55 * intensity})`;
  g.lineWidth = 2;
  g.strokeRect(x, y, w, h);
  g.setLineDash([]);
  g.restore();
}
