import { mulberry32 } from './math';

export type Mood = 'calm' | 'siege' | 'none';
type ThemeId = Exclude<Mood, 'none'>;

/** quanto in anticipo si programmano le note (s) e ogni quanto gira lo scheduler (ms) */
const LOOKAHEAD = 0.18;
const TICK_MS = 60;
const FADE = 1.6;

const midi = (n: number) => 440 * Math.pow(2, (n - 69) / 12);

interface Chord {
  /** fondamentale (MIDI) */
  root: number;
  /** note dell'accordo (MIDI, ottava centrale) */
  notes: number[];
}

interface ThemeDef {
  bpm: number;
  /** passi (crome) per battuta */
  steps: number;
  chords: Chord[];
  /** scala per le melodie (MIDI) */
  scale: number[];
  play(m: Music, out: GainNode, t: number, step: number, bar: number, chord: Chord, rng: () => number): void;
}

/**
 * Musica procedurale WebAudio, nessun file. Due temi con strumenti sintetizzati
 * (kalimba, marimba, archi pizzicati, legni e tamburi):
 * - calma: Do maggiore pentatonico, 84 bpm, per menu e costruzione;
 * - assedio: Re minore, 112 bpm, ostinato pizzicato e taiko, per attacco e diretta.
 * Ogni tema ha il suo guadagno: il cambio di scena fa un crossfade.
 * Lo scheduler programma le note con anticipo sull'orologio audio (niente tremolii del timer JS).
 */
export class Music {
  private ctx: AudioContext | null = null;
  private noise: AudioBuffer | null = null;
  private readonly gains = new Map<ThemeId, GainNode>();
  private readonly clock = new Map<ThemeId, { next: number; step: number; until: number }>();
  private mood: Mood = 'none';
  /** 0..1: l'assedio si fa più fitto negli ultimi secondi */
  tension = 0;
  paused = false;

  attach(ctx: AudioContext, out: AudioNode, noise: AudioBuffer): void {
    this.ctx = ctx;
    this.noise = noise;
    for (const id of Object.keys(THEMES) as ThemeId[]) {
      const g = ctx.createGain();
      g.gain.value = 0;
      g.connect(out);
      this.gains.set(id, g);
      this.clock.set(id, { next: 0, step: 0, until: -1 });
    }
    this.setMood(this.mood, true);
    setInterval(() => this.schedule(), TICK_MS);
  }

  setMood(m: Mood, force = false): void {
    if (m === this.mood && !force) return;
    this.mood = m;
    const ctx = this.ctx;
    if (!ctx) return;
    const now = ctx.currentTime;
    for (const [id, g] of this.gains) {
      const on = id === m;
      g.gain.cancelScheduledValues(now);
      g.gain.setValueAtTime(g.gain.value, now);
      g.gain.linearRampToValueAtTime(on ? 1 : 0, now + FADE);
      const c = this.clock.get(id)!;
      if (on) {
        // ripartenza da capo se il tema era fermo: entra su una battuta pulita
        if (now > c.until) {
          c.next = now + 0.08;
          c.step = 0;
        }
        c.until = Infinity;
      } else if (c.until === Infinity) c.until = now + FADE;
    }
    if (m === 'none') this.tension = 0;
  }

  private schedule(): void {
    const ctx = this.ctx;
    if (!ctx || this.paused || ctx.state !== 'running') return;
    const now = ctx.currentTime;
    for (const id of Object.keys(THEMES) as ThemeId[]) {
      const c = this.clock.get(id)!;
      if (now > c.until) continue;
      const th = THEMES[id];
      const dur = 60 / th.bpm / 2;
      // dopo una pausa lunga (scheda nascosta, muto) si riallinea invece di recuperare
      if (c.next < now - 0.5) c.next = now + 0.05;
      while (c.next < now + LOOKAHEAD) {
        const bar = Math.floor(c.step / th.steps);
        const chord = th.chords[bar % th.chords.length];
        // melodia: stesso seme per una frase di 4 battute, ripetuta con variazioni ogni 2 frasi
        const rng = mulberry32(Math.floor(bar / 8) * 977 + (bar % 4) * 131 + (c.step % th.steps) * 17 + (bar % 8 >= 4 ? 5 : 0));
        th.play(this, this.gains.get(id)!, c.next, c.step % th.steps, bar, chord, rng);
        c.next += dur;
        c.step++;
      }
    }
  }

  // ------------------------------------------------------------------ strumenti

  /** Kalimba: fondamentale sinusoidale con lamella metallica che si spegne subito. */
  kalimba(out: AudioNode, t: number, note: number, vol: number): void {
    const f = midi(note);
    this.osc(out, t, f, 'sine', vol, 0.004, 1.1);
    this.osc(out, t, f * 5.4, 'sine', vol * 0.18, 0.002, 0.08);
  }

  /** Marimba: legno caldo, decadimento rapido. */
  marimba(out: AudioNode, t: number, note: number, vol: number): void {
    const f = midi(note);
    this.osc(out, t, f, 'sine', vol, 0.003, 0.55);
    this.osc(out, t, f * 4, 'sine', vol * 0.25, 0.002, 0.06);
  }

  /** Archi pizzicati: triangolo con filtro che si chiude. */
  pluck(out: AudioNode, t: number, note: number, vol: number, len = 0.3): void {
    const ctx = this.ctx!;
    const o = ctx.createOscillator();
    o.type = 'triangle';
    o.frequency.value = midi(note);
    const f = ctx.createBiquadFilter();
    f.type = 'lowpass';
    f.frequency.setValueAtTime(2400, t);
    f.frequency.exponentialRampToValueAtTime(260, t + len);
    const g = this.env(t, vol, 0.004, len);
    o.connect(f).connect(g).connect(out);
    o.start(t);
    o.stop(t + len + 0.05);
  }

  /** Tappeto morbido: due onde leggermente scordate per nota, filtrate. */
  pad(out: AudioNode, t: number, notes: number[], vol: number, len: number, type: OscillatorType = 'triangle', cutoff = 900): void {
    const ctx = this.ctx!;
    const f = ctx.createBiquadFilter();
    f.type = 'lowpass';
    f.frequency.value = cutoff;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.linearRampToValueAtTime(vol, t + len * 0.35);
    g.gain.linearRampToValueAtTime(0.0001, t + len);
    f.connect(g).connect(out);
    for (const n of notes)
      for (const d of [-6, 6]) {
        const o = ctx.createOscillator();
        o.type = type;
        o.frequency.value = midi(n);
        o.detune.value = d;
        o.connect(f);
        o.start(t);
        o.stop(t + len + 0.05);
      }
  }

  /** Legnetto / woodblock. */
  wood(out: AudioNode, t: number, vol: number, freq = 1800): void {
    this.hit(out, t, vol, freq, 'bandpass', 0.06, 9);
  }

  /** Sonaglio. */
  shaker(out: AudioNode, t: number, vol: number): void {
    this.hit(out, t, vol, 6500, 'highpass', 0.05, 0.7);
  }

  /** Taiko: colpo grave con pelle. */
  drum(out: AudioNode, t: number, vol: number): void {
    const ctx = this.ctx!;
    const o = ctx.createOscillator();
    o.frequency.setValueAtTime(130, t);
    o.frequency.exponentialRampToValueAtTime(48, t + 0.32);
    const g = this.env(t, vol, 0.003, 0.4);
    o.connect(g).connect(out);
    o.start(t);
    o.stop(t + 0.45);
    this.hit(out, t, vol * 0.5, 500, 'lowpass', 0.12, 0.8);
  }

  private osc(out: AudioNode, t: number, freq: number, type: OscillatorType, vol: number, attack: number, len: number): void {
    const ctx = this.ctx!;
    const o = ctx.createOscillator();
    o.type = type;
    o.frequency.value = freq;
    const g = this.env(t, vol, attack, len);
    o.connect(g).connect(out);
    o.start(t);
    o.stop(t + len + 0.05);
  }

  private hit(out: AudioNode, t: number, vol: number, freq: number, type: BiquadFilterType, len: number, q: number): void {
    const ctx = this.ctx!;
    const src = ctx.createBufferSource();
    src.buffer = this.noise;
    const f = ctx.createBiquadFilter();
    f.type = type;
    f.frequency.value = freq;
    f.Q.value = q;
    const g = this.env(t, vol, 0.002, len);
    src.connect(f).connect(g).connect(out);
    src.start(t, Math.random() * 0.8);
    src.stop(t + len + 0.05);
  }

  private env(t: number, vol: number, attack: number, len: number): GainNode {
    const g = this.ctx!.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(Math.max(vol, 0.0002), t + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, t + len);
    return g;
  }
}

const pick = <T>(a: T[], r: number) => a[Math.floor(r * a.length) % a.length];

const THEMES: Record<ThemeId, ThemeDef> = {
  // ---------------------------------------------------------------- costruzione / menu
  calm: {
    bpm: 84,
    steps: 8,
    chords: [
      { root: 48, notes: [60, 64, 67, 71] }, // Do maj7
      { root: 45, notes: [57, 60, 64, 67] }, // La m7
      { root: 41, notes: [57, 60, 64, 65] }, // Fa maj7
      { root: 43, notes: [55, 59, 62, 64] }, // Sol 6
    ],
    scale: [72, 74, 76, 79, 81, 84, 86],
    play(m, out, t, step, bar, chord, rng) {
      const beat = 60 / this.bpm;
      if (step === 0) m.pad(out, t, chord.notes, 0.035, beat * 4.2);
      if (step === 0) m.pluck(out, t, chord.root, 0.2, 0.6);
      if (step === 4) m.pluck(out, t, chord.root + 7, 0.14, 0.5);
      if (step === 6 && bar % 2 === 1) m.pluck(out, t, chord.root + 12, 0.1, 0.4);
      // kalimba: frase leggera, più note sui tempi forti
      const density = [0.85, 0.2, 0.55, 0.35, 0.7, 0.2, 0.5, 0.3][step];
      if (rng() < density) {
        const n = rng() < 0.45 ? pick(chord.notes, rng()) + 12 : pick(this.scale, rng());
        m.kalimba(out, t, n, 0.11 + rng() * 0.05);
      }
      if (step === 2 || step === 6) m.wood(out, t, 0.035, 2200);
      if (bar % 4 === 3 && step === 7) m.marimba(out, t, 84, 0.06);
    },
  },
  // ---------------------------------------------------------------- attacco / diretta
  siege: {
    bpm: 112,
    steps: 8,
    chords: [
      { root: 38, notes: [62, 65, 69] }, // Re m
      { root: 34, notes: [58, 62, 65] }, // Si♭
      { root: 43, notes: [55, 58, 62] }, // Sol m
      { root: 45, notes: [57, 61, 64] }, // La (dominante)
    ],
    scale: [74, 76, 77, 79, 81, 82, 85, 86],
    play(m, out, t, step, bar, chord, rng) {
      const beat = 60 / this.bpm;
      const tense = m.tension;
      // ostinato pizzicato: fondamentale, ottava, quinta
      const bass = [0, 0, 12, 0, 7, 0, 12, 7][step];
      m.pluck(out, t, chord.root + bass, step % 2 ? 0.12 : 0.19, 0.22);
      if (step === 0) m.pad(out, t, chord.notes.map((n) => n - 12), 0.022 + tense * 0.02, beat * 4.1, 'sawtooth', 700 + tense * 900);
      // taiko
      if (step === 0 || step === 3 || (step === 6 && bar % 2 === 1)) m.drum(out, t, step === 0 ? 0.42 : 0.26);
      if (tense > 0.5 && (step === 5 || step === 7)) m.drum(out, t, 0.18 * tense);
      if (step === 2 || step === 6) m.wood(out, t, 0.06, 1500);
      m.shaker(out, t, (step % 2 ? 0.02 : 0.035) + tense * 0.02);
      // marimba: arpeggio inquieto, a frasi alterne
      if (bar % 4 >= 2 || tense > 0.3) {
        if (rng() < 0.65) m.marimba(out, t, pick(chord.notes, rng()) + 12, 0.08);
      } else if (step % 2 === 0 && rng() < 0.5) m.kalimba(out, t, pick(this.scale, rng()), 0.07);
    },
  },
};
