  bomb: { id: 'bomb', name: 'Bomba', family: 'Arma', aim: 'sling', desc: 'Esplode al primo impatto. I muri spessi riparano.' },
  drill: { id: 'drill', name: 'Trivella', family: 'Arma', aim: 'line', desc: 'Vola dritta e perfora 3 blocchi. Il ferro la ferma.' },
  lightning: { id: 'lightning', name: 'Fulmine', family: 'Ambiente', aim: 'tap', desc: "Tocca un punto: colpisce dall'alto. Il ferro conduce, la seta lo rimanda indietro!" },
  wind: { id: 'wind', name: 'Bufera', family: 'Ambiente', aim: 'instant', desc: 'Raffica da sinistra: le torri sottili crollano.' },
  sonar: { id: 'sonar', name: 'Eco', family: 'Stratagemma', aim: 'instant', desc: 'Per 3 secondi rivela dove si nasconde Mimika.' },
