interface LocalMatch {
  mode: ModeId;
  players: [string, string];
  score: [number, number];
  /** indice del giocatore che difende in questo round */
  defender: 0 | 1;
}

/**
 * Orchestratore: loop di gioco, scena corrente e flussi tra le schermate
 * (partita locale, sfida via link, apertura di link ricevuti). Il duello live è in LiveDuel.
 */
export class Game {
  readonly renderer: Renderer;
  readonly particles = new Particles();
  readonly sfx = new Sfx();
  readonly ui: UI;
  /** secondi dall'avvio (per le animazioni) */
  time = 0;
  private scene: Scene;
  private last = 0;
  private mode: ModeId;
  private name: string;
  private match: LocalMatch | null = null;
  private live: LiveDuel | null = null;
  private themePref: ThemePref;
  private menuCoach: Coach | null = null;
  /** ultimo link ricevuto dal sistema e quando (evita doppie aperture all'avvio) */
  private lastLink = { url: '', at: 0 };
  private exitArmed = 0;
  private insetTimer = 0;
  private readonly handlers: PointerHandlers = {
    down: (p) => this.scene.down?.(p),
    move: (p, pressed) => this.scene.move?.(p, pressed),
    up: (p) => this.scene.up?.(p),
  };

  constructor(canvas: HTMLCanvasElement, uiRoot: HTMLElement) {
    this.renderer = new Renderer(canvas);
    this.ui = new UI(uiRoot);
    this.mode = loadPref('mode', 'timed') === 'tactical' ? 'tactical' : 'timed';
    this.name = loadPref('name', '');
    this.sfx.setMuted(loadPref('muted', '0') === '1');
    this.sfx.setVolumes(prefNumber('vol.music', 0.7), prefNumber('vol.sfx', 1));
    this.themePref = loadPref('theme', 'random') as ThemePref;
    this.renderer.setTheme(resolveTheme(this.themePref));
    const q = loadPref('quality', 'auto');
    this.renderer.setQualityPref(q === 'high' || q === 'low' ? q : 'auto');
    this.scene = new BackdropScene(this);
    new Input(canvas, (sx, sy) => this.renderer.screenToWorld(sx, sy), () => this.handlers);
    window.addEventListener('keydown', (e) => {
      if ((e.target as HTMLElement).tagName === 'INPUT' || (e.target as HTMLElement).tagName === 'TEXTAREA') return;
      this.scene.key?.(e);
    });
    window.addEventListener('pointerdown', () => this.sfx.unlock(), { capture: true });
    window.addEventListener('hashchange', () => this.routeHash());
    uiRoot.append(this.soundToggle());
  }

  start(): void {
    if (!this.routeHash()) this.showMenu();
    void initNative({
      openLink: (url) => this.openLink(url),
      back: () => this.back(),
      active: (on) => this.sfx.setBackground(!on),
    });
    requestAnimationFrame((t) => {
      this.last = t;
      this.frame(t);
    });
  }

  private frame(now: number): void {
    const raw = now - this.last;
    const dt = Math.min(raw, 50);
    this.last = now;
    this.time += dt / 1000;
    this.renderer.meter.sample(raw, this.renderer.qualityPref === 'auto');
    if ((this.insetTimer -= raw) <= 0) {
      this.insetTimer = 250;
      this.measureHud();
    }
    this.scene.update(dt);
    this.particles.update(dt);
    const g = this.renderer.g;
    this.renderer.follow(this.scene.camera?.() ?? null, dt);
    this.renderer.beginFrame(this.time, dt);
    this.scene.render(g, this.time);
    this.particles.draw(g);
    this.renderer.endFrame(this.time, dt);
    requestAnimationFrame((t) => this.frame(t));
  }

  /**
   * Quanto spazio occupano barra in alto e attrezzi in basso dell'HUD in partita: il Renderer
   * inquadra il campo nello spazio rimasto (sui telefoni bassi altrimenti il suolo finisce sotto la barra).
   */
  private measureHud(): void {
    const top = document.querySelector<HTMLElement>('#ui .hud-top');
    const dock = document.querySelector<HTMLElement>('#ui .dock:not(.hidden)');
    const t = top ? top.getBoundingClientRect().bottom : 0;
    const b = dock ? window.innerHeight - dock.getBoundingClientRect().top : 0;
    // solo quando lo spazio libero è davvero poco: su schermi grandi l'inquadratura resta quella di sempre
    const tight = window.innerHeight < 620;
    this.renderer.setInsets(tight ? t : 0, tight ? b : 0);
  }

  setScene(next: Scene): void {
    this.scene.exit?.();
    this.particles.clear();
    this.scene = next;
    this.sfx.setMood(next.mood ?? 'calm');
    void keepAwake(!(next instanceof BackdropScene)); // in partita lo schermo non si spegne
    next.enter?.();
  }

  private get playerName(): string {
    return this.nameOr('Giocatore 1');
  }

  nameOr(fallback: string): string {
    return this.name.trim() || fallback;
  }

  setName(n: string): void {
    this.name = n;
    savePref('name', n);
  }

  get currentMode(): ModeId {
    return this.mode;
  }

  // ------------------------------------------------------------------ menu

  showMenu(): void {
    this.match = null;
    this.live?.dispose();
    this.live = null;
    this.ui.closeModals();
    this.setScene(new BackdropScene(this));
    this.ui.screen(menuScreen({
      name: this.name,
      mode: this.mode,
      onName: (n) => { this.name = n; savePref('name', n); },
      onMode: (m) => {
        this.mode = m;
        savePref('mode', m);
        this.sfx.click();
        const rec = document.querySelector('[data-tut="survival"] small');
        if (rec) rec.textContent = this.records().survival;
      },
      onLocal: () => this.startLocal(),
      onChallenge: () => this.startChallenge(),
      onLive: () => this.openLive(),
      onSurvival: () => this.startSurvival(),
      onDaily: () => this.startDaily(),
      records: this.records(),
      onCode: () => codeModal(this.ui, (text) => {
        const parsed = parseLinkInput(text, 'c');
        if (!parsed) return this.ui.toast('Link o codice non riconosciuto.', 'warn');
        void this.openCode(parsed.key, parsed.code);
      }),
      onHelp: () => this.ui.modal(howToContent()),
      onSettings: () => this.openSettings(),
    }));
    this.menuCoach?.close();
    this.menuCoach = Coach.start(this.ui, 'menu', 'side');
  }

  /** Record locali mostrati nel menu. */
  private records(): { survival: string; daily: string } {
    const best = Number(loadPref(`survival.${this.mode}`, '0')) || 0;
    const today = dailyRecord(dailySeed());
    return {
      survival: best ? `Record ${MODES[this.mode].name}: ${best} ${best === 1 ? 'ondata' : 'ondate'}` : `Da solo, ${MODES[this.mode].name}`,
      daily: today?.won ? `Oggi: presa in ${today.shots} colpi` : today ? 'Oggi: da ritentare' : 'Nuova fortezza oggi',
    };
  }

  private openSettings(): void {
    this.sfx.click();
    const close = this.ui.modal(settingsContent({
      music: this.sfx.musicVolume,
      sfx: this.sfx.sfxVolume,
      theme: this.themePref,
      quality: this.renderer.qualityPref,
      perf: () => `${this.renderer.meter.fps} fps · qualità ${QUALITY.low ? 'leggera' : 'alta'}${this.renderer.qualityPref === 'auto' ? ' (automatica)' : ''}`,
      onVolume: (m, s) => {
        this.sfx.setVolumes(m, s);
        savePref('vol.music', String(m));
        savePref('vol.sfx', String(s));
      },
      onTheme: (t) => {
        this.themePref = t;
        savePref('theme', t);
        this.renderer.setTheme(resolveTheme(t));
        this.sfx.click();
      },
      onQuality: (q) => {
        savePref('quality', q);
        this.renderer.setQualityPref(q);
        this.sfx.click();
      },
      onTutorial: () => {
        resetTutorials();
        close();
        this.showMenu();
        this.ui.toast('Il tutorial ripartirà dalla prossima partita.', 'good');
      },
      onInstall: canInstall() ? () => { close(); void promptInstall(); } : undefined,
    }));
  }

  /** Tema casuale a ogni nuova partita (se scelto "Casuale" nelle impostazioni). */
  private rollTheme(): void {
    if (this.themePref === 'random') this.renderer.setTheme(resolveTheme('random'));
  }

  confirmQuit(): void {
    const close = this.ui.modal(h('div', { class: 'confirm' },
      h('h2', {}, 'Abbandonare la partita?'),
      h('p', {}, 'I progressi di questo round andranno persi.'),
      h('div', { class: 'row' },
        h('button', { class: 'btn ghost', onclick: () => close() }, 'Continua'),
        h('button', { class: 'btn primary', onclick: () => { close(); this.showMenu(); } }, 'Torna al menu'),
      )));
  }

  // ------------------------------------------------------------------ partita locale (hot-seat)

  private startLocal(): void {
    this.rollTheme();
    this.match = { mode: this.mode, players: [this.playerName, 'Giocatore 2'], score: [0, 0], defender: 0 };
    this.localRound();
  }

  private localRound(): void {
    const m = this.match!;
    const def = m.players[m.defender];
    const atk = m.players[1 - m.defender];
    const nameField = h('input', { class: 'name-input', maxlength: '16', value: m.players[1], placeholder: 'Nome avversario',
      oninput: (e: Event) => (m.players[1] = (e.target as HTMLInputElement).value.trim() || 'Giocatore 2') });
    this.handoff({
      role: 'def',
      title: `${def} difende`,
      text: `${atk}, girati e non sbirciare! Modalità ${MODES[m.mode].name}: ${MODES[m.mode].buildTime} secondi per costruire.`,
      cta: 'Inizia a costruire',
      extra: m.score[0] + m.score[1] === 0 ? h('label', { class: 'field' }, h('span', {}, 'Avversario'), nameField) : undefined,
      onGo: () => {
        const defName = m.players[m.defender];
        const atkName = m.players[1 - m.defender];
        this.build(m.mode, defName, (bp) =>
          this.handoff({
            role: 'atk',
            title: `Tocca a ${atkName}`,
            text: `La fortezza di ${defName} è pronta. Passa il dispositivo a ${atkName}: Mimika è nascosta da qualche parte...`,
            cta: "All'attacco!",
            bp,
            onGo: () => this.attack(bp, atkName, defName, (res) => this.localResult(res)),
          }));
      },
    });
  }

  private localResult(res: AttackResult): void {
    const m = this.match!;
    const winnerIdx = res.winner === 'attacker' ? 1 - m.defender : m.defender;
    m.score[winnerIdx]++;
    this.ui.hud(null);
    this.ui.screen(resultScreen({
      winnerName: m.players[winnerIdx],
      winnerRole: res.winner === 'attacker' ? 'atk' : 'def',
      cause: res.cause,
      shots: res.shots,
      broken: res.broken,
      seconds: res.seconds,
      score: { names: m.players, values: m.score },
      actions: [
        { label: 'Rivincita a ruoli invertiti', ico: ICONS.users, primary: true, onClick: () => { m.defender = m.defender === 0 ? 1 : 0; this.localRound(); } },
        { label: 'Menu', ico: ICONS.back, onClick: () => this.showMenu() },
      ],
    }));
  }

  // ------------------------------------------------------------------ sfida asincrona via link

  startChallenge(): void {
    this.rollTheme();
    this.handoff({
      role: 'def',
      title: 'Crea una sfida',
      text: `Costruisci la tua fortezza (${MODES[this.mode].name}). Alla fine riceverai un link da mandare a chi vuoi: lo giocherà quando vuole, anche senza essere online insieme a te.`,
      cta: 'Inizia a costruire',
      onGo: () => this.build(this.mode, this.playerName, (bp) => void this.shareChallenge(bp)),
    });
  }

  async shareChallenge(bp: Blueprint): Promise<void> {
    const link = await challengeLink(bp);
    // ricorda la fortezza inviata: il referto che torna indietro dirà se è proprio questa
    const sent = sentFortresses().filter((id) => id !== fortressId(bp));
    savePref('sent', JSON.stringify([fortressId(bp), ...sent].slice(0, 20)));
    this.setScene(new BackdropScene(this, bp));
    this.ui.screen(shareScreen(this.ui, {
      title: 'La tua fortezza è pronta!',
      text: "Manda il link all'avversario. Quando avrà giocato, ti rimanderà il link con il risultato.",
      link,
      shareText: `${bp.author} ti sfida a Mimika: riesci a scovare il camaleonte nella mia fortezza?`,
      onDone: () => this.showMenu(),
    }));
  }

  // ------------------------------------------------------------------ da solo: sopravvivenza e sfida del giorno

  private startSurvival(): void {
    this.menuCoach?.signal('start');
    this.rollTheme();
    const mode = this.mode;
    this.handoff({
      role: 'def',
      title: 'Sopravvivenza',
      text: `Costruisci la fortezza (${MODES[mode].name}, ${MODES[mode].buildTime} secondi). Poi il Cacciatore automatico attaccherà a ondate: ogni volta con l'arsenale pieno e una mira più precisa, mentre i danni restano. Quante ondate resisterà Mimika?`,
      cta: 'Inizia a costruire',
      onGo: () => this.build(mode, this.playerName, (bp) => this.survive(bp)),
    });
  }

  private survive(bp: Blueprint): void {
    this.ui.screen(null);
    this.setScene(new SurvivalScene(this, bp, {
      defender: this.playerName,
      seed: (Math.random() * 1e9) | 0,
      onDone: (r) => this.survivalResult(bp, r),
      onQuit: () => this.confirmQuit(),
    }));
  }

  private survivalResult(bp: Blueprint, r: SurvivalResult): void {
    const key = `survival.${bp.mode}`;
    const best = Number(loadPref(key, '0')) || 0;
    if (r.waves > best) savePref(key, String(r.waves));
    const unit = (n: number) => `${n} ${n === 1 ? 'ondata' : 'ondate'}`;
    this.ui.hud(null);
    this.ui.screen(resultScreen({
      winnerName: this.playerName,
      winnerRole: r.waves > 0 ? 'def' : 'atk',
      cause: r.cause,
      shots: r.shots,
      broken: r.broken,
      seconds: r.seconds,
      badge: 'SOPRAVVIVENZA',
      title: `${unit(r.waves)} ${r.waves === 1 ? 'superata' : 'superate'}`,
      causeText: `Mimika è stata presa all'ondata ${r.waves + 1}: ${r.cause}.`,
      extra: h('p', { class: 'record' }, r.waves > best ? `Nuovo record in modalità ${MODES[bp.mode].name}!` : `Record ${MODES[bp.mode].name}: ${unit(best)}`),
      actions: [
        { label: 'Riprova con la stessa fortezza', ico: ICONS.replay, primary: true, onClick: () => this.survive(bp) },
        { label: 'Nuova fortezza', ico: ICONS.survival, onClick: () => this.startSurvival() },
        { label: 'Menu', ico: ICONS.back, onClick: () => this.showMenu() },
      ],
    }));
  }

  /** Sfida del giorno: la fortezza nasce dal seme della data, quindi è uguale per tutti (anche via link #d=). */
  private startDaily(seed = dailySeed()): void {
    this.menuCoach?.signal('start');
    this.rollTheme();
    const bp = generateFortress(seed, 'tactical', 'mixed', 'Sfida del giorno');
    const rec = dailyRecord(seed);
    this.handoff({
      role: 'atk',
      title: `Sfida del giorno · ${dateLabel(seed)}`,
      text: `Una fortezza uguale per tutti, solo per oggi. Scova Mimika con meno colpi possibile: hai ${MODES.tactical.attackTime} secondi.` +
        (rec?.won ? ` Il tuo record: presa in ${rec.shots} colpi (${rec.seconds}s).` : rec ? ' Ci hai già provato: ritenta!' : ''),
      cta: "All'attacco!",
      bp,
      onGo: () => this.attack(bp, this.playerName, 'Mimika', (res) => this.dailyResult(seed, res)),
    });
  }

  private dailyResult(seed: number, res: AttackResult): void {
    const won = res.winner === 'attacker';
    const rec = dailyRecord(seed);
    const better = !rec || (won && (!rec.won || res.shots < rec.shots || (res.shots === rec.shots && res.seconds < rec.seconds)));
    if (better) savePref(`daily.${seed}`, JSON.stringify({ won, shots: res.shots, seconds: res.seconds }));
    if (won && !rec?.won) savePref('daily.wins', String((Number(loadPref('daily.wins', '0')) || 0) + 1));
    const days = Number(loadPref('daily.wins', '0')) || 0;
    const link = makeLink('d', String(seed));
    this.ui.hud(null);
    this.ui.screen(resultScreen({
      winnerName: won ? this.playerName : 'Mimika',
      winnerRole: won ? 'atk' : 'def',
      cause: res.cause,
      shots: res.shots,
      broken: res.broken,
      seconds: res.seconds,
      badge: `SFIDA DEL GIORNO · ${dateLabel(seed)}`,
      title: won ? `Presa in ${res.shots} colpi!` : 'Mimika ti è sfuggita',
      extra: h('p', { class: 'record' },
        won && better ? 'Nuovo record di oggi!' : rec?.won ? `Record di oggi: ${rec.shots} colpi (${rec.seconds}s)` : 'Domani una fortezza nuova.',
        days ? ` · Sfide vinte: ${days}` : ''),
      actions: [
        { label: 'Sfida un amico', sub: 'Stessa fortezza: chi fa meno colpi?', ico: ICONS.share, primary: true, onClick: () =>
          this.ui.screen(shareScreen(this.ui, {
            title: 'Sfida del giorno',
            text: 'Chi apre il link gioca la stessa fortezza di oggi.',
            link,
            shareText: won ? `Ho scovato Mimika in ${res.shots} colpi nella sfida del giorno: fai di meglio?` : 'La sfida del giorno di Mimika mi ha battuto: provaci tu!',
            onDone: () => this.showMenu(),
            doneLabel: 'Menu',
          })) },
        { label: 'Riprova', ico: ICONS.replay, onClick: () => this.startDaily(seed) },
        { label: 'Menu', ico: ICONS.back, onClick: () => this.showMenu() },
      ],
    }));
  }

  // ------------------------------------------------------------------ referto con replay

  private showReport(rep: MatchReport): void {
    this.setScene(new BackdropScene(this));
    this.ui.hud(null);
    this.ui.screen(reportScreen(rep, () => this.showMenu(), () => this.startChallenge(), this.checkReport(rep)));
  }

  /** Rigioca senza grafica i tiri del referto e confronta l'impronta del risultato. */
  private checkReport(rep: MatchReport): ReplayCheck | null {
    const p = rep.p;
    if (!p) return null;
    const bp = fromWire(p.b);
    const shots = cleanShots(p.s);
    if (!bp || !shots || !Number.isInteger(p.e) || p.e < 0 || typeof p.h !== 'string')
      return { ok: false, text: 'Il replay allegato è danneggiato: risultato non verificabile.' };
    const claimed = rep.w === 'atk' ? 'attacker' : 'defender';
    const out = replaySiege(bp, shots, p.e, claimed);
    const mine = sentFortresses().includes(fortressId(bp));
    const where = mine ? ' È proprio la fortezza che hai inviato.' : ' (Fortezza non trovata tra quelle inviate da questo dispositivo.)';
    const ok = out.winner === claimed && out.hash === p.h;
    return {
      ok,
      text: ok
        ? `Risultato verificato: rigiocando qui ${shots.length === 1 ? "l'unico tiro" : `i ${shots.length} tiri`} si ottiene lo stesso identico esito.${where}`
        : `Il replay non torna: qui i tiri danno «${out.winner === 'attacker' ? 'Mimika presa' : 'Mimika salva'}». Succede tra motori di browser diversi (es. Safari e Chrome) o se il referto è stato modificato.`,
      onReplay: () => this.watchReplay(rep, bp, shots, claimed),
    };
  }

  private watchReplay(rep: MatchReport, bp: Blueprint, shots: Shot[], claimed: 'attacker' | 'defender'): void {
    this.ui.screen(null);
    this.setScene(new ReplayScene(this, bp, { shots, end: rep.p!.e, claimed, attacker: rep.an, defender: rep.dn, onDone: () => this.showReport(rep) }));
  }


  // ------------------------------------------------------------------ duello live P2P (vedi LiveDuel)

  private openLive(): void {
    this.menuCoach?.signal('start');
    this.sfx.click();
    this.ui.screen(liveHomeScreen({
      mode: this.mode,
      onHost: () => this.startLive(() => LiveDuel.host(this)),
      onJoin: (text) => {
        const parsed = parseLinkInput(text, 'o');
        if (parsed?.key === 'o') this.startLive(() => LiveDuel.guest(this, parsed.code));
        else if (parsed?.key === 'a') this.ui.toast("Questa è una risposta: aprila nella scheda in cui hai creato l'invito.", 'warn');
        else this.ui.toast("Link d'invito non riconosciuto.", 'warn');
      },
      onBack: () => this.showMenu(),
    }));
  }

  private startLive(create: () => LiveDuel): void {
    this.live?.dispose();
    this.match = null;
    this.ui.closeModals();
    this.live = create();
  }

  /** Risposta #a= aperta qui: se questa scheda ha l'invito la usa, altrimenti la inoltra alla scheda giusta. */
  private async deliverAnswer(code: string): Promise<void> {
    if (this.live?.applyAnswer(code)) return;
    const delivered = await forwardAnswerToOriginalTab(code);
    const menu = { label: 'Menu', ico: ICONS.back, onClick: () => this.showMenu() };
    this.setScene(new BackdropScene(this));
    this.ui.screen(delivered
      ? noticeScreen({ badge: 'DUELLO LIVE', title: 'Risposta consegnata!',
          text: "Torna alla scheda in cui hai creato l'invito: il duello parte lì. Questa scheda puoi chiuderla.", actions: [menu] })
      : noticeScreen({ badge: 'DUELLO LIVE', title: 'Nessun invito aperto qui',
          text: "Apri la risposta sullo stesso dispositivo e browser in cui hai creato l'invito, con quella scheda ancora aperta. Oppure copiala e incollala lì, in «Apri la sua risposta».",
          actions: [
            { label: 'Copia la risposta', ico: ICONS.copy, primary: true, onClick: async () =>
              this.ui.toast((await copyText(makeLink('a', code))) ? 'Risposta copiata!' : 'Copia non riuscita.', 'good') },
            menu,
          ] }));
  }

  // ------------------------------------------------------------------ app nativa

  /** Deep link dall'app (mimika://open#c=… o https://…#c=…). */
  private openLink(url: string): void {
    const now = performance.now();
    if (url === this.lastLink.url && now - this.lastLink.at < 3000) return;
    this.lastLink = { url, at: now };
    const hit = parseLinkInput(url);
    if (hit) void this.openCode(hit.key, hit.code);
  }

  /** Pulsante Indietro di Android: chiude le finestre → chiede se uscire dalla partita → menu → esce. */
  private back(): void {
    if (this.ui.closeTopModal()) return;
    const quit = document.querySelector<HTMLElement>('#ui .quit-btn');
    if (quit) return quit.click();
    if (!this.ui.showing('menu')) return this.match || this.live ? this.confirmQuit() : this.showMenu();
    if (performance.now() - this.exitArmed < 2000) return exitNativeApp();
    this.exitArmed = performance.now();
    this.ui.toast('Premi di nuovo Indietro per uscire.');
  }

  /** Gestisce i link ricevuti (#c= sfida, #r= risultato, #o/#a= duello live). */
  private routeHash(): boolean {
    const hit = readHash();
    if (!hit) return false;
    clearHash();
    void this.openCode(hit.key, hit.code);
    return true;
  }

  private async openCode(key: HashKey, code: string): Promise<void> {
    this.menuCoach?.close();
    try {
      if (key === 'c') {
        const bp = fromWire(await unpackJson(code));
        if (!bp) throw new Error('blueprint non valido');
        return this.playChallenge(bp);
      }
      if (key === 'r') {
        const rep = await unpackJson<MatchReport>(code);
        if (rep?.v !== 1) throw new Error('referto non valido');
        return this.showReport(rep);
      }
      if (key === 'd') {
        if (!/^20\d{6}$/.test(code)) throw new Error('data non valida');
        return this.startDaily(Number(code));
      }
      if (key === 'o') {
        // invito corto (m + segreto della cassetta) o invito manuale (offerta compressa)
        if (!/^(m[A-Za-z0-9_-]{22}|[zp][A-Za-z0-9_-]{20,})$/.test(code)) throw new Error('invito non valido');
        return this.startLive(() => LiveDuel.guest(this, code));
      }
      return await this.deliverAnswer(code);
    } catch {
      this.ui.toast('Link incompleto o non valido: fattelo rimandare copiandolo tutto.', 'warn');
      this.showMenu();
    }
  }

  private playChallenge(bp: Blueprint): void {
    this.rollTheme();
    this.mode = bp.mode;
    const nameField = h('input', { class: 'name-input', maxlength: '16', value: this.name, placeholder: 'Il tuo nome',
      oninput: (e: Event) => { this.name = (e.target as HTMLInputElement).value; savePref('name', this.name); } });
    this.handoff({
      role: 'atk',
      title: `${bp.author} ti sfida!`,
      text: `Modalità ${MODES[bp.mode].name}: hai ${MODES[bp.mode].attackTime} secondi per scovare e colpire Mimika nella sua fortezza.`,
      cta: "All'attacco!",
      bp,
      extra: h('label', { class: 'field' }, h('span', {}, 'Nome'), nameField),
      onGo: () => this.attack(bp, this.playerName, bp.author, (res) => void this.challengeResult(bp, res)),
    });
  }

  async challengeResult(bp: Blueprint, res: AttackResult): Promise<void> {
    const report: MatchReport = {
      v: 1, w: res.winner === 'attacker' ? 'atk' : 'def', an: this.playerName, dn: bp.author, m: bp.mode,
      s: res.shots, k: res.broken, t: res.seconds, c: res.cause,
      p: { b: toWire(bp), s: res.replay.shots, e: res.replay.end, h: res.replay.hash },
    };
    const link = await reportLink(report);
    const atkWon = res.winner === 'attacker';
    this.ui.hud(null);
    this.ui.screen(resultScreen({
      winnerName: atkWon ? this.playerName : bp.author,
      winnerRole: atkWon ? 'atk' : 'def',
      cause: res.cause,
      shots: res.shots,
      broken: res.broken,
      seconds: res.seconds,
      actions: [
        {
          label: `Manda il risultato a ${bp.author}`, ico: ICONS.share, primary: true, onClick: () =>
            this.ui.screen(shareScreen(this.ui, {
              title: 'Referto della battaglia',
              text: `Rimanda questo link a ${bp.author} per fargli vedere com'è andata.`,
              link,
              shareText: atkWon ? `Ho scovato il tuo Mimika in ${res.seconds}s!` : 'La tua fortezza ha resistito... per stavolta.',
              onDone: () => this.showMenu(),
              doneLabel: 'Menu',
            })),
        },
        { label: 'Rivincita: costruisci tu', ico: ICONS.link, onClick: () => this.startChallenge() },
        { label: 'Menu', ico: ICONS.back, onClick: () => this.showMenu() },
      ],
    }));
  }

  // ------------------------------------------------------------------ mattoncini dei flussi

  handoff(o: { role: 'def' | 'atk'; title: string; text: string; cta: string; bp?: Blueprint; extra?: HTMLElement; onGo(): void }): void {
    this.menuCoach?.signal('start');
    this.menuCoach?.close();
    this.ui.hud(null);
    this.setScene(new BackdropScene(this, o.bp, !!o.bp));
    this.ui.screen(handoffScreen({ ...o, onBack: () => this.showMenu(), onGo: () => { this.sfx.click(); o.onGo(); } }));
  }

  build(mode: ModeId, author: string, onDone: (bp: Blueprint) => void, onProgress?: BuildOptions['onProgress']): void {
    this.ui.screen(null);
    this.setScene(new BuildScene(this, mode, { author, onDone, onProgress, onQuit: () => this.confirmQuit() }));
  }

  attack(bp: Blueprint, attacker: string, defender: string, onDone: (r: AttackResult) => void, live?: LiveBroadcaster): void {
    this.ui.screen(null);
    this.setScene(new AttackScene(this, bp, { attacker, defender, onDone, live, onQuit: () => this.confirmQuit() }));
  }

  private soundToggle(): HTMLElement {
    const btn = h('button', { class: 'sound-btn', 'aria-label': 'Audio', 'data-tip': tip('Audio', 'Silenzia o riattiva musica ed effetti.', 'Volumi separati nelle Impostazioni.') },
      icon(this.sfx.muted ? ICONS.mute : ICONS.sound));
    btn.addEventListener('click', () => {
      this.sfx.setMuted(!this.sfx.muted);
      savePref('muted', this.sfx.muted ? '1' : '0');
      btn.replaceChildren(icon(this.sfx.muted ? ICONS.mute : ICONS.sound));
    });
    return btn;
  }
}

/** Impronta di una fortezza (come viaggia nei link). */
const fortressId = (bp: Blueprint) => hashString(JSON.stringify(toWire(bp)));

function sentFortresses(): string[] {
  try {
    const list: unknown = JSON.parse(loadPref('sent', '[]'));
    return Array.isArray(list) ? list.filter((s): s is string => typeof s === 'string') : [];
  } catch {
    return [];
  }
}

function dailyRecord(seed: number): { won: boolean; shots: number; seconds: number } | null {
  try {
    const r = JSON.parse(loadPref(`daily.${seed}`, 'null'));
    return r && typeof r.shots === 'number' ? r : null;
  } catch {
    return null;
  }
}

/** 20261022 -> "22/10/2026" */
const dateLabel = (seed: number) =>
  `${String(seed % 100).padStart(2, '0')}/${String(Math.floor(seed / 100) % 100).padStart(2, '0')}/${Math.floor(seed / 10000)}`;


function prefNumber(key: string, fallback: number): number {
  const n = Number(loadPref(key, String(fallback)));
  return Number.isFinite(n) ? Math.min(1, Math.max(0, n)) : fallback;
}
