import { MATERIALS } from '../config/materials';
import type { Game } from '../game/Game';
import { floodShape, type Vec, type World } from '../game/World';
import { TUNING } from '../config/weapons';
import type { NetEvent } from '../net/protocol';
import { drawBolt, drawFlood, drawSonarRing, type HunterPose, type MimikaOpts } from '../render/actors';
import { PALETTE } from '../render/palette';
import type { CamFocus } from '../render/Renderer';

/**
 * Effetti visivi e sonori della battaglia, guidati da NetEvent.
 * Unica fonte per entrambi i lati del duello: l'attaccante li genera dal World,
 * lo spettatore (difensore) li riceve dalla rete e li riproduce identici.
 * Qui vivono anche gli stati d'animo dei personaggi e il punto seguito dalla camera:
 * così attaccante e difensore vedono la stessa scena.
 */
export const BOLT_LIFE = 450;
export const SONAR_LIFE = 1600;
/** distanza (unità mondo) entro cui un proiettile in volo spaventa Mimika */
const SCARE_RADIUS = 170;
const CATCH_FOCUS_MS = 2600;

export interface FxState {
  /** chi guarda: decide il suono di fine (vittoria o sconfitta) */
  viewer: 'atk' | 'def';
  bolts: { path: Vec[]; branches: Vec[][]; life: number }[];
  sonarRings: number[];
  /** posizione di Mimika (aggiornata a ogni frame da updateEffects) */
  core: Vec | null;
  /** 0..1 stati d'animo: decadono da soli */
  scare: number;
  recoil: number;
  /** Cacciatore abbagliato dal fulmine riflesso */
  daze: number;
  /** ms dall'inizio della piena (-1 = nessuna) */
  flood: number;
  /** esito: Mimika esulta / è presa; il Cacciatore esulta / si abbatte */
  winner: 'attacker' | 'defender' | null;
  /** la camera stringe su Mimika quando viene presa */
  focus: Vec | null;
  focusMs: number;
}

export const newFxState = (viewer: FxState['viewer']): FxState => ({
  viewer, bolts: [], sonarRings: [], core: null, scare: 0, recoil: 0, daze: 0, flood: -1, winner: null, focus: null, focusMs: 0,
});

/** Vec[] -> [x0, y0, x1, y1, …] arrotondati (formato degli eventi fulmine). */
export const flatPath = (pts: Vec[]): number[] => pts.flatMap((p) => [Math.round(p.x), Math.round(p.y)]);

function unflat(a: unknown): Vec[] {
  if (!Array.isArray(a)) return [];
  const pts: Vec[] = [];
  for (let i = 0; i + 1 < a.length && pts.length < 64; i += 2) if (Number.isFinite(a[i]) && Number.isFinite(a[i + 1])) pts.push({ x: a[i], y: a[i + 1] });
  return pts;
}

const isNum = (...v: unknown[]) => v.every((n) => Number.isFinite(n));

/** Un colpo vicino a Mimika la spaventa. Lo squittio lo sente solo chi difende (non deve tradirla). */
function scareNear(game: Game, st: FxState, x: number, y: number, radius: number): void {
  if (!st.core || st.winner) return;
  if (Math.hypot(x - st.core.x, y - st.core.y) > radius) return;
  st.scare = 1;
  if (st.viewer === 'def') game.sfx.eek();
}

export function playEffect(game: Game, ev: NetEvent, st: FxState): void {
  const fx = game.particles;
  const sfx = game.sfx;
  const r = game.renderer;
  switch (ev.k) {
    case 'shot':
      sfx.launch(ev.w);
      st.recoil = 1;
      break;
    case 'impact': {
      if (!isNum(ev.x, ev.y, ev.s)) return;
      const mat = ev.mat && ev.mat in MATERIALS ? ev.mat : undefined;
      if (ev.s > 0.15) sfx.thud(ev.s, mat);
      if (ev.s > 0.35) fx.dust(ev.x, ev.y, 2);
      if (ev.s > 0.3) scareNear(game, st, ev.x, ev.y, 90);
      r.shake(ev.s * 4);
      break;
    }
    case 'broken':
      if (!isNum(ev.x, ev.y) || !(ev.mat in MATERIALS)) return;
      fx.debris(ev.x, ev.y, ev.mat, 14);
      sfx.broken(ev.mat);
      scareNear(game, st, ev.x, ev.y, 110);
      r.shake(3);
      break;
    case 'decoy':
      if (!isNum(ev.x, ev.y)) return;
      fx.text(ev.x, ev.y - 36, 'Esca!', PALETTE.gold);
      fx.debris(ev.x, ev.y, 'wood', 8);
      sfx.pop();
      break;
    case 'explosion':
      if (!isNum(ev.x, ev.y, ev.r)) return;
      fx.explosion(ev.x, ev.y, ev.r);
      sfx.boom();
      scareNear(game, st, ev.x, ev.y, ev.r + 120);
      r.shake(16);
      r.flash(0.22, '255,210,150');
      break;
    case 'bolt': {
      const path = unflat(ev.path);
      if (path.length < 2) return;
      const branches = (Array.isArray(ev.br) ? ev.br.slice(0, 24) : []).map(unflat);
      st.bolts.push({ path, branches, life: BOLT_LIFE });
      const end = path[path.length - 1];
      fx.sparks(end.x, end.y, 18, PALETTE.bolt);
      sfx.zap();
      scareNear(game, st, end.x, end.y, 160);
      r.flash(0.5, '210,200,255');
      r.shake(7);
      break;
    }
    case 'spark':
      if (!isNum(ev.x, ev.y)) return;
      fx.sparks(ev.x, ev.y, 14);
      sfx.tick();
      break;
    case 'gone':
      if (isNum(ev.x, ev.y)) fx.dust(ev.x, ev.y, 4);
      break;
    case 'wind':
      sfx.wind();
      break;
    case 'echo':
      st.sonarRings.push(0);
      sfx.ping();
      break;
    case 'termite':
      if (!isNum(ev.x, ev.y)) return;
      fx.dust(ev.x, ev.y, 5, 'rgba(160,96,60,0.55)');
      fx.sparks(ev.x, ev.y, 10, '#5a3418');
      if (ev.n < 0) fx.text(ev.x, ev.y - 30, 'Niente da rosicchiare', PALETTE.gold);
      sfx.chew();
      scareNear(game, st, ev.x, ev.y, 90);
      break;
    case 'reflect':
      if (!isNum(ev.x, ev.y)) return;
      fx.text(ev.x, ev.y - 34, 'Riflesso!', '#e4dbff');
      fx.sparks(ev.x, ev.y, 22, '#fff3d6');
      fx.ring(ev.x, ev.y, 60, '#cbb8ff', 700);
      sfx.mirror();
      st.daze = 1;
      r.flash(0.3, '228,219,255');
      break;
    case 'flood':
      st.flood = 0;
      sfx.flood();
      r.shake(5);
      break;
    case 'core-hit':
      if (!isNum(ev.x, ev.y)) return;
      fx.text(ev.x, ev.y - 40, 'PRESA!', PALETTE.attacker);
      fx.sparks(ev.x, ev.y, 26, '#ffe7f0');
      fx.ring(ev.x, ev.y, 90, PALETTE.attacker, 800);
      sfx.squeak();
      r.flash(0.35, '255,180,200');
      st.scare = 1;
      st.focus = { x: ev.x, y: ev.y };
      st.focusMs = CATCH_FOCUS_MS;
      break;
    case 'end':
      st.winner = ev.winner === 'defender' ? 'defender' : 'attacker';
      sfx.setMood('none');
      if (ev.winner === 'defender' && isNum(ev.x, ev.y)) {
        fx.text(ev.x, ev.y - 44, 'Al sicuro!', PALETTE.defender);
        fx.ring(ev.x, ev.y, 70, PALETTE.defender, 900);
        fx.sparks(ev.x, ev.y - 10, 24, PALETTE.defender);
        sfx.cheer();
        st.scare = 0;
      }
      if (st.viewer === 'def' && ev.winner === 'attacker') sfx.lose(); else sfx.win();
      break;
  }
}

export function updateEffects(game: Game, st: FxState, dt: number, world: World): void {
  for (let i = st.sonarRings.length - 1; i >= 0; i--) if ((st.sonarRings[i] += dt) > SONAR_LIFE) st.sonarRings.splice(i, 1);
  for (let i = st.bolts.length - 1; i >= 0; i--) if ((st.bolts[i].life -= dt) <= 0) st.bolts.splice(i, 1);
  st.scare = Math.max(0, st.scare - dt / 1100);
  st.recoil = Math.max(0, st.recoil - dt / 650);
  st.daze = Math.max(0, st.daze - dt / TUNING.reflectJamMs);
  if (st.flood >= 0 && (st.flood += dt) > TUNING.floodMs) st.flood = -1;
  st.focusMs = Math.max(0, st.focusMs - dt);
  const c = world.core?.body.position;
  st.core = c ? { x: c.x, y: c.y } : null;
  if (!st.core) return;
  for (const e of world.entities.values()) {
    if (e.kind !== 'projectile') continue;
    const p = e.body.position;
    scareNear(game, st, p.x, p.y, SCARE_RADIUS);
  }
}

/**
 * Cosa segue la camera: Mimika appena presa, altrimenti l'ultimo proiettile in volo.
 * Ferma durante la mira (il trascinamento resta preciso). Uguale per attaccante e spettatore.
 */
export function battleFocus(world: World, st: FxState, aiming: boolean): CamFocus | null {
  if (st.focus && st.focusMs > 0) return { x: st.focus.x, y: st.focus.y, zoom: 1.1 };
  if (aiming) return null;
  let last: Vec | null = null;
  for (const e of world.entities.values()) if (e.kind === 'projectile') last = e.body.position;
  return last ? { x: last.x, y: last.y } : null;
}

/** Espressione di Mimika (vera) secondo lo stato della battaglia. */
export function mimikaMood(st: FxState): Pick<MimikaOpts, 'scared' | 'cheer' | 'dizzy'> {
  if (st.winner === 'defender') return { cheer: 1 };
  if (st.winner === 'attacker') return { dizzy: true, scared: 0.4 };
  return { scared: st.scare };
}

/** Posa del Cacciatore (senza la sacca, che dipende dalla scena). */
export function hunterMood(st: FxState): HunterPose {
  return { recoil: st.recoil, cheer: st.winner === 'attacker' ? 1 : 0, slump: st.winner === 'defender' ? 1 : Math.min(0.5, st.daze), daze: st.daze };
}

export function drawEffects(g: CanvasRenderingContext2D, st: FxState, t = 0): void {
  const wave = st.flood >= 0 ? floodShape(TUNING.floodMs - st.flood, TUNING.floodMs) : null;
  if (wave) drawFlood(g, wave.x, wave.h, t);
  for (const b of st.bolts) drawBolt(g, b.path, b.branches, b.life / BOLT_LIFE);
  for (const age of st.sonarRings) drawSonarRing(g, age / SONAR_LIFE);
}
