import { h, loadPref, savePref, type UI } from './dom';

export type TutorialId = 'menu' | 'build' | 'attack';

interface Step {
  text: string;
  /** selettore CSS degli elementi da evidenziare */
  target?: string;
  /** segnale che fa avanzare da solo (es. 'place' quando si piazza un blocco) */
  until?: string;
}

const STEPS: Record<TutorialId, Step[]> = {
  menu: [
    {
      target: '[data-tut="local"]',
      until: 'start',
      text: 'Ciao! In MIMIKA chi difende costruisce una fortezza e ci nasconde il camaleonte, chi attacca deve scovarlo. Inizia con una «Partita locale»: ti guido io, passo passo. Da solo puoi provare «Sopravvivenza» e la «Sfida del giorno».',
    },
  ],
  build: [
    { target: '.build-hud .tool.mat', until: 'material', text: 'Sei in DIFESA. Qui sotto ci sono i materiali: ognuno ha costo e resistenza diversi. Scegline uno.' },
    { target: '.build-hud .tool.mat-silk, .build-hud .tool.mat-metal', text: 'Il ferro ferma la trivella ma conduce il fulmine; la Seta specchiante invece lo rimanda al Cacciatore e lo abbaglia. Occhio: le termiti mangiano legno e muschio, la piena sposta i blocchi bassi.' },
    { target: '.build-hud .tool.shape', until: 'place', text: 'Tocca la zona tratteggiata a destra per piazzare un blocco. Puoi cambiare forma e ruotarla (R).' },
    { target: '[data-tut="core"]', until: 'core', text: 'Mimika è il camaleonte da proteggere. Con «Mimika» la sposti in un nascondiglio migliore: in attacco sarà quasi invisibile.' },
    { target: '[data-tut="decoy"]', until: 'decoy', text: "Le esche luccicano proprio come Mimika: piazzale per ingannare chi attacca." },
    { target: '[data-tut="test"], [data-tut="done"]', until: 'done', text: '«Prova» simula la gravità senza toccare il progetto. Quando sei soddisfatto premi «Pronto».' },
  ],
  attack: [
    { until: 'shot', text: "Sei in ATTACCO! Trascina all'indietro da un punto qualsiasi e rilascia: il Cacciatore tira con la fionda. I puntini mostrano l'inizio della traiettoria." },
    { target: '.attack-hud .tool.weapon', until: 'weapon', text: 'Le munizioni sono contate: prova anche Bomba, Trivella, Fulmine… Tieni premuto (o passa sopra) uno strumento per leggere cosa fa.' },
    { target: '[data-tut="sonar"]', until: 'echo', text: "Mimika è mimetizzata: cerca i riflessi tremolanti, ma occhio alle esche! L'Eco la rivela per 3 secondi." },
    { target: '[data-tut="termite"], [data-tut="flood"]', until: 'special', text: 'Termite: un vaso che rosicchia legno e muschio poco a poco (il metallo no). Piena: un\'onda che spinge i blocchi bassi e bagna il ferro, così il fulmine successivo salta più lontano. Attento alla seta: rimanda il fulmine indietro!' },
  ],
};

const done = (id: TutorialId) => loadPref('tut.skip', '0') === '1' || loadPref(`tut.${id}`, '0') === '1';

/** Rimette il tutorial come alla prima apertura (dalle impostazioni). */
export function resetTutorials(): void {
  savePref('tut.skip', '0');
  for (const id of Object.keys(STEPS)) savePref(`tut.${id}`, '0');
}

/**
 * Tutorial interattivo a fumetti: non blocca il gioco (il canvas resta giocabile, il tempo scorre),
 * evidenzia i comandi e avanza da solo quando il giocatore fa l'azione richiesta.
 * Saltabile; ricordato in localStorage (savePref).
 */
export class Coach {
  private i = 0;
  private closed = false;

  private constructor(private readonly ui: UI, private readonly id: TutorialId, private readonly where: 'top' | 'side') {}

  /** Avvia il tutorial se non è già stato visto. */
  static start(ui: UI, id: TutorialId, where: 'top' | 'side' = 'top'): Coach | null {
    if (done(id)) return null;
    const c = new Coach(ui, id, where);
    // aspetta che l'HUD sia nel DOM per evidenziare i bersagli
    requestAnimationFrame(() => c.show());
    return c;
  }

  /** Azione del giocatore: se un passo (attuale o successivo) la attende, si va oltre. */
  signal(name: string): void {
    if (this.closed) return;
    const steps = STEPS[this.id];
    const j = steps.findIndex((s, k) => k >= this.i && s.until === name);
    if (j < 0) return;
    this.i = j + 1;
    if (this.i >= steps.length) this.finish();
    else this.show();
  }

  close(): void {
    if (this.closed) return;
    this.closed = true;
    this.highlight(null);
    this.ui.coach(null);
  }

  private finish(): void {
    savePref(`tut.${this.id}`, '1');
    this.close();
  }

  private next(): void {
    this.i++;
    if (this.i >= STEPS[this.id].length) this.finish();
    else this.show();
  }

  private show(): void {
    if (this.closed) return;
    const steps = STEPS[this.id];
    const step = steps[this.i];
    const last = this.i === steps.length - 1;
    this.highlight(step.target ?? null);
    this.ui.coach(h('div', { class: `coach ${this.where}`, role: 'dialog', 'aria-live': 'polite' },
      h('div', { class: 'coach-mimika', 'aria-hidden': 'true' }),
      h('div', { class: 'coach-body' },
        steps.length > 1 ? h('small', { class: 'coach-step' }, `Tutorial ${this.i + 1}/${steps.length}`) : null,
        h('p', {}, step.text),
        h('div', { class: 'row' },
          h('button', { class: 'btn ghost small', onclick: () => { savePref('tut.skip', '1'); this.close(); } }, 'Salta il tutorial'),
          h('button', { class: 'btn primary small', onclick: () => this.next() }, last ? 'Ho capito' : 'Avanti'),
        ),
      ),
    ));
  }

  private highlight(selector: string | null): void {
    document.querySelectorAll('.coach-target').forEach((el) => el.classList.remove('coach-target'));
    if (selector) document.querySelectorAll(selector).forEach((el) => el.classList.add('coach-target'));
  }
}
