type Child = Node | string | null | undefined | false;
type Props = Record<string, unknown>;

/** Mini-hyperscript: h('button', { class: 'btn', onclick: fn }, 'Testo'). */
export function h<K extends keyof HTMLElementTagNameMap>(tag: K, props: Props = {}, ...children: Child[]): HTMLElementTagNameMap[K] {
  const el = document.createElement(tag);
  for (const [k, v] of Object.entries(props)) {
    if (v == null || v === false) continue;
    if (k === 'class') el.className = String(v);
    else if (k === 'html') el.innerHTML = String(v);
    else if (k === 'style' && typeof v === 'object') {
      // setProperty: unico modo per assegnare custom properties CSS (--nome)
      for (const [prop, val] of Object.entries(v as Record<string, string>)) {
        if (prop.startsWith('--')) el.style.setProperty(prop, val);
        else (el.style as unknown as Record<string, string>)[prop] = val;
      }
    }
    else if (k.startsWith('on') && typeof v === 'function') el.addEventListener(k.slice(2).toLowerCase(), v as EventListener);
    else el.setAttribute(k, v === true ? '' : String(v));
  }
  for (const c of children) if (c != null && c !== false) el.append(c);
  return el;
}

/** Icona SVG inline (stringa da icons.ts). */
export const icon = (svg: string, cls = 'ico') => h('span', { class: cls, html: svg, 'aria-hidden': 'true' });

/** Gestore dei livelli UI: hud (durante il gioco), screen (menu/pannelli), coach (tutorial), modal, toast, tooltip. */
export class UI {
  private readonly hudLayer: HTMLElement;
  private readonly screenLayer: HTMLElement;
  private readonly coachLayer: HTMLElement;
  private readonly modalLayer: HTMLElement;
  private readonly toastLayer: HTMLElement;

  constructor(root: HTMLElement) {
    this.hudLayer = h('div', { class: 'layer hud-layer' });
    this.screenLayer = h('div', { class: 'layer screen-layer' });
    this.coachLayer = h('div', { class: 'layer coach-layer' });
    this.modalLayer = h('div', { class: 'layer modal-layer' });
    this.toastLayer = h('div', { class: 'layer toast-layer' });
    root.append(this.hudLayer, this.screenLayer, this.coachLayer, this.modalLayer, this.toastLayer);
    installTooltips(root);
  }

  coach(el: HTMLElement | null): void {
    this.coachLayer.replaceChildren(...(el ? [el] : []));
  }

  hud(el: HTMLElement | null): void {
    this.hudLayer.replaceChildren(...(el ? [el] : []));
  }

  screen(el: HTMLElement | null): void {
    this.screenLayer.replaceChildren(...(el ? [el] : []));
  }

  modal(content: HTMLElement): () => void {
    const close = () => backdrop.remove();
    const backdrop = h('div', { class: 'modal-backdrop', onclick: (e: Event) => e.target === backdrop && close() },
      h('div', { class: 'modal panel' }, h('button', { class: 'modal-close', onclick: close, 'aria-label': 'Chiudi' }, '×'), content));
    this.modalLayer.append(backdrop);
    return close;
  }

  /** Chiude la finestra in primo piano (pulsante Indietro). false se non ce n'erano. */
  closeTopModal(): boolean {
    const top = this.modalLayer.lastElementChild;
    top?.remove();
    return !!top;
  }

  /** C'è una schermata con questa classe (es. 'menu')? */
  showing(cls: string): boolean {
    return !!this.screenLayer.querySelector(`:scope > .${cls}`);
  }

  closeModals(): void {
    this.modalLayer.replaceChildren();
  }

  toast(text: string, kind: 'info' | 'warn' | 'good' = 'info'): void {
    const el = h('div', { class: `toast ${kind}` }, text);
    this.toastLayer.append(el);
    setTimeout(() => el.classList.add('out'), 2200);
    setTimeout(() => el.remove(), 2700);
  }
}

/** Testo per data-tip: titolo in grassetto, poi descrizione e dettagli (righe separate). */
export const tip = (...lines: (string | undefined)[]) => lines.filter(Boolean).join('\n');

/**
 * Tooltip per gli elementi con data-tip: al passaggio del mouse, o tenendo premuto su touch.
 * Un'unica bolla in position: fixed (il dock scorre in orizzontale e taglierebbe i ::after).
 */
function installTooltips(root: HTMLElement): void {
  const bubble = h('div', { class: 'tooltip', role: 'tooltip' });
  root.append(bubble);
  let timer = 0;
  let current: HTMLElement | null = null;
  const show = (el: HTMLElement) => {
    const text = el.dataset.tip;
    if (!text || !el.isConnected) return;
    current = el;
    const [title, ...rest] = text.split('\n');
    bubble.replaceChildren(h('b', {}, title), ...rest.map((r) => h('span', {}, r)));
    bubble.classList.add('on');
    const r = el.getBoundingClientRect();
    const bw = bubble.offsetWidth, bh = bubble.offsetHeight;
    const x = Math.min(window.innerWidth - bw - 8, Math.max(8, r.left + r.width / 2 - bw / 2));
    const above = r.top - bh - 10;
    bubble.style.left = `${x}px`;
    bubble.style.top = `${above > 8 ? above : r.bottom + 10}px`;
  };
  const hide = () => {
    clearTimeout(timer);
    current = null;
    bubble.classList.remove('on');
  };
  const target = (e: Event) => (e.target as Element | null)?.closest?.('[data-tip]') as HTMLElement | null;
  root.addEventListener('pointerover', (e) => {
    if (e.pointerType !== 'mouse') return;
    const el = target(e);
    if (el === current) return;
    hide();
    if (el) timer = window.setTimeout(() => show(el), 350);
  });
  root.addEventListener('pointerout', (e) => e.pointerType === 'mouse' && !target(e)?.contains(e.relatedTarget as Node) && hide());
  root.addEventListener('pointerdown', (e) => {
    hide();
    const el = target(e);
    if (el && e.pointerType !== 'mouse') timer = window.setTimeout(() => show(el), 450);
  });
  root.addEventListener('pointerup', (e) => {
    if (e.pointerType === 'mouse') return hide();
    clearTimeout(timer);
    if (current) timer = window.setTimeout(hide, 1600);
  });
  root.addEventListener('pointercancel', hide);
}

export async function copyText(text: string): Promise<boolean> {
  try {
    await navigator.clipboard.writeText(text);
    return true;
  } catch {
    const ta = h('textarea', { style: { position: 'fixed', opacity: '0' } });
    ta.value = text;
    document.body.append(ta);
    ta.select();
    const ok = document.execCommand('copy');
    ta.remove();
    return ok;
  }
}

export function loadPref(key: string, fallback: string): string {
  try {
    return localStorage.getItem(`mimika.${key}`) ?? fallback;
  } catch {
    return fallback;
  }
}

export function savePref(key: string, value: string): void {
  try {
    localStorage.setItem(`mimika.${key}`, value);
  } catch {
    /* storage non disponibile (navigazione privata): si ignora */
  }
}
