/**
 * Geometria del mondo. Tutto il gioco ragiona in "unità mondo" (1920x1080 logici);
 * il Renderer scala e centra la regione VIEW su qualsiasi schermo.
 */
export const WORLD = {
  W: 1920,
  H: 1080,
  GROUND_Y: 940,
  CELL: 40,
  /** Zona di costruzione del difensore (a destra). */
  ZONE_X: 1100,
  ZONE_COLS: 16,
  ZONE_ROWS: 12,
  /** Fionda dell'attaccante (a sinistra). */
  LAUNCH_X: 250,
  LAUNCH_Y: 795,
  /** Sotto questa quota un corpo è considerato caduto fuori dal mondo. */
  KILL_Y: 1500,
  /** Regione che deve essere sempre visibile, qualunque sia lo schermo. */
  VIEW: { x0: 70, y0: 330, x1: 1850, y1: 1080 },
} as const;

export interface Cell {
  col: number;
  row: number;
}

/** Rettangolo in coordinate mondo di un blocco che parte dalla cella (col,row) in basso a sinistra. */
export function cellRect(col: number, row: number, w = 1, h = 1) {
  const x = WORLD.ZONE_X + col * WORLD.CELL;
  const y = WORLD.GROUND_Y - (row + h) * WORLD.CELL;
  const pw = w * WORLD.CELL;
  const ph = h * WORLD.CELL;
  return { x, y, w: pw, h: ph, cx: x + pw / 2, cy: y + ph / 2 };
}

export function pointToCell(x: number, y: number): Cell {
  return {
    col: Math.floor((x - WORLD.ZONE_X) / WORLD.CELL),
    row: Math.floor((WORLD.GROUND_Y - y) / WORLD.CELL),
  };
}

export function inZone(col: number, row: number, w = 1, h = 1): boolean {
  return col >= 0 && row >= 0 && col + w <= WORLD.ZONE_COLS && row + h <= WORLD.ZONE_ROWS;
}
