export type Action = { label: string; sub?: string; ico?: string; primary?: boolean; disabled?: boolean; tut?: string; onClick: () => void };

export const actionBtn = (a: Action) =>
  h('button', { class: `btn big${a.primary ? ' primary' : ''}`, disabled: a.disabled, 'data-tut': a.tut, onclick: a.onClick },
    a.ico ? icon(a.ico) : null, h('span', { class: 'btn-text' }, a.label, a.sub ? h('small', {}, a.sub) : null));

const brand = () =>
  h('header', { class: 'brand' },
    h('h1', { class: 'logo' }, ...'MIMIKA'.split('').map((c, i) => h('span', { style: { '--i': String(i) } }, c))),
    h('p', { class: 'tagline' }, 'Costruisci. Nasconditi. Assedia.'));

// ---------------------------------------------------------------- menu

export interface MenuOpts {
  name: string;
  mode: ModeId;
  onName(n: string): void;
  onMode(m: ModeId): void;
  onLocal(): void;
  onChallenge(): void;
  onLive(): void;
  onSurvival(): void;
  onDaily(): void;
  /** riassunto dei record locali (sopravvivenza, sfida del giorno) */
  records: { survival: string; daily: string };
  onCode(): void;
  onHelp(): void;
  onSettings(): void;
}

export function menuScreen(o: MenuOpts): HTMLElement {
  const modeCards = (Object.keys(MODES) as ModeId[]).map((id) => {
    const m = MODES[id];
    const card = h('button', { class: `mode-card${id === o.mode ? ' active' : ''}`, onclick: () => {
      o.onMode(id);
      card.parentElement!.querySelectorAll('.mode-card').forEach((c) => c.classList.toggle('active', c === card));
    } },
      h('b', {}, m.name),
      h('span', {}, m.tagline),
      h('small', {}, `${m.buildTime}s costruzione · ${m.attackTime}s attacco · ${m.budget} risorse · ${m.decoys} esche`));
    return card;
  });
  const nameInput = h('input', { class: 'name-input', maxlength: '16', placeholder: 'Il tuo nome', value: o.name, oninput: (e: Event) => o.onName((e.target as HTMLInputElement).value) });

  return h('div', { class: 'screen menu' },
    h('div', { class: 'menu-left' }, brand(),
      h('p', { class: 'pitch' }, "Uno costruisce una fortezza e ci nasconde Mimika, il camaleonte che si mimetizza. L'altro ha un arsenale limitato per scovarla e colpirla."),
    ),
    h('div', { class: 'menu-right panel' },
      h('label', { class: 'field' }, h('span', {}, 'Nome'), nameInput),
      h('div', { class: 'mode-picker' }, ...modeCards),
      h('div', { class: 'actions' },
        actionBtn({ label: 'Partita locale', sub: 'Due giocatori, un dispositivo', ico: ICONS.users, primary: true, tut: 'local', onClick: o.onLocal }),
        actionBtn({ label: 'Sfida via link', sub: 'Costruisci e invia la fortezza', ico: ICONS.link, onClick: o.onChallenge }),
        actionBtn({ label: 'Duello live P2P', sub: 'In diretta, ognuno sul suo dispositivo', ico: ICONS.live, onClick: o.onLive }),
        h('div', { class: 'solo-row' },
          h('button', { class: 'btn solo def', 'data-tut': 'survival', onclick: o.onSurvival,
            'data-tip': tip('Sopravvivenza · da solo', 'Costruisci e resisti alle ondate del Cacciatore automatico.', o.records.survival) },
            icon(ICONS.survival), h('span', { class: 'btn-text' }, 'Sopravvivenza', h('small', {}, o.records.survival))),
          h('button', { class: 'btn solo', 'data-tut': 'daily', onclick: o.onDaily,
            'data-tip': tip('Sfida del giorno', 'Una fortezza nuova ogni giorno, uguale per tutti: scova Mimika con meno colpi possibile.', o.records.daily) },
            icon(ICONS.daily), h('span', { class: 'btn-text' }, 'Sfida del giorno', h('small', {}, o.records.daily))),
        ),
      ),
      h('div', { class: 'row wrap menu-links' },
        h('button', { class: 'btn ghost', onclick: o.onCode, 'data-tip': tip('Hai ricevuto un link?', 'Incolla una sfida, un risultato o un invito al duello.') }, icon(ICONS.key), 'Link o codice'),
        h('button', { class: 'btn ghost', onclick: o.onHelp }, icon(ICONS.help), 'Come si gioca'),
        h('button', { class: 'btn ghost icon-only', onclick: o.onSettings, 'aria-label': 'Impostazioni', 'data-tip': tip('Impostazioni', 'Musica, effetti, ambiente, grafica, tutorial.') }, icon(ICONS.settings)),
      ),
    ),
  );
}

