// ---------------------------------------------------------------- impostazioni

export interface SettingsOpts {
  music: number;
  sfx: number;
  theme: ThemePref;
  quality: QualityPref;
  /** stato attuale delle prestazioni, es. "60 fps · qualità alta" */
  perf(): string;
  onVolume(music: number, sfx: number): void;
  onTheme(t: ThemePref): void;
  onQuality(q: QualityPref): void;
  onTutorial(): void;
  /** presente solo se il browser permette di installare l'app (PWA) */
  onInstall?: () => void;
}

/** Gruppo di pulsanti a scelta singola. */
function segmented<T extends string>(options: [T, string][], value: T, onPick: (v: T) => void): HTMLElement {
  const wrap = h('div', { class: 'segmented', role: 'radiogroup' });
  for (const [v, label] of options) {
    const b = h('button', { class: `seg${v === value ? ' active' : ''}`, role: 'radio', 'aria-checked': String(v === value), onclick: () => {
      wrap.querySelectorAll('.seg').forEach((el) => { el.classList.toggle('active', el === b); el.setAttribute('aria-checked', String(el === b)); });
      onPick(v);
    } }, label);
    wrap.append(b);
  }
  return wrap;
}

export function settingsContent(o: SettingsOpts): HTMLElement {
  let music = o.music, sfx = o.sfx;
  const slider = (label: string, value: number, set: (v: number) => void) =>
    h('label', { class: 'slider' }, h('span', {}, label),
      h('input', { type: 'range', min: '0', max: '100', step: '5', value: String(Math.round(value * 100)),
        oninput: (e: Event) => { set(Number((e.target as HTMLInputElement).value) / 100); o.onVolume(music, sfx); } }));
  const perf = h('small', { class: 'perf' }, o.perf());
  const timer = setInterval(() => (perf.isConnected ? (perf.textContent = o.perf()) : clearInterval(timer)), 1000);
  return h('div', { class: 'settings' },
    h('h2', {}, 'Impostazioni'),
    h('section', {},
      h('h3', {}, 'Audio'),
      slider('Musica', music, (v) => (music = v)),
      slider('Effetti', sfx, (v) => (sfx = v)),
      h('p', { class: 'tip' }, 'Il pulsante in alto a destra silenzia tutto.'),
    ),
    h('section', {},
      h('h3', {}, 'Ambiente'),
      segmented<ThemePref>([['random', 'Casuale'], ...THEME_ORDER.map((id) => [id, THEMES[id].name] as [ThemePref, string])], o.theme, o.onTheme),
    ),
    h('section', {},
      h('h3', {}, 'Grafica'),
      segmented<QualityPref>([['auto', 'Automatica'], ['high', 'Alta'], ['low', 'Leggera']], o.quality, o.onQuality),
      perf,
    ),
    h('div', { class: 'row wrap' },
      h('button', { class: 'btn', onclick: o.onTutorial }, icon(ICONS.help), 'Rivedi il tutorial'),
      o.onInstall ? h('button', { class: 'btn primary', onclick: o.onInstall }, icon(ICONS.install), "Installa l'app") : null,
    ),
    // pagine statiche del sito pubblicato (nell'app nativa si aprono nel browser di sistema)
    publicBase() ? h('p', { class: 'tip' },
      h('a', { href: `${publicBase()}privacy/`, target: '_blank', rel: 'noopener' }, 'Informativa sulla privacy'), ' · ',
      h('a', { href: `${publicBase()}promo/`, target: '_blank', rel: 'noopener' }, 'Il sito di Mimika')) : null,
  );
}

export function codeModal(ui: UI, onSubmit: (text: string) => void): void {
  const ta = h('textarea', { rows: '4', placeholder: 'Incolla qui il link o il codice ricevuto (sfida, risultato o invito al duello)' });
  const close = ui.modal(h('div', { class: 'code-modal' },
    h('h2', {}, 'Hai ricevuto qualcosa?'),
    h('p', {}, 'Incolla il link di sfida, di risultato o di invito al duello live che ti hanno mandato.'),
    ta,
    h('button', { class: 'btn primary', onclick: () => { close(); onSubmit(ta.value); } }, icon(ICONS.check), 'Apri'),
  ));
  setTimeout(() => ta.focus(), 50);
}

// ---------------------------------------------------------------- passaggio di mano

export function handoffScreen(o: { role: 'def' | 'atk'; title: string; text: string; cta: string; onGo(): void; onBack(): void; extra?: HTMLElement }): HTMLElement {
  return h('div', { class: 'screen center' },
    h('div', { class: `panel handoff ${o.role}` },
      h('div', { class: 'role-badge' }, o.role === 'def' ? 'DIFESA' : 'ATTACCO'),
      h('h2', {}, o.title),
      h('p', {}, o.text),
      o.extra ?? null,
      h('div', { class: 'row' },
        h('button', { class: 'btn ghost', onclick: o.onBack }, icon(ICONS.back), 'Menu'),
        h('button', { class: 'btn primary big-cta', onclick: o.onGo }, o.cta),
      ),
    ),
  );
}

// ---------------------------------------------------------------- risultato

export interface ResultView {
  winnerName: string;
  winnerRole: 'atk' | 'def';
  cause: string;
  shots: number;
  broken: number;
  seconds: number;
  score?: { names: [string, string]; values: [number, number] };
  actions: Action[];
  /** titolo e frase dell'esito al posto di quelli standard */
  title?: string;
  causeText?: string;
  badge?: string;
  /** riga in più sotto le statistiche (record, verifica del replay…) */
  extra?: HTMLElement | null;
}

export function resultScreen(r: ResultView): HTMLElement {
  return h('div', { class: 'screen center' },
    h('div', { class: `panel result ${r.winnerRole}` },
      victoryArt(r.winnerRole),
      h('div', { class: 'role-badge' }, r.badge ?? (r.winnerRole === 'atk' ? "VITTORIA DELL'ATTACCO" : 'VITTORIA DELLA DIFESA')),
      h('h2', {}, r.title ?? `${r.winnerName} vince!`),
      h('p', { class: 'cause' }, r.causeText ?? (r.winnerRole === 'atk' ? `Mimika è stata presa: ${r.cause}.` : `Mimika è salva: ${r.cause}.`)),
      h('div', { class: 'stat-row' },
        stat('Colpi', r.shots), stat('Blocchi distrutti', r.broken), stat('Secondi', r.seconds)),
      r.extra ?? null,
      r.score
        ? h('div', { class: 'scoreboard' },
            h('span', {}, r.score.names[0]), h('b', {}, `${r.score.values[0]} – ${r.score.values[1]}`), h('span', {}, r.score.names[1]))
        : null,
      h('div', { class: 'actions' }, ...r.actions.map(actionBtn)),
    ),
  );
}

const stat = (label: string, value: number) => h('div', { class: 'stat' }, h('b', {}, String(value)), h('small', {}, label));

/** Esito della verifica del replay di un referto. */
export interface ReplayCheck {
  ok: boolean;
  text: string;
  /** assente se il replay allegato è danneggiato */
  onReplay?: () => void;
}

export function reportScreen(rep: MatchReport, onMenu: () => void, onRevenge: () => void, check?: ReplayCheck | null): HTMLElement {
  const atkWon = rep.w === 'atk';
  return resultScreen({
    extra: check
      ? h('div', { class: `verify ${check.ok ? 'ok' : 'bad'}` }, icon(check.ok ? ICONS.check : ICONS.help), h('span', {}, check.text))
      : h('p', { class: 'tip' }, 'Referto senza replay (versione precedente del gioco): risultato non verificabile.'),
    winnerName: atkWon ? rep.an : rep.dn,
    winnerRole: rep.w,
    cause: rep.c,
    shots: rep.s,
    broken: rep.k,
    seconds: rep.t,
    actions: [
      { label: 'Costruisci la rivincita', sub: 'Nuova fortezza da inviare', ico: ICONS.link, primary: true, onClick: onRevenge },
      ...(check?.onReplay ? [{ label: 'Rigioca la battaglia', sub: 'Guarda come è andata, colpo per colpo', ico: ICONS.replay, onClick: check.onReplay }] : []),
      { label: 'Menu', ico: ICONS.back, onClick: onMenu },
    ],
  });
}

// ---------------------------------------------------------------- condivisione link

/** Condividi (foglio di sistema: plugin nativo nell'app, navigator.share sul web) / Copia / WhatsApp per un link. */
export function shareRow(ui: UI, link: string, shareText: string): HTMLElement {
  const message = `${shareText}\n${link}`;
  return h('div', { class: 'row wrap' },
    canShare() ? h('button', { class: 'btn', onclick: () => void systemShare(message) }, icon(ICONS.share), 'Condividi') : null,
    h('button', { class: 'btn', onclick: async () => ui.toast((await copyText(link)) ? 'Link copiato!' : 'Copia non riuscita: selezionalo a mano.', 'good') }, icon(ICONS.copy), 'Copia'),
    h('a', { class: 'btn', href: `https://wa.me/?text=${encodeURIComponent(message)}`, target: '_blank', rel: 'noopener' }, icon(ICONS.chat), 'WhatsApp'),
  );
}

export function shareScreen(ui: UI, o: { title: string; text: string; link: string; shareText: string; onDone(): void; doneLabel?: string }): HTMLElement {
  const ta = h('textarea', { readonly: true, rows: '3', class: 'link-box' });
  ta.value = o.link;
  return h('div', { class: 'screen center' },
    h('div', { class: 'panel share' },
      h('h2', {}, o.title),
      h('p', {}, o.text),
      ta,
      shareRow(ui, o.link, o.shareText),
      h('p', { class: 'tip' }, 'Il link contiene tutti i dati: nessun server li vede (viaggiano dopo il simbolo #).'),
      h('button', { class: 'btn primary', onclick: o.onDone }, o.doneLabel ?? 'Fatto'),
    ),
  );
}
